quests[9461] = { id = 9461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr sollt wissen, dass der Prophet nach Euch gefragt hat, da er von Euren Erfolgen in Euren Prüfungen erfahren hat. Die Erschaffung Eures Feuertotems muss warten, bis Ihr mit ihm gesprochen habt.\n\nDies ist eine seltene Ehre; geht sofort zur Exodar, um so schnell wie möglich mit ihm zu sprechen!", sourceObjective = "Geht zu Prophet Velen in der Halle des Lichts in der Exodar.", completion = "Hallo, {name}, ich habe Euch erwartet. Heute scheint Euer Tag zu sein, nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[9462] = { id = 9462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "{name}! Es ist an der Zeit, dass Ihr weitere Ausbildung im Weg der Geister erhaltet. Ihr solltet mit Tuluun, dem Schamanen in der Azurwacht, sprechen. Er kann Euch in dem Verständnis und der Beherrschung der Macht des Feuers unterweisen.", sourceObjective = "Geht zu Tuluun in der Azurwacht auf der Azurmythosinsel.", completion = "Hallo, {name}, ich habe Euch erwartet. Ich hoffe, Ihr seid bereit, Eure Ausbildung fortzusetzen. Die nächste Aufgabe wird schwierig werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9463] = { id = 9463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medizinische Notwendigkeit", description = "Ich habe herausgefunden, dass die Ranken der Pflanzenkreaturen, den sogenannten Peitschern, auf dieser Insel eine regenerierende Eigenschaft besitzen. Wenn man die Ranken richtig verarbeitet, kann man aus ihnen eine hochwirksame Heilsalbe herstellen. Durch die vielen verletzten Draenei, die ständig in der Azurwacht eintreffen, sind unsere Vorräte an Heilmitteln beinahe erschöpft.\n\nUnser besonderer Gast wurde erst gestern schwer verletzt und bewusstlos am Kristallfluss gefunden. Bringt mir die Wurzeln und wir können sie möglicherweise retten.\n\nHaltet südlich und östlich von hier nach den Lauerwurzkreaturen Ausschau, {class}. Ihr dürft keine Zeit verlieren!", sourceObjective = "Anachoret Fateema bei der Azurwacht möchte, dass Ihr für sie 8 Lauerwurzranken sammelt.", progress = "Ich fürchte, ihr Zustand verschlimmert sich zusehends.", completion = "Lasst uns hoffen, dass diese Salbe ihren Lebenswillen neu belebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9464] = { id = 9464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr sollt noch einmal auf die Probe gestellt werden. Diesmal ist es das chaotische Element des Feuers, das Ihr verstehen müsst, wenn Ihr ein Totem erstellen wollt, um dessen Energien zu nutzen.\n\nIm Nordosten entlang der Küste gibt es einen heiligen Ort des Feuers, den Glutgrund. Inmitten der verbrannten Bäume wacht Glutos, ein besonders mächtiger und weiser Feuerelementar. Mit ihm müsst Ihr sprechen.\n\nGeht jetzt zu ihm, mögen die Elementargeister von Azeroth mit Euch sein.", sourceObjective = "Sprecht mit Glutos beim Glutgrund auf der Azurmythosinsel.", completion = "Sehe ich richtig, dass das Funkeln in Euren Augen Euren Wunsch heranzuwachsen und zu verstehen widerspiegelt? Gut!\n\nTuluun hat Euch hierher geschickt, da er erkannt hat, dass Ihr fähig seid zu lernen und uns bei einem Problem zu helfen, das durch den Absturz der Exodar verursacht wurde.\n\nWir werden sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9465] = { id = 9465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Einer meiner Brüder, Hauteur, ist verrückt geworden! Zweifellos ist der Absturz Eures Schiffs daran schuld. Er verlangt jetzt, dass ihn die heimischen Eulenbestien verehren.\n\nDas kann nicht so weitergehen! Keiner von uns würde jemals einen Gott verkörpern! Ihr müsst das Gleichgewicht wieder herstellen.\n\nAls Erstes müsst Ihr ihre Ritualfackel finden, welche in Besitz der wahnsinnigen Wildekin innerhalb der Tannenruhfeste im Westen ist.\n\nBringt mir diese Fackel.", sourceObjective = "Erlangt die Ritualfackel wieder und bringt sie zu Glutos beim Glutgrund auf der Azurmythosinsel.", progress = "Habt Ihr die Fackel?", completion = "Seht Ihr? Das Feuer geht niemals aus. Das ist das Werk Hauteurs. Es ist das Symbol seines Hochmuts. Flammen sollen verzehren, was sie selbst brennen lässt und dann sterben, um ein andermal wieder entfacht zu werden.\n\nIch würde Euch ja beim Löschen der Fackel helfen, aber sie muss noch brennen, damit Ihr Euch Hauteur stellen könnt. Lassen wir sie noch ein wenig länger am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9466] = { id = 9466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Schwarzkralle die Wilde", description = "Auf Anweisung des Waldläuferhauptmanns wird hiermit eine Belohnung auf die Erlegung der teuflischen Felsklauenmatriarchin, bekannt als Schwarzkralle die Wilde, ausgesetzt.\n\nSchwarzkralle wurde zuletzt in einer Höhle in der großen Kluft gesichtet. Zum Erhalt der Belohnung müssen die Klauen der Kreatur vorgezeigt werden.", sourceObjective = "Bringt Schwarzkralles Klauen zu Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.", progress = "Gibt es Neuigkeiten über Schwarzkralle?", completion = "Ihr seid ein tapferer {class}, {name}. Diese Bestie hat viele meiner besten Jäger das Leben gekostet.\n\nNehmt die Belohnung, Ihr habt sie Euch redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9467] = { id = 9467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Den Eulenbestien vom Mondschwingenbau auf der Silbermythosinsel, weit im Südwesten, wurde weisgemacht, dass Hauteur ein Gott sei, den es zu huldigen gilt. In Wirklichkeit ist er ein abtrünniger Elementar, den man von seinem Leid erlösen muss. Diese Fackel ist der Schlüssel zu seinem Niedergang.\n\nHauteur verlangt von den Eulenbestien die regelmäßige Entzündung eines Feuers zu seinen Ehren. Sobald Ihr es entfacht, wird er kommen. Tötet ihn und bringt mir seine Asche. Verwendet die Kugel in Eurer Tasche und ich werde Euch hierher zu mir zurückbringen.", sourceObjective = "Besorgt Euch Hauteurs Asche und bringt sie zusammen mit der Ritualfackel zu Glutos beim Glutgrund auf der Azurmythosinsel. Vergesst nicht, dass Ihr die Kugel der Rückkehr verwenden könnt, um zu Glutos zurückzukehren, sobald Ihr die Asche habt.", progress = "Sprecht erst wieder mit mir, wenn Ihr Hauteurs Asche habt.", completion = "Ihr habt heute eine besonders wichtige Lektion gelernt. Es ist die Geschichte vom Ende und vom Neuanfang.\n\nAls wir uns das erste Mal unterhielten, sagte ich Euch, dass das Feuer nicht nur Zerstörung verkörpert, sondern auch die erneuernde Kraft der Elemente. Durch Euer Handeln habt Ihr Hauteur zerstört und gleichzeitig gerettet, auf das er aus seiner Asche wiedergeboren wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[9468] = { id = 9468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr habt heute bei dem Versuch, Eure Bindung zum Feuer zu verstehen, etwas Großartiges geleistet. Vergesst nicht, dass Ihr ihm stets den gebührenden Respekt erweisen sollt, um Euch nicht selbst daran zu verbrennen.\n\nIch habe einen Teil von Hauteurs Asche für Euch aufgehoben. Verwendet ihn, wenn Ihr Euer Feuertotem erstellt und vergesst nichts von dem, was Ihr auf Eurem Weg hierher gelernt habt.\n\nKehrt jetzt zu Tuluun zurück.", sourceObjective = "Bringt Hauteurs Asche zu Tuluun in der Azurwacht auf der Azurmythosinsel.", progress = "Ihr scheint Euch an ein paar Ecken versengt zu haben. Wie erging es Euch bei der Zusammenkunft mit der Flamme, {class}?", completion = "Ihr habt das reinigende Feuer der Zerstörung erfahren und seid erneuert worden, {name}. Dies ist nichts im Gegensatz zu dem Elend, das die {race} derzeit erleiden. Ihr habt Hauteur vor sich selbst gerettet und somit Eure Bindung zu dem Element des Feuers in dieser Welt gesichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[9469] = { id = 9469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federbarts Unterstützung", description = "Sollte ich endlich eine Audienz bei Falstad Wildhammer gewährt bekommen, hoffe ich einen der besten Fürsprecher der Wildhammerzwerge an meiner Seite zu haben, {name}.\n\nFederbart genießt bei seinen Leuten hohes Ansehen, sei es wegen seiner legendären Ausbildungsmethoden für Greifen oder wegen seiner Weisheit. Wenn jemand Falstad Wildhammer überzeugen kann, dann er.\n\nIch würde ihn ja gerne selbst aufsuchen, allerdings darf ich den Nistgipfel nicht verlassen, solange ich meine Audienz erwarte. Sucht Federbart bei seiner Wohnstätte im Süden auf und fragt ihn, ob er an meiner Seite aussagen möchte.", sourceObjective = "Geht zu Federbarts Hütte und stattet dem Zwerg dort einen Besuch ab. Solltet Ihr ihn nicht dort antreffen, so sucht nach Hinweisen auf seinen Verbleib.", completion = "Federbarts Tagebuch weist relativ viele neue Einträge auf. Ihr blättert durch die letzten paar Seiten und beginnt nach Hinweisen über seinen Verbleib zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9470] = { id = 9470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geste des guten Willens", description = "Das zerklüftete Gebiet des Hinterlands ist nicht nur das Zuhause der Zwerge des Wildhammerklans und ihrer Greifen, sondern auch einiger Waldtrollstämme.\n\nDie Trolle betrachten die Wildhämmer als Besatzer ihres Heimatlands und lassen keine Gelegenheit aus, um die Zwerge zu belästigen, indem sie die Greifennester angreifen. Ein Weg uns in den Augen der Wildhämmer zu beweisen ist, diese Angriffe zum Ende zu bringen, indem wir einen Anführer der Bleichborken, Hexendoktor Mai'jin, töten. Er befindet sich in einer Höhle in Bogens Kante, westlich von Shadra'Alor.", sourceObjective = "Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr Hexendoktor Mai'jin und seine Spinne Tcha'kaz tötet.", completion = "Gut gemacht, {name}. Die Wildhämmer werden sich sehr darüber freuen, dass sie den Bleichborken nicht alleine gegenübertreten müssen. Wenn sie sehen, dass die Allianz ein verlässlicher Partner im Schutz der Greifen ist, gehen sie vielleicht eher auf unser Angebot ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9471] = { id = 9471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Raubtiere zur Beute machen", description = "Die Wildhammerzwerge sind die Begleiter, Hüter und Ausbilder der Greifen. Die Greifen haben genügend Feinde, vor allem unter den Stämmen der Waldtrolle.\n\nManchmal stammt die Gefahr aber auch von natürlichen Feinden, wie zum Beispiel den Wölfen. Ein einzelnes Tier ist kein erstzunehmender Gegner für einen Greifen, aber in letzter Zeit werden die Greifen immer häufiger von Rudeln angegriffen, da ihre natürliche Beute knapp wird. Die Wölfe auszulöschen könnte wesentlich zur Sicherheit der Greifen beitragen und uns bei den Wildhämmern sehr beliebt machen.", sourceObjective = "Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr 10 räudige Silbermähnen und 5 Silbermähnenwölfe tötet.", completion = "<Botschafter Rualeth nickt, als Ihr ihm Euren Bericht übergebt.>\n\nIhr habt gute Arbeit geleistet. Das Auslöschen der Silbermähnen wird von den Wildhämmern nicht unbemerkt bleiben. Wenn ich mich mit ihren Anführern treffe, werden Eure Taten sicher ein gutes Licht auf die Allianz werfen. Bitte nehmt diese Bezahlung als kleines Zeichen meiner Dankbarkeit an, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9472] = { id = 9472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelions Geliebte", description = "Bei all den wichtigen Dingen, die er zu tun hatte, fand Arelion immer noch genug Zeit seine Geliebte zu besuchen!\n\nJetzt wird mir alles klar. Viera Sonnenwisper, dieses widerwärtige Frauenzimmer... wir werden Ihr beibringen, sich niemals in die Angelegenheiten einer Magistrix einzumischen.\n\nNehmt diese Schriftrolle und findet Viera. Sucht einen Weg, sie vom Dorf wegzulocken und benutzt die Schriftrolle.\n\nArelion erwähnte, dass sie einem bestimmten Wein, der von den Druiden des Cenarius angebaut wird, nicht widerstehen kann. Vielleicht findet Ihr ein wenig davon bei der Zuflucht des Cenarius in den Zangarmarschen westlich von hier.", sourceObjective = "Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr Viera Sonnenwisper aus der Siedlung herauslockt und Carindas Rolle der Vergeltung auf sie anwendet.", completion = "Hervorragend! Diese hinterhältige Göre wird sich mit niemandes Ehemann mehr davonschleichen.\n\nHier habt Ihr eine Kleinigkeit für Eure Mühen. Ich vertraue darauf, dass diese Angelegenheit unter uns bleibt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9473] = { id = 9473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine alternative Alternative", description = "Der Zustand des Mädchens ist bereits zu kritisch, als dass einfache Salben sie noch retten könnten. Es gibt möglicherweise noch einen anderen Weg...\n\nDer Wald von Azurmythos birgt viele Geheimnisse, eines davon ist eine seltene Pflanze, das Azurlöwenmäulchen, die viele als Allheilmittel ansehen.\n\nSie ist leicht zu entdecken, da sich ihr Aussehen sehr stark von allen anderen Pflanzen unterscheidet und sie ausschließlich im Schatten der Azurkiefer wächst. Beeilt Euch!\n\nUnd {name}, nehmt Euch vor den Drescherwurzkreaturen in Acht! Sie ernähren sich von den Azurlöwenmäulchen.", sourceObjective = "Daedal bei der Azurwacht möchte, dass Ihr für ihn 5 Azurlöwenmäulchen sammelt.", progress = "Verschwendet keine Zeit, Junge.", completion = "Seht, wie die Pflanze ihre wundersame Wirkung entfaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9474] = { id = 9474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal des Lichtbringers", description = "In der kurzen Zeit, die ich in Azeroth verbracht habe, habe ich viele seiner Helden studiert. Einer von ihnen, Uther Lichtbringer, hebt sich von allen anderen ab. Nachdem er viele Jahre ein Held war, wurde er am Ende von seinem viel versprechendsten Schüler, Arthas, verraten.\n\nZu seiner Ehre würde ich gerne etwas, das er verloren hat, zu seinem Grabmal bringen. Man sagt, dass der Scharlachrote Kreuzzug eines seiner heiligen Relikte oben in dem Wachturm in der Nähe von Herdweiler aufbewahrt.\n\nBitte, {class}, geht und holt es zurück.", sourceObjective = "Besorgt das Mal des Lichtbringers und kehrt dann zu Anachoret Truuen im Zugwindlager in den westlichen Pestländern zurück.", progress = "Das Mal des Lichtbringers ist ein mächtiges Symbol für Uthers Glaube an das Licht.", completion = "Vielen Dank, {class}! Dass Ihr dieses heilige Symbol zurückgebracht habt, bedeutet mir und allen anderen, die die Erinnerung an Uther Lichtbringer in Ehren halten, sehr viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9475] = { id = 9475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedererlangen der Eier", description = "Die Begutachtung der Überreste lässt vermuten, dass es sich bei dem zerschmetterten Skelett um Federbart handeln muss. Eine der skelettierten Hände umklammert fest ein zerfetztes und schmutziges Stück Papier. Ihr zieht es vorsichtig heraus und rollt es auf. Zum Vorschein kommt eine handgezeichnete Karte und ein paar eilig hingekritzelte Notizen.\n\nDie Karte scheint eine Skizze von Shadra'Alor und seinen drei Tempeln zu sein. Mehrere 'X' auf der Zeichnung markieren vermutlich die Lage gestohlener Eier. Ihr packt die Karte ein und plant, sie an einem sicheren Ort genauer zu untersuchen.", sourceObjective = "Erlangt 5 Greifeneier und bringt sie zu Botschafter Rualeth beim Nistgipfel.", progress = "Euer Gesichtsausdruck verrät, dass Ihr Überbringer schlechter Nachrichten seid. Was habt Ihr herausgefunden?", completion = "<Ihr überreicht dem Botschafter die Eier und berichtet von den Entdeckungen bei Federbarts Hütte und Shadra'Alor.>\n\nDie Bleichborken haben Federbart getötet?\n\n<Auf Rualeths Gesicht legt sich ein Ausdruck des Grauens, als Ihr ihm vom Tod des Zwergs und den Auswirkungen auf seine Mission erzählt.>\n\nIch kann verstehen, warum er sich auf die Suche nach den Eiern machen wollte, aber ich wünschte, er hätte noch jemanden mit sich genommen. Sein Tod wird Falstad Wildhammer zweifellos erzürnen, einen Vergeltungsschlag gegen die Trolle zur Folge haben und meine Audienz nun endgültig aufschieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9476] = { id = 9476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Federbart", description = "Die jüngsten Einträge in Federbarts Tagebuch beschreiben seine Sorge bezüglich der immer häufigeren Überfälle von Bleichborkentrollen auf die Greifen im Wildhammergebiet und die sich mehrenden Diebstähle von Eiern. Die Untersuchung der kleineren Bleichborkensiedlungen brachte keine Informationen zu Tage.\n\nDer letzte Eintrag handelt von Federbarts Verdacht, dass ein Hexendoktor der Bleichborken, namens Mai'jin, hinter all den Raubzügen steckt. Am Ende des Eintrags, steht mit hastig geschriebenen Worten, dass der Zwerg die Absicht hat, nach Shadra'Alor zu gehen und nach den Eiern zu suchen.", sourceObjective = "Reist nach Shadra'Alor und sucht nach Spuren von Federbart.", completion = "Auf dem Altar liegen Skelettknochen, die von einem männlichen Zwerg zu stammen scheinen. Eine Identifikation ist zwar nicht mehr möglich, aber Ihr beschließt, die Überreste nach Hinweisen zu untersuchen, die auf Federbart verweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9483] = { id = 9483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die feinen Freuden im Leben", progress = "Nur weil wir auf dieser Pilgerfahrt sind, heißt das noch lange nicht, dass wir alle Freuden im Leben aufgeben müssen. Ich hatte schon seit Ewigkeiten keinen guten Wein mehr.\n\nIch könnte im wahrsten Sinne des Wortes für einen gute Flasche Cenarischer Geistertropfen töten!\n\nIch weiß, ich weiß, wie unpassend von mir, ein Nachtelfengebräu zu genießen.", completion = "Vielleicht werden wir ja doch noch Freunde. Folgt mir! Wir wollen schließlich nicht mit den anderen teilen müssen, oder?" }
quests[9484] = { id = 9484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr habt zweifellos schon Tiere für Euren Schutz und für Euren Lebensunterhalt getötet, jedoch seid Ihr erst jetzt bereit, Euch mit ihnen anzufreunden und sie zu zähmen, um von ihrer Stärke Gebrauch zu machen. Ich kann Euch darin ausbilden.\n\nNehmt diese magische Zähmerrute, sie wird ein wildes Tier vorübergehend an Euch binden und an Eurer Seite kämpfen lassen. Beginnt mit einem wahnsinnigen Drachenfalken, ein recht gefügiger Vogel, den man außerhalb der Zuflucht der Weltenwanderer findet. Kehrt anschließend zu mir zurück.", sourceObjective = "Verwendet die Zähmerrute, um einen wahnsinnigen Drachenfalken zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", progress = "Konntet Ihr den Drachenfalken gefügig machen?", completion = "Ihr habt zahlreiche Kratzer und Bisse von dem Drachenfalken in Kauf genommen, dies steht für Eure Hartnäckigkeit. Seid Ihr stark genug, um noch mehr zu lernen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9485] = { id = 9485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr habt Euch gut geschlagen, {name}. Euer Verständnis für die Wildnis wird rasch größer.\n\nDie Nebelfledermaus ist ein listiger Jäger, sie vereint die Schnelligkeit des Drachenfalken und die Wildheit einer Bachtatze. Man findet die Nebelfledermäuse direkt über dem Elrendar im Süden, wo sie unglücklichen Reisenden auflauern, die in den Geisterlanden umherwandern.\n\nVerwendet diese letzte Zähmerrute, um eine Nebelfledermaus zu bändigen. Kehrt anschließend zu mir zurück.", sourceObjective = "Verwendet die Zähmerrute, um eine Nebelfledermaus zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", progress = "Konntet Ihr die Nebelfledermaus gefügig machen?", completion = "Seht Ihr {name}, ich kann Euch nichts Neues mehr lehren. Ihr wisst bereits, wie man die einst gejagten Kreaturen zähmen kann, jetzt müsst Ihr Euch nur noch einen Verbündeten der Natur aussuchen, der zu Euch passt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9486] = { id = 9486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Die alte Bachtatze ist ein gründlicher und geschickter Jäger. Wenn man sie zähmen möchte, sieht sie einen sofort als Beute. Lasst Euch nicht von Eurem Vorhaben abbringen.\n\nVerwendet die Zähmerrute, um diese große Katze gefügig zu machen und an ihrer Seite zu jagen. Man findet sie überall im Immersangwald, manche sogar ganz nahe bei der Jagdhütte. Kehrt zu mir zurück, wenn Ihr genug gelernt habt.", sourceObjective = "Verwendet die Zähmerrute, um eine alte Bachtatze zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", progress = "Habt Ihr an der Seite der Bachtatze gejagt?", completion = "Ihr habt Stärke und Durchhaltevermögen bewiesen. Euch erwartet nur noch ein letzter Test, bevor Ihr das Zähmen ohne Magie beherrscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9487] = { id = 9487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanhäscher", description = "Arkanhäscher sind magische Kunstwesen mit roher Kraft. Sie sind dick gepanzert und können schwere Schläge austeilen. Eure Zauberkraft gewährt Euch jedoch den Vorteil, ihre Abwehr umgehen und Treffer von ihnen vermeiden zu können, {name}.\n\nReist zum Morgensternturm und sprengt die Arkanhäscher in Stücke! Bei ihren Überresten findet Ihr kristallisierte Fragmente magischer Energie. Sammelt diese und bringt sie zu mir. Den Morgensternturm findet Ihr im Osten, jenseits des Sees.", sourceObjective = "Arkanist Vandril möchte, dass Ihr 10 Arkantrümmer für ihn sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9488] = { id = 9488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine einfache Robe", description = "Die Arkantrümmer, die Ihr gesammelt habt, sind gut geeignet.\n\nGeeignet wofür, möchtet Ihr wissen? Um eine prächtige Robe für <einen/eine:c> {class} wie Euch herzustellen!\n\nAlles, was wir jetzt noch benötigen, ist etwas Leinenstoff und eine Seidendrüse der Spindelweber. Die Seidendrüse bekommt Ihr von einer Spindelweberspinne, vorzugsweise nachdem Ihr diese getötet habt.", sourceObjective = "Arkanist Vandril möchte, dass Ihr ihm 15 Leinenstoff und eine Seidendrüse der Spindelweber bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9489] = { id = 9489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung in der Schneise", description = "{name}, gut, dass Ihr hier seid. Die Geißel überfällt unsere Stadt mit so unendlichem Hass, dass ich befürchten muss, dass die Moral unserer Wache langsam dahinschwindet.\n\nEilt zu der Todesschneise südlich der Stadt, wo Jaela und ihre Waldläufer bereitstehen. Erfüllt sie mit Eurem Segen mit der Macht des Lichts.", sourceObjective = "Wirkt das Machtwort: Seelenstärke auf 6 Waldläufer von Immersang in der Todesschneise.", sourceObjectiveStatus = "unverified-source-field" }
quests[9490] = { id = 9490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Felsklauenmatriarchin", description = "Felsklauen sind bösartige, hinterhältige und grausame Kreaturen. Aber die normalen sind noch harmlose Schoßtierchen im Vergleich zu ihrer Matriarchin, Schwarzkralle der Wilden.\n\nMein Cousin wurde von ihr gefressen. Das war kein schöner Anblick. Ich habe an diesem Tag geschworen, dass Schwarzkralle dafür bezahlen wird. Bringt mir die Krallen dieses Monsters, und ich werde Euch dafür meine Ersparnisse geben. Einverstanden?\n\nIhr werdet ein paar Freunde brauchen, um Schwarzkralle zu töten. Große, starke Freunde mit scharfen Schwertern. Ihr findet das Biest in einer Höhle in der großen Kluft. Viel Erfolg!", sourceObjective = "Besorgt Schwarzkralles Klauen von Schwarzkralle der Wilden in der großen Kluft und bringt sie zu Ikan beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr schon einen Beweis für Schwarzkralles Tod, {name}?", completion = "Ja, an diese scharfen Krallen erinnere ich mich genau!\n\nNehmt diese Belohnung, {name}. Ihr habt eine gefährliche Aufgabe erledigt. Ihr habt Euch jedes einzelne Stück hiervon verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9491] = { id = 9491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gier", description = "Ein reicher, und wenn ich sage 'reich', meine ich 'stinkreicher' Händler kam gestern hier vorbei und erzählte etwas über einen Ring von 'immenser archäologischer Bedeutung', der in einer der zahllosen Grabtruhen in den Amanikatakomben eingeschlossen ist. Wenn er nicht über den Ring sprach, dann darüber, wie viel er dafür bezahlen würde.\n\nIch könnte Euch Diebeswerkzeug vorstrecken, und wenn es Euch gelingt, mir den Ring zu bringen, zahle ich Euch so viel, dass ihr zehn Ringe für Euch selbst kaufen könnt!", sourceObjective = "Eralan in Tristessa möchte, dass Ihr ihr einen gekörnten Goldring aus den Amanikatakomben bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9492] = { id = 9492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal wenden", description = "Die weiterhin bestehende orcische Bedrohung ist eine der traurigen Wahrheiten der Scherbenwelt. Es gab eine Zeit, in der wir Söhne des Lothars glaubten, dass wir die Sicherheit der Ehrenfeste mit unserem Blut erkauft haben, aber es sollte keinen Frieden geben.\n\nDie Söhne werden sich keinem Orc fügen - ob er nun grün, braun oder eben rot sein mag - wir werden sie besiegen oder bei dem Versuch sterben. Wenn wir eine Chance auf den Sieg haben wollen, müssen wir sie in der Höllenfeuerzitadelle bekämpfen. Bringt mir die Waffe ihres selbsternannten \"Kriegshäuptlings\" Kargath Messerfaust, und ich werde Euch reich belohnen.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Truppenkommandant Danath Trollbann in der Ehrenfeste.", progress = "Seid Ihr mit den Überresten von Kriegshäuptling Messerfaust zurück?", completion = "Gut gemacht, {name}. Mit Eurem Sieg in der Höllenfeuerzitadelle haben wir den Orcs großen Schaden zugefügt.\n\nIhr müsst mit Feldkommandeur Romus über das weitere Vorgehen und das Ziel, die Orcs weiter in der Defensive zu halten, sprechen. Jetzt, da wir Verstärkung haben, können wir die Ehrenfeste viel leichter verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9493] = { id = 9493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz der Höllenhorde", description = "Wir wissen herzlich wenig über die Höllenhorde in der Höllenfeuerzitadelle, und die Informationen, die wir haben, wurden teuer mit Blut bezahlt.\n\nDie Truppen der Höllenhorde unter dem Kommando von Kargath Messerfaust sind ein blutrünstiger, schlachterprobter Haufen, der von bösartigen Magiern unterstützt wird. Die Elite dieser Streitkräfte, die Legionäre, Champions und Zenturios der Zerschmetterten Hand, werden von den gewöhnlichen Soldaten gefürchtet und dienen als Offiziere.\n\nAuf sie loszugehen und sie zu vernichten ist der erste wichtige Schritt für einen erfolgreichen Angriff auf die Führung der Höllenhorde.", sourceObjective = "Feldkommandeur Romus in der Ehrenfeste möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet.", completion = "Das sind großartige Nachrichten, {name}. Mit diesen Fortschritten bei der Höllenfeuerzitadelle können wir es vielleicht sogar wagen, die Höllenhorde auch in anderen Orten der Halbinsel und der ganzen Scherbenwelt zu bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9494] = { id = 9494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsglut", description = "Die altmodischen Akademiker Azeroths haben sich schon viel zu lange in ihren Türmen versteckt. Jetzt ist es an mir, ihnen zu zeigen, was hochmoderne Forschung bedeutet! Sie haben Angst, mit dem Feuer zu spielen, und genau das werde ich tun! Das heißt, sobald ich dieses Feuer in die Finger bekomme.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle vollbringt der Großhexenmeister Nethekurse unerreichte magische Meisterleistungen, die von der Macht einer ungewöhnlichen Kohlepfanne noch verstärkt werden. Benutzt dieses Gefäß, um ein Stück Teufelsglut zu fangen, und bringt es zu mir, {name}.", sourceObjective = "Magus Zabraxis in der Ehrenfeste möchte, dass Ihr ihr ein Stück Teufelsglut bringt.", progress = "<Magus Zabraxis schaut zu Amythiel Nebelgänger hinüber und senkt ihre Stimme.>\n\nHabt Ihr die, ähm, Glut?", completion = "Gut gemacht! Ich maße mir nicht an, Nethekurses Meisterwerke nachahmen zu können, aber wir wären dumm, wenn wir die Macht der Teufelsglut außer Acht lassen würden.\n\nEs gibt jedoch einige, die meine Art der Forschung verbieten wollen, deshalb muss ich meine Entdeckungen geheim halten. Bitte erzählt niemandem davon, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9495] = { id = 9495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille des Kriegshäuptlings", description = "Es ist nicht einfach, das orcische Volk von seinen verderbten Blutsverwandten zu befreien, {name}. Kriegshäuptling Thrall hat schon zu viele orcische Helden durch die Hand des Schicksals fallen sehen. Und nun scheint es, als ob auch Kargath Messerfaust ihm zum Opfer gefallen ist.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle hat Kargath sich selbst den Titel \"Kriegshäuptling\" der Höllenhorde gegeben. Er und seine Armee von irren und blutdurstigen Höllenorcs werden nicht ruhen, bis Thrallmar in Trümmern liegt. Kriegshäuptling Thrall hat befohlen, Kargath und seine Streitkräfte koste es was es wolle zu vernichten.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Nazgrel in Thrallmar.", progress = "Habt Ihr einen Beweis für den Sieg über Kargath Messerfaust?", completion = "Das habt Ihr gut gemacht, {name}. In seiner Jugend war Kargath Messerfaust ein vortrefflicher Krieger, ein Held und ein gutes Beispiel für sein Volk.\n\nSein Tod ist für uns alle schmerzhaft, jedoch besonders für Kriegshäuptling Thrall. Was auch immer in seinen letzten Tagen mit ihm geschehen sein mag, wir dürfen nie den Orc vergessen, der Kargath einst war, genauso wenig wie die Lektion, die uns sein Fall sein sollte.\n\nFür Eure Dienste für die Horde werdet Ihr mit einer dieser Waffen belohnt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9496] = { id = 9496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz der Höllenhorde", description = "Von Oberanführer Stümmelfaust mal abgesehen, {name}, ist mit der Höllenhorde nicht zu spaßen.\n\nSoweit wir wissen, sind die Truppen der Höllenhorde unter dem Kommando von Kargath Messerfaust ein blutrünstiger, schlachterprobter Haufen, der von bösartigen Magiern unterstützt wird. Die Elite dieser Streitkräfte, die Legionäre, Champions und Zenturios der Zerschmetterten Hand, werden von den gewöhnlichen Soldaten gefürchtet und dienen als Offiziere.\n\nAuf sie loszugehen und sie zu vernichten ist der erste wichtige Schritt für einen erfolgreichen Angriff auf die Führung der Höllenhorde.", sourceObjective = "Schattenjäger Ty'jin in Thrallmar möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet.", completion = "Ausgezeichnete Arbeit, {name}. Jetzt, da die Legionäre gefallen sind, wird es einfacher, der Höllenhorde auf dem Schlachtfeld zu begegnen, auch wenn sie immer noch ein ernstzunehmender Gegner ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9497] = { id = 9497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emblem der Höllenhorde", description = "Als der Kriegshäuptling von der so genannten Höllenhorde hörte, wurde er sowohl wütend als auch sehr traurig. Wie Rend und seine Hochstapler damals wird auch diese falsche Horde fallen, und ihr Banner wird als Zeichen für die Macht unseres Kriegshäuptlings von den Zinnen der Feste Grommasch wehen.\n\nEs liegt an Euch, in dieser Angelegenheit den Willen des Kriegshäuptlings auszuführen, {name}. Es wird nicht einfach werden, denn das Banner wird von einem Champion der Höllenhorde, bekannt als Kriegshetzer O'mrogg, bewacht. Er wird sich das Banner nicht ohne Kampf nehmen lassen.", sourceObjective = "Tötet Kriegshetzer O'mrogg und besorgt Euch das Banner der Höllenhorde. Kehrt danach zu Oberanführer Hun Stümmelfaust in Thrallmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9498] = { id = 9498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenwacht", description = "Mein Volk hat die Falkenwacht erst kürzlich als Operationsbasis im Südwesten der Höllenfeuerhalbinsel, hinter der Höllenfeuerzitadelle, fertiggestellt. Man wird Euch dort als Verbündeten willkommen heißen, {name}.\n\nWenn Ihr also auf der Suche nach Arbeit seid, reist dorthin und sagt Waldläuferhauptmann Venn'ren, dass ich Euch geschickt habe. Er wird Euch sicherlich eine Aufgabe zuweisen können, die Eurer Fähigkeiten würdig ist.", sourceObjective = "Meldet Euch bei Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.", completion = "Willkommen in der Falkenwacht, {race}. Alle Verbündeten der Horde sind hier willkommen, insbesondere all jene, mit einer Empfehlung von Martik.", sourceObjectiveStatus = "unverified-source-field" }
quests[9499] = { id = 9499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenwacht", description = "Was macht Ihr denn noch hier, {name}? Habt Ihr nicht gehört, dass wir einen anständigen Außenposten der Sin'dorei auf der Höllenfeuerhalbinsel errichtet haben?\n\nIhr wärt doch sicher viel lieber bei den Blutelfen als bei all diesem... Gestank hier. Ihr findet die Falkenwacht im Südosten, hinter der Höllenfeuerzitadelle. Meldet Euch bei Waldläuferhauptmann Venn'ren, er wird sich um Euch kümmern.\n\nDie Straße dorthin ist sehr gefährlich und wird von den Spähern der Allianz überwacht. Reist lieber in Begleitung. Am Besten mit Blutelfen.", sourceObjective = "Reist zur Falkenwacht im Südwesten der Höllenfeuerhalbinsel und meldet Euch bei Waldläuferhauptmann Venn'ren.", completion = "Willkommen in der Falkenwacht, Bruder. Viele andere Blutelfen haben es leider nicht geschafft, heil hier anzukommen.\n\nEs ist eine Schande. Unsere Arbeit in der Scherbenwelt hat doch gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9500] = { id = 9500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Weissager Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?", sourceObjective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9501] = { id = 9501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ein mächtiger Wasserelementar namens Aqueous hat nach Euch verlangt. Scheinbar ist das Element des Wassers auf der Blutmythosinsel aus dem Gleichgewicht geraten, was bei der unnatürlichen Vorliebe der Blutelfen nicht wirklich verwunderlich ist.\n\nIhr findet Aqueous in einem versteckten Riff unter den Wogen vor der Küste im Norden der Blutmythosinsel.\n\nNehmt diesen Trank, er wird Euch auf Eurem Weg zu Aqueous behilflich sein, sobald Ihr in der Nähe des Riffs im Wasser seid.", sourceObjective = "Sprecht mit Aqueous im versteckten Riff bei der Blutmythosinsel.\n\nBereitgestellter Gegenstand:", completion = "Fürchtet Euch nicht, {name}. Wir werden hier mit Hilfe unserer Gedanken miteinander kommunizieren.\n\nIch bin Weissager Nobundo dankbar, dass er Euch zu mir gesandt hat. Etwas verunreinigt das Wasser auf und um die Blutmythosinsel herum. Nicht einmal einem Blinden würde der Effekt entgehen, den diese Störung auf die Kreaturen hat.\n\nIhr und ich werden zusammen gegen diese Verderbnis vorgehen, bevor sie sich noch weiter ausbreitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9502] = { id = 9502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Weissager Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?", sourceObjective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", completion = "So treffen wir uns wieder. Ich habe Eure Fortschritte aus der Ferne beobachtet, {class}, ich bin sehr zufrieden.\n\nEs ist jetzt an der Zeit, dass Ihr mit dem Element des Wassers vertraut werdet. Ihr sollt die Geheimnisse des Wassers erlernen und Euch diesem Wissen widmen, um es mit der Zeit auch beherrschen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9503] = { id = 9503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "In Verbindung mit den anderen Elementen ist Wasser der Quell und die Grundlage allen Lebens. Alle Kreaturen sind darauf angewiesen. Allerdings bringt das Wasser durch die Verunreinigung jetzt auch den Tod.\n\nWir müssen das Ausmaß des Schadens erfassen. Im Südwesten liegt ein derart verderbtes Gewässer, welches mittlerweile als besudelter Teich bekannt ist. Geht dorthin und besorgt Euch besudelte Essenzen von den dort lebenden Wassergeistern.", sourceObjective = "Sammelt 6 besudelte Essenzen ein und bringt sie zu Aqueous im versteckten Riff bei der Blutmythosinsel.", progress = "Habt Ihr die besudelten Essenzen meiner bedauernswerten Schwestern bereits eingesammelt, {name}?", completion = "Ich danke Euch, {class}. Dies sollte für meine Untersuchung der Verunreinigung ausreichen. Schon bald werden wir wissen, auf welche Weise wir vorgehen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9504] = { id = 9504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schlimmer als ich befürchtet hatte. Die Verunreinigung ist hartnäckig und könnte, wenn man nicht rechtzeitig handelt, ungehindert in die Ströme des Meeres fließen und sich somit in ganz Azeroth ausbreiten!\n\nWir brauchen eine Probe reinsten Wassers, um diesem Übel entgegenzuwirken. Auf dem nahegelegenen Kontinent Kalimdor gibt es ein Waldgebiet namens Eschental. Unweit seiner südwestlichen Begrenzung findet Ihr die Sternenstaubruinen.\n\nNehmt diesen Botabeutel und füllt ihn mit Wasser aus dem Brunnen auf der kleinen Insel im Zentrum der Ruinen. Beeilt Euch, {name}!", sourceObjective = "Füllt den leeren Botabeutel und kehrt anschließend zu Aqueous im versteckten Riff bei der Blutmythosinsel zurück.", progress = "Habt Ihr das reine Wasser von den Ruinen?", completion = "Wasser schwindet schnell, vereinigt man aber genug davon, bildet es eine unaufhaltsame Kraft. Es spült Erde und Feuer hinfort und bahnt sich auch durch die Luft seinen Weg.\n\nWir sind diese unaufhaltsame Kraft, {name}, nicht diejenigen, die die Blutmythosinsel vergiftet haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[9505] = { id = 9505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prophezeiung von Velen", description = "Der Prophet sprach von diesem Tag, da auf dieser Insel, in dieser Welt, sich uns unsere Verbündeten offenbaren würden.\n\n\"Man wird uns auf die Probe stellen. Wir werden für die Sünden unserer Vorväter bezahlen...\"\n\nDamals blieb mir der Sinn seiner Worte verborgen; doch in dem Moment, als ich dieses Wesen erblickte, wurde mir die Bedeutung seiner Prophezeiung gewahr. Selbst an diesem Ort verspüre ich noch die schleichende Verderbnis unseres Volkes.\n\nBegebt Euch nach Süden, dort wo wir sie gefunden haben. Findet ihresgleichen und berichtet ihnen von unserem Volk.", sourceObjective = "Daedal möchte, dass Ihr nach Süden reist und die Personen aufsucht, von denen das verletzte Wesen gesprochen hat.", completion = "Ihr sagt, dass Ihr eines unserer Besatzungsmitglieder gefunden habt und dass sie schwer verletzt ist? Ich werde umgehend ein Mitglied meiner Besatzung in Euer Dorf entsenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[9506] = { id = 9506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Anfang", description = "Ich bin Admiral Odesyus vom Marinekommando der Allianz. Eine Plage der besonderen Art zwang uns dazu, an der Küste Eurer Insel vor Anker zu gehen. Es beschämt mich das sagen zu müssen, doch ein paar Goblins haben es irgendwie geschafft, sich als blinde Passagiere in den Frachträumen unserer beiden Schiffe zu verstecken.\n\nLetzte Nacht, als der Großteil der Schiffsmannschaften in den Kojen lag, schlugen sie zu!\n\nSie stahlen unsere Navigationsinstrumente und sprangen von Bord!\n\nAnschließend verschwanden sie im Dickicht, östlich von hier. Werdet Ihr uns bei der Suche nach den Instrumenten behilflich sein? Es wäre eine großzügige Geste von Euch.", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr den von der Venture Co. gestohlenen nautischen Kompass und die nautische Karte wiederbeschafft.", progress = "Hattet Ihr Erfolg, Fremder?", completion = "Ihr seid verdammt einfallsreich! Jetzt, da wir unsere Navigationsinstrumente zurückerhalten haben, sollte es leicht sein, herauszufinden, wie weit wir vom Kurs abgekommen sind.\n\nAber wartet, was ist das? Da ist etwas in der Karte eingerollt. Lasst mich mal sehen...\n\nDas sind Befehle von Mogul Raztunk der Venture Company. Laut diesen Plänen sind sie hier, um die Insel ihrer Kristalle zu berauben und unsere Schiffe zu kapern, wenn sie fertig sind!\n\nBei Bronzebarts buschiger Braue! Deswegen haben sie uns an Land gezwungen? Wie konnten sie von unseren Plänen erfahren?\n\nDas riecht nach einem Verräter...", sourceObjectiveStatus = "unverified-source-field" }
quests[9508] = { id = 9508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ich habe den Ursprung der Verunreinigung gefunden. Es ist das Nebenprodukt eines wahnsinnigen Experiments und Ihr werdet dem Ganzen ein Ende bereiten!\n\nSüdwestlich des besudelten Teichs liegt ein kleines Lager, wo Ihr auf das 'Experiment' von Tel'athion dem Unreinen stoßen werdet. An diesem Ort erzeugt er den Unrat und lässt ihn in die Gewässer der Insel sickern.\n\nVerwendet das reine Wasser aus dem Eschental, um seine Fässer zu zerstören. Das wird ihn sicherlich aus seinem Versteck locken.\n\nWir werden das alles ein für alle Mal beenden!", sourceObjective = "Bringt Tel'athions Kopf zu Aqueous im versteckten Riff bei der Blutmythosinsel zurück.", progress = "Wart Ihr erfolgreich?", completion = "Wir haben es geschafft! Der Katastrophe wurde vorgebeugt und Ihr habt die Erholung der Gewässer von der Blutmythosinsel in Gang gesetzt. Mit der Zeit wird sich das Wasser, in Verbindung mit den anderen Elementen, wieder von selbst heilen.\n\nEs ist wirklich traurig, die Blutelfen sehen einfach nicht, wie sie sich durch die Zerstörung ihrer Umgebung  langsam selbst vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[9509] = { id = 9509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ich habe etwas von dem Wasser aus dem Eschental beiseite gelegt, jedoch nicht, weil ich an Euren Fähigkeiten, die Situation in den Griff zu bekommen, gezweifelt habe. Im Gegenteil, ich wusste, dass Ihr Erfolg haben würdet. Ich wollte lediglich sicherstellen, dass Ihr etwas Besonderes habt, das Ihr zurück zu Nobundo bringen könnt.\n\nHier, {name}, nehmt dieses Fläschchen mit reinstem Wasser. Die Erstellung eines mächtigen Wassertotems ist Euch dadurch gewiss.\n\nWeissager Nobundo erwartet Eure Rückkehr bei der Exodar.", sourceObjective = "Nehmt das Fläschchen mit reinstem Wasser zu Weissager Nobundo innerhalb der Exodar auf der Azurmythosinsel.", progress = "Die Elemente haben mir von großen Taten erzählt, die Ihr vollbracht habt. Kommt, sprecht mit mir.", completion = "Ihr habt eine Weisheit an den Tag gelegt, die Eurem Alter vorauseilt, {name}. Ich kann spüren, dass das Element des Wassers mit Euch zufrieden ist. Es ist eine Ehre für mich, wenn ich das reine Wasser, das Ihr mir gebracht habt, in Euer neues Wassertotem einfließen lassen kann.\n\nVergesst niemals die Lehren des Wassers und Ihr werdet das Element mit der Zeit noch besser verstehen und zu meistern lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9510] = { id = 9510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bälge eines borstigen Grollhufs", description = "Ihr wollt Euch also nützlich machen? Unsere Vorräte an Grollhufbälgen sind sehr knapp, {name}.\n\nWenn Ihr von hier aus nach Südwesten geht, werdet Ihr in der Nähe der Falkenwacht haufenweise borstige Grollhufe finden. Ihre Bälge sind ideal für die Lederverarbeitung. Bringt mir einen Stapel davon und ich werde Euch angemessen belohnen.", sourceObjective = "Versorger Braknar beim Mag'harposten auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 5 Bälge eines borstigen Grollhufs bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9511] = { id = 9511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kargaths Schlachtpläne", description = "Die Dokumente, die Ihr bei Kargath gefunden habt, enthalten genaue Pläne für einen großen Angriff auf die Ehrenfeste." }
quests[9512] = { id = 9512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräckas Jumboeintopf", description = "Der Admiral hat wohl Recht, Ihr seid ziemlich clever. Könnt Ihr Kräcka vielleicht aushelfen?\n\nWenn ich der Mannschaft noch einmal Hühnchen vorsetze, schmeißen se' mich ganz sicher in die Brigg.\n\nHab' gesehen, dass es an der Küste nur so von Kriechern wimmelt! Bringt mir Kriecherfleisch und ich steh' für immer in Eurer Schuld.\n\nHelft Ihr 'nem ehemaligen Piraten aus der Patsche?", sourceObjective = "\"Kräcka\" Aschebäscha bei Odesyus' Ankerplatz möchte, dass Ihr ihm 6 Stücke Raubkriecherfleisch bringt.", progress = "Arrr... Jarr... beim Klabautermann... Eh, 'tschuldigung Junge, ich muss mal wieder 'n bisschen Pirat spielen, bevor ich's ganz vergesse...", completion = "Erste Sahne, Fremder. Das wird helfen, die Moral der Mannschaft wieder mächtig aufzumöbeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[9513] = { id = 9513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Ruinen", description = "Während einige glauben, dass unsere momentane Lage das Resultat einer langen Kette von unglücklichen Ereignissen ist, glaube ich vielmehr, dass wir aus einem bestimmten Grund hier sind. Die unsichtbare Hand des Schicksals hat uns an diesen Ort verschlagen. Die Gründe dafür werden sich uns im Laufe der Zeit offenbaren.\n\nIm Westen liegt eine uralte Stadt der Nachtelfen, heute sind es nur noch von Naga besetzte Ruinen. Ich wäre nachlässig, würde ich tatenlos zusehen, wie die Naga weiterhin das Land meiner Vorfahren mit ihrer Anwesenheit beflecken.\n\nIhr habt Eure Fähigkeiten als {class} unter Beweis gestellt. Nun ehrt mein Volk und reinigt diese Ruinen von seinen unrechtmäßigen Einwohnern.", sourceObjective = "Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr 5 Myrmidonen der Hasspranken, 5 Naga der Hasspranken und 5 Sirenen der Hasspranken tötet.", completion = "Gelobt sei Elune! Mögen die restlosen Geister endlich Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9514] = { id = 9514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenbesetzte Schrifttafel", description = "Es gelingt Euch nicht, die Symbole auf der Schrifttafel zu entziffern. Vielleicht ist die Priesterin in der Lage, die mysteriösen Runen zu entschlüsseln.", sourceObjective = "Bringt die runenbesetzte Schrifttafel zu Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel.", progress = "Ihr habt etwas entdeckt?", completion = "Ich kann diese Runen leider nicht entziffern, doch ich kenne jemanden, der dies zu tun vermag...", sourceObjectiveStatus = "unverified-source-field" }
quests[9515] = { id = 9515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr Sriss'tiz", description = "Eine Nagainvasion wäre ein Desaster, {name}. Ich habe gesehen, was diese Naga anrichten können und ich werde es nicht zulassen, dass sie weiter über unschuldige Wesen herfallen. Ich nehme an, dass dieser Kriegsherr Sriss'tiz sich in einer Höhle versteckt - möglicherweise irgendwo an der Küste im Westen.\n\nMacht Kriegsherr Sriss'tiz ausfindig und beendet seine Herrschaft für immer!", sourceObjective = "Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr Kriegsherr Sriss'tiz tötet.", completion = "Nach dem Tod von Kriegsherr Sriss'tiz, dürfte die Gefahr einer Nagainvasion fürs Erste gebannt sein...\n\nIch muss gestehen, es war falsch von mir, so schlecht über Euch zu denken, {name}. Ihr habt bewiesen, dass Ihr weit mehr seid, als die Brut Archimondes. Bitte nehmt dieses Geschenk der Nachtelfen als ein Zeichen der Freundschaft entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9516] = { id = 9516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Legion", description = "Ich werde Ihre Existenz in dieser Welt nicht tolerieren! Die Brennende Legion hat unser Volk fast ausgerottet, und wir mussten ein neues Zuhause in einer neuen Welt suchen! Dann kamen sie erneut. Und wir haben uns zurückgezogen, immer und immer wieder.\n\nNie wieder!\n\nIm Süden gibt es noch ein Überbleibsel der Legion, in den Regionen, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind. Sie sind von dieser Macht, die einst in Eure Welt eingedrungen ist, übriggeblieben.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt, bevor es zu spät ist!", sourceObjective = "Tötet 6 Mannorocpeitscher, 6 Teufelswachen und 6 Sengende Höllenbestien und kehrt dann zu Verteidiger Vedaar in Waldeslied im Eschental zurück.", completion = "Ihr habt meinen Respekt und meinen Dank, {class}. Vielleicht können wir hier ein neues Zuhause errichten, ohne ein weiteres Mal die Brennende Legion fürchten zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9517] = { id = 9517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schändliche Verschwendung", description = "Willkommen in Waldeslied, {class}. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.\n\nWir werden den Holzfällern des Kriegshymnenklans ihren Überschuss abnehmen und etwas von dem verdorbenen Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre, der es für unsere Zwecke reinigen wird.", sourceObjective = "Bringt 15 Stück Holz des Kriegshymnenklans und 5 Stück verdorbenes Satyrnaarholz zu Knorre in Waldeslied.", progress = "<Das Urtum knarrt, als es sich zu Euch umdreht>\n\nArchitekt Nemos sagte, Ihr brächtet Holz, das Ihr aus dem Lager der Roder und dem verdorbenen Satyrnaar errettet habt.", completion = "Holz, das mit den rohen Klingen der Orcs gefällt wurde, ist genauso verzogen, als wäre es extremen Witterungsbedingungen ausgesetzt worden. Nichts Vernünftiges lässt sich daraus erbauen, doch ich werde es reinigen und Architekt Nemos zurückgeben, auf dass er und seine Mannen es benutzen können. So wird die Tragödie doch ein gutes Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9518] = { id = 9518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agenten der Zerstörung", description = "Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!\n\nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, {name}, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!\n\nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!", sourceObjective = "Schildwache Luciel Sternwisper in Waldeslied möchte, dass Ihr Vorarbeiter Gorthak, 2 Schredder des Kriegshymnenklans, 5 Roder der Horde und 10 Späher der Horde tötet.", completion = "Endlich haben wir ein Zeichen gesetzt, das die Orcs nicht ignorieren können. Jeder Vorarbeiter oder Großknecht, der einen Fuß in das Lager setzt, um Gorthak zu ersetzen, wird meinen Zorn zu spüren bekommen!\n\nWir müssen unseren Vorteil ausnutzen, {name}, und nicht ruhen, bevor das Holzfällerlager des Kriegshymnenklans nichts mehr als eine weit entfernte Erinnerung ist und junge Bäume ihre Wurzeln in diesen Boden schlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9519] = { id = 9519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Kelch", description = "Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.\n\nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, {name}.", sourceObjective = "Bringt Elunes Kelch zu Kayneth Stillwind in Waldeslied.", progress = "Könnt Ihr ihn fühlen, {name}, den Hauch von Verderbnis im Wind? Wenn wir nichts tun, wird er noch stärker werden. Deshalb suche ich Elunes Kelch. Konntet Ihr ihn finden?", completion = "Ausgezeichnete Arbeit, {name}. Es schlummert eine deutliche Macht in ihm, die nicht einmal die Verderbnis der Satyrn trüben kann. Seht Ihr, wie er immer noch glänzt, nach all den Jahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[9520] = { id = 9520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Pläne", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise in der Allgemeinsprache verfasst wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf Waldeslied im Norden, wo gerade eine neue Draeneisiedlung errichtet wird.\n\nVielleicht ist Verteidiger Vedaar in Waldeslied daran interessiert?", sourceObjective = "Bringt die teuflischen Pläne zu Verteidiger Vedaar in Waldeslied im Eschental.", progress = "Was habt Ihr da, werter Herr?", completion = "Bei den sieben Kristallen von Ata'mal, das kann nicht sein! Sie planen uns hier in Waldeslied anzugreifen?!\n\nNicht solange ich hier wache!\n\n<Verteidiger Vedaar zerknüllt die Pläne mit dem Dämonengekritzel in seiner Faust.>\n\nNein. Das werden wir nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9521] = { id = 9521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht von der Nordfront", description = "Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur von Waldeslied aus geführt, {name}. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.\n\nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber Waldeslied nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?", sourceObjective = "Bringt Schildwache Luciels Bericht zu Schildwache Weltensang im Hain der Silberschwingen.", progress = "Was habt Ihr da, {class}?", completion = "Vielen Dank für diesen Bericht, {name}. Nach dem, was Schildwache Luciel schreibt, scheint es, als wären unsere schlimmsten Befürchtungen wahr geworden. Mit jedem Fortschritt, den wir machen, scheint die Horde umso entschlossener, so viel Schaden wie möglich anzurichten.\n\nWir können es uns nicht leisten, klein beizugeben. Das Schicksal des Landes unserer Vorfahren liegt im Gleichgewicht der Natur. Wenn wir mehr von Eurer Sorte an der Front hätten, könnten wir sicher triumphieren. Werdet Ihr Euch unserem Kampf anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9522] = { id = 9522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder!", description = "{name}, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Ihr müsst losziehen und ihre Anführer erschlagen. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des treibenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonenstieg. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals der Horde für Grom Höllschrei.", sourceObjective = "Tötet Gorgannon und Diathorus den Sucher und kehrt danach zu Verteidiger Vedaar in Waldeslied im Eschental zurück.", completion = "Nie wieder wird uns die Brennende Legion hier bedrohen! Ihr habt uns vor einem Kampf gerettet, den wir sicher verloren hätten, {class}.\n\nIch schulde Euch meinen persönlichen und den Dank der Hand von Argus. Es ehrt mich, Euch auf unserer Seite zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9523] = { id = 9523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Handhabung für kostbare und zerbrechliche Dinge", description = "Die Priesterin sagte mir, dass die Ruinen im Westen die Überreste einer Nachtelfenkultur sind. Das erinnerte mich wiederum an etwas, was mein Paps immer über Nachtelfenruinen zu sagen pflegte: \"Kleiner, wenn du Nachtelfenruinen siehst, dann sind bestimmt auch Nachtelfenrelikte in der Nähe.\"\n\nWas für ein Zwerg wäre ich wohl, wenn ich nicht die erste Person anstellen würde, die mir über den Weg läuft, um für mich nach Nachtelfenrelikten zu graben? Los jetzt!", sourceObjective = "Archäologe Adamant Eisenherz bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm 8 uralte Relikte bringt.", progress = "Kommt nicht ohne uralte Relikte zurück.", completion = "Mein Paps wäre stolz! Sein Junge hat bei den ersten Nachtelfenruinen, auf die er gestoßen ist, das große Los gezogen... dank Eurer Hilfe natürlich. Ja, macht Euch keine Sorgen, ich werde Euch nicht von der Entdeckung ausschließen. Euer Name ist {name}, stimmt's? In Eisenschmiede werden alle von Euch hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[9524] = { id = 9524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Zitadelle", description = "Allianztruppen, hier?! Hört mir genau zu, {class}.\n\nKargath hat viele unserer Kämpfer gefangen genommen. Unter ihnen ist auch Hauptmann Alina, einer unserer wichtigsten Offiziere. Rettet sie, bevor sie hingerichtet wird.\n\nMacht Euch um mich keine Sorgen, ich komme hier schon heraus, lasst mich nur etwas Luft schnappen.", sourceObjective = "Rettet Hauptmann Alina aus der Höllenfeuerzitadelle, bevor sie hingerichtet wird.\n\nUm diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad 'Heroisch' betreten.", completion = "Ich danke Euch, {name}. Eigentlich hatte ich nicht mehr mit dem Eintreffen einer Rettungstruppe gerechnet.\n\nIch werde die überlebenden Gefangenen versammeln und sie zur Ehrenfeste zurückführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9525] = { id = 9525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Zitadelle", description = "Ich hatte Glück und konnte Kargaths Verlies entkommen, {name}. Die Hinrichtung der meisten Gefangenen wurde bereits angesetzt, unter ihnen befindet sich einer unserer wichtigsten Offiziere.\n\nHauptmann Knochenbrechers Tod wäre für uns ein schwerer Schlag. Tut alles in Eurer Macht stehende, um ihn vor seinem Schicksal zu bewahren. Ich bin zu schwach, um weiter zu machen...", sourceObjective = "Rettet Hauptmann Knochenbrecher aus der Höllenfeuerzitadelle, bevor er hingerichtet wird.\n\nUm diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad 'Heroisch' betreten.", completion = "Ihr habt meinen Tag gerettet, {class}. Wenn ich sterbe, dann auf dem Schlachtfeld... bedeckt von dem Blut meiner Feinde, werde ich sie mit mir in den Abgrund reißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9526] = { id = 9526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Dämonenhügels", description = "Kleines Wesen. Im Süden gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.\n\nKönntet Ihr etwas unternehmen, um das Land zurückzuerobern?\n\nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.", sourceObjective = "Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen und kehrt dann zu Knorre in Waldeslied im Eschental zurück.", completion = "Gut. Auch wenn es vielleicht lange Zeit dauern mag, bis aus den Setzlingen Uralte werden, werden sie uns dann im Kampf gegen die Dämonen am Dämonenhügel helfen können.\n\nGeht in Frieden, kleiner Bruder.", sourceObjectiveStatus = "unverified-source-field" }
quests[9527] = { id = 9527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was noch bleibt", description = "Wir lebten viele Jahre in Frieden mit den Kreaturen dieser Insel. Ihr könnt Euch vorstellen, wie überrascht ich war, als sie den Strand stürmten und uns angriffen.\n\nIch habe mich mit Händen und Füßen gewehrt, wurde aber sofort überwältigt. Als ich auf Grund der zahlreichen Schläge in Ohnmacht fiel, betete ich, dass meine Familie nicht leiden muss.\n\nIch erwachte und alles war ruhig. Der Sand war rot, vor Blut getränkt - mit ihrem Blut. Man hatte sie vollständig verschlungen.\n\nIch sehne mich nicht nach Rache, {name}. Ich wünsche mir nur, dass man mir ihre Überreste bringt, damit ich sie ordnungsgemäß bestatten kann.", sourceObjective = "Cowlen auf der Azurmythosinsel möchte, dass Ihr ihm die Überreste von Cowlens Familie bringt.", progress = "Meine Frau hieß Thalrisa und meine Tochter Magwin.", completion = "Ich danke Euch, {name}. Ihre Geister können nun in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9528] = { id = 9528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hilferuf", description = "Meine Familie wurde vor einigen Wochen von den Murlocs und Eulkin dieser Insel überfallen. Ich schaffte es zu fliehen, aber ich glaube, dass mein Vater und meine Mutter getötet wurden. Ich weiß nicht, was ich jetzt tun soll, aber ich muss versuchen, zurück zu meinem Zuhause zu gehen - oder was davon übrig ist... Könnt Ihr mich durch den Wald begleiten?", sourceObjective = "Begleitet Magwin über die Insel zu ihrem Zuhause.", progress = "Seid gegrüßt, {name}.", completion = "<Freudentränen strömen über Cowlens Gesicht.>\n\nWie kann ich Euch dafür jemals genug danken, {name}? Bitte, nehmt dieses Erbstück. Es symbolisiert die heiligen Bande der Freundschaft, sowie das Vertrauen und die Verbundenheit zwischen den Nachtelfen. Ihr seid wie ein Bruder für mich - vom heutigen Tag bis in alle Ewigkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[9529] = { id = 9529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stein", description = "Ich bin mir sicher, dass Euer Wichtel sich als nützlicher und manchmal auch unterhaltsamer Begleiter bewiesen hat. Es ist jetzt an der Zeit, dass Ihr einen mächtigeren Dämonen zu beherrschen lernt: den Leerwandler.\n\nReist bis zu dem Punkt der Todesschneise, an dem sie vom Elrendar gekreuzt wird. Macht direkt südlich vom Fluss einen der blauen glühenden Steine ausfindig und nehmt ihn. Euer Weg wird sich Euch dort offenbaren.", sourceObjective = "Beschafft Euch einen Leerstein von der Todesschneise.", completion = "Als Ihr in den Stein blickt, scheint sich Eure Sicht zu verklären...", sourceObjectiveStatus = "unverified-source-field" }
quests[9530] = { id = 9530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Plan aus Hecken", description = "Ich habe eine ganze Zeit nun darüber gegrübelt, aber es stellt sich als wahr heraus.\n\nEs gibt einen Verräter unter uns.\n\nDie Pläne, die von den Goblins zurückgelassen wurden, bestätigen diesen Komplott. Da ich nicht weiß, wer es sein könnte, benötige ich Eure Hilfe, um den Verräter auszumachen. Keinem aus meiner Mannschaft kann vertraut werden.\n\nFür ein gelungenes Unterfangen benötige ich einen ausgehöhlten Stamm und Laub. Sucht in der Nähe der Holzarbeiter nördlich von uns nach dem Baumstamm. Das Laub müsst Ihr selbst auftreiben. Durchforstet den Wald.", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm einen ausgehöhlten Stamm und 5 Laubhaufen bringt.", progress = "Ich liebe es, wenn ein Plan aufgeht...", completion = "Ich muss Euch warnen, das, was ich als nächstes von Euch verlangen werde, ist sehr gefährlich. Ich würde es Euch nicht verdenken, wenn Ihr mir dabei lieber nicht aushelfen wollt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9531] = { id = 9531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laubangriff", description = "Der Verräter wird sich den Plänen zufolge mit dem Anführer der Goblins, Geezle, bei einer Bucht auf der westlichen Insel treffen. Ihr müsst zu diesem Treffen gehen, {name}.\n\nErinnert Ihr Euch an den Stamm und das Laub? Ihr müsst Euch damit verkleiden! Es ist die perfekte Tarnung.\n\nGeht zur Bucht und haltet nach einer Nagaflagge Ausschau. Seht Ihr die Flagge, so wurde ein Treffen arrangiert. Legt die Verkleidung an, wenn Ihr die Flagge seht, und wartet. Der Verräter wird sich früher oder später zeigen. Lasst das Treffen enden und kehrt anschließend mit der Identität des Schufts zu mir zurück.", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr das Treffen beobachtet, das Geezle und der Verräter gemeinsam ausgemacht haben.\n\nKehrt zu ihm zurück, wenn Ihr ihm die Identität des Verräters mitteilen könnt.", progress = "Der Verräter wird noch bereuen, dass er sich mit dem Marinekommando der Allianz angelegt hat!", completion = "Ich kann es nicht glauben! Der Gnom war es, die ganze Zeit über... Ich hätte es wissen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9532] = { id = 9532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Keltus Dunkellaub", description = "{name}, einer unserer Späher nimmt seine Pflichten ein wenig zu ernst. Er bewacht unsere Feinde ohne Unterlass, erstattet uns aber keine Berichte darüber.\n\nIhr müsst diesen Spion, Keltus Dunkellaub, finden und überzeugen, damit er seinen Bericht aushändigt und so schnell wie möglich zu mir zurückkommt. Ihr findet ihn weit im Südwesten, wo der Elrendar sich teilt und um Goldnebel herum fließt. Er beobachtet die Nachtelfen von An'daroth und hält sich sicher in ihrer Nähe auf.", sourceObjective = "Macht Keltus Dunkellaub ausfindig.", completion = "Ich hoffe Ihr könnt sehen, dass ich verdeckt arbeite... zumindest hatte ich das.", sourceObjectiveStatus = "unverified-source-field" }
quests[9533] = { id = 9533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Meine Leute haben im Osten des Eschentals mit Hilfe der Kaldorei eine wichtige Entdeckung gemacht.\n\nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, {name}, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er bat mich, <jeden Mann, der/jede Frau> die; Interesse hat, zu ihm zu schicken.", sourceObjective = "Geht nach Waldeslied und sprecht mit Architekt Nemos.", completion = "Es ist schön, einen Neuankömmling hier in Waldeslied begrüßen zu dürfen.\n\nVerteidigerin Palanaar sendet so viel Hilfe, wie sie aufbringen kann, und jede helfende Hand ist willkommen.\n\nSchaut Euch um, {class}. Es ist vielleicht noch nicht viel, aber mit der Zeit und der Hilfe unserer Nachtelfenverbündeten werden wir eine Siedlung errichten, die es wert ist, Zuhause genannt zu werden. Es gibt hier viel zu tun, und für jede Hilfe, die Ihr uns leisten könnt, sind wir sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9534] = { id = 9534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Legion", description = "Die Überreste der Brennenden Legion haben Überfälle auf das Holzfällerlager des Kriegshymnenklans durchgeführt!\n\nEs ist an der Zeit, sie dafür bezahlen zu lassen!\n\nDie Dämonen greifen von den Gebieten im Osten, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind, an.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt und erlangt Ruhm für Euch selbst und für die Horde!", sourceObjective = "Tötet 6 Mannorocpeitscher, 6 Teufelswachen und 6 sengende Höllenbestien und kehrt dann zu Valusha im Splitterholzposten in Eschental zurück.", completion = "So ist es schon besser! Nichts ist so gut, wie unsere Welt von einem Dämonen zu befreien. Und sie sind würdige Gegner, nicht so wie die schwachen Völker der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[9535] = { id = 9535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Pläne", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise auf Orcisch geschrieben wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf den Splitterholzposten im Nordwesten\n\nIhr seid Euch sicher, dass Valusha im Splitterholzposten daran interessiert ist.", sourceObjective = "Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental.", progress = "Was habt Ihr da, Bruder?", completion = "Schreckenslords! Sie planen uns hier am Splitterholzposten anzugreifen?!\n\nNicht solange ich noch am Leben bin!\n\n<Valusha zerknüllt die Pläne mit dem Dämonengekritzel in ihrer Faust.>\n\nNein. Wir werden das nicht zulassen. Sie sind ein Schandfleck in unserer Welt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9536] = { id = 9536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder!", description = "{name}, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des treibenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonenstieg. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals für Grom Höllschrei.", sourceObjective = "Tötet Gorgannon und Diathorus den Sucher und kehrt danach zu Velusha im Splitterholzposten im Eschental zurück.", completion = "Nie wieder wird die Brennende Legion die Orcs oder ein anderes Volk der Horde versklaven! Ihr habt tapfer gekämpft, {class}!\n\nDas wahre Herz der Horde schlägt in Euch! Ihr bringt uns sehr viel Ehre!", sourceObjectiveStatus = "unverified-source-field" }
quests[9537] = { id = 9537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade mit dem Gnom", description = "Wir müssen uns Funks vornehmen!\n\nGeht zum Strand und sucht nach diesem betrügerischen Gnom. Quetscht so viele Informationen wie möglich aus ihm heraus!\n\nWer weiß, wie viele andere ebenfalls ein faules Spiel treiben, wenn schon ein hochrangiger Beamter der Allianz solch verräterische Taten begangen hat?\n\nUnd {name}, wendet Gewalt an, wenn es nicht anders geht...", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr die Mitteilung des Verräters von Ingenieur \"Funks\" Oberschleif an Euch bringt.", progress = "Habt Ihr den elenden Lügner gefunden?", completion = "Unglaublich! Das gehörte alles zu ihrem perfiden Plan!\n\nIhr müsst diese Informationen dem König und Euren eigenen Anführern zukommen lassen. Die Folgen sind erschütternd.", sourceObjectiveStatus = "unverified-source-field" }
quests[9538] = { id = 9538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlernen der Sprache", description = "Ich glaube, ich hab's, {name}!\n\n<Aurren zeigt auf das Totem.>\n\nAlles, was wir über die Sprache der Furbolgs der Tannenruhfeste wissen müssen, ist auf ihren Totems verzeichnet. Wenn wir den grundlegenden Aufbau der Symbole verstehen, können wir die Totems studieren und somit lernen, mit den Furbolgs zu kommunizieren.\n\nIch habe das Grundmuster der Symbole auf dieses Pergament gezeichnet. Studiert es und untersucht dann das Totem. Es sollte Euch zu dem nächsten Sprachtotem führen.\n\nSprecht mit Arugoo, wenn Ihr als gelehrter Draenei zurückkehrt, {race}!", sourceObjective = "Lest die Übersetzungsfibel der Tannenruhfeste, die Aurren Euch gegeben hat. Kommuniziert anschließend mit dem Totem von Akida bei der Azurwacht.", progress = "Ihr könnt ein dunkles Brummen hören, das von dem Totem ausgeht.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort A-K-I-D-A formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9539] = { id = 9539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Coo", description = "Ihr beginnt das Totem zu entschlüsseln, die komplizierten Begriffe lassen sich kaum aussprechen. Langsam formen sich Worte in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Geht auf dem nahegelegenen Hügel nach oben, Richtung Nordosten.", sourceObjective = "Findet das Totem von Coo, indem Ihr den Hinweisen folgt.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort C-O-O formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9540] = { id = 9540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Tikti", description = "Ihr beginnt das Totem zu entschlüsseln, die Begriffe lassen sich bereits etwas leichter aussprechen. Worte formen sich in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Überquert den Kristallfluss Richtung Osten. Vielleicht liegt Euer Ziel ja auf der anderen Uferseite des Flusses.", sourceObjective = "Findet das Totem von Tikti, indem Ihr den Hinweisen folgt.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort T-I-K-T-I formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9541] = { id = 9541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Yor", description = "Die Symbole des Totems scheinen sich viel schneller entschlüsseln zu lassen. Die Begriffe ergeben rasch einen Sinn. Ihr seid ziemlich sicher, dass das Totem Euch auf etwas den Fluss herab im Süden verweist. Etwas muss auf dem Grund des Flusses selbst liegen.", sourceObjective = "Findet das Totem von Yor, indem Ihr den Hinweisen folgt.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort Y-O-R formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9542] = { id = 9542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Vark", description = "Die Symbole auf dem Totem lassen sich jetzt ganz einfach lesen. Es ist, als wäre die Beschriftung auf dem Totem von Yor in Eurer Muttersprache verfasst worden.\n\nDie Hinweise deuten auf einen anderen Furbolgbau im Westen hin. Ihr entschlüsselt meisterhaft die Sprache auf dem Totem und wisst, dass Euer Ziel das Dorf der Sichelklauen ist. Yor wird Euch dorthin führen, falls Ihr Euch dennoch verlaufen solltet, wisst Ihr, dass Ihr die alte Elfenstraße im Wald nehmen könnt, die Richtung Westen zu Eurem Ziel führt.", sourceObjective = "Findet das Totem von Vark, indem Ihr den Hinweisen folgt.", completion = "Beim Lesen des Totems formen Eure Lippen das Wort V-A-R-K. Ihr versteht die Bedeutung, sie lautet Gerechtigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9543] = { id = 9543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sühne", description = "Unsere Vergangenheit mit den Orcs ist gezeichnet von andauernden Konflikten, {name}. Einst hätten sie uns im Blutrausch beinahe vollständig ausgelöscht und selbst als der dämonische Einfluss von ihnen wich, haben wir uns weiter von den Orcs fern gehalten.\n\nTrotz dieser Vergangenheit... das Letzte, was Sedai gewollt hätte, wäre Rache und Blutvergießen. Sprecht mit unserem Ältesten, Amaan dem Weisen. Ihm wird es gelingen, Licht in diese Ereignisse zu bringen.", sourceObjective = "Sprecht mit Amaan dem Weisen beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.", completion = "Wie kann ich Euch behilflich sein, {name}? Ihr klingt, als hättet Ihr Sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9544] = { id = 9544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prophezeiung von Akida", description = "Die Abbildungen auf dem Totem stellen einen Krieg zwischen dem Furbolgstamm der Tannenruhfeste und dem der Sichelklauen dar. Die Motive zeigen Gräueltaten, die die Sichelklauen den Furbolgs der Tannenruhfeste angetan haben.\n\nInmitten des Chaos wird eine Prophezeiung offenbart: Ein Held wird kommen - in seinen Adern fließt kein Furbolgblut - er wird den Stamm der Tannenruhfeste erretten.\n\nTötet die Furbolgs der Sichelklauen im Dorf der Sichelklauen für ihre Schlüssel. Verwendet diese Schlüssel, um gefangene Furbolgs der Tannenruhfeste zu befreien. Sobald Ihr alle befreit habt, kehrt zu Arugoo der Tannenruhfeste zurück.", sourceObjective = "Befreit 8 gefangene Furbolgs der Tannenruhfeste aus den Käfigen im Dorf der Sichelklauen. Kehrt anschließend zu Arugoo der Tannenruhfeste bei der Azurwacht zurück.", completion = "[Furbolg] Die Prophezeiung sprach von jemandem, der sich erheben und uns aus dem gewaltsamen Griff der Sichelklauen befreien würde; dass die Geister selbst die Ankunft dieses Helden verkünden würden.\n\nJetzt seid Ihr gekommen.\n\nIch beuge mich vor Euch in Demut, Großartiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[9545] = { id = 9545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Relikt des Sehers", description = "Die Störrischen unter uns verschließen ihren Geist und glauben an die eine Wahrheit. Der Weise jedoch, hat ein offenes Ohr für die Existenz unterschiedlicher Möglichkeiten, die letztlich zur Gegenwart führen, oder von ihr ausgehen.\n\nBringt dieses Relikt zu dem Ort, an dem Ihr Sedai gefunden habt. Seht nicht mit Euren Augen, {name}, sondern mit Eurem Verstand.", sourceObjective = "Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr Sedais Leichnam erneut aufsucht, um dort das Relikt des Sehers zu benutzen. Kehrt nach Abschluss der Aufgabe zu ihm zurück.", progress = "Habt Ihr eine Vision gehabt, {name}?", completion = "Tief in meinem Innersten hoffe ich, dass Eure Vision Euch neue Einblicke auf die Ereignisse, die zu Sedais Tod geführt haben, gewährt hat. Das Relikt zeigte Euch eine mögliche Reihe von Ereignissen, die zur Gegenwart führten. Die Wahrheit mag irgendwo dazwischen liegen, doch wir werden es nie mit Sicherheit erfahren.\n\nHättet Ihr mit Eurem jetzigen Wissen anders gehandelt?\n\nWer kann schon sagen, ob unser Konflikt mit den Orcs ewig währen wird? Doch am wichtigsten ist es, immer für alle Möglichkeiten offen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9547] = { id = 9547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "{name}, Weissager Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.", sourceObjective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9548] = { id = 9548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Ausrüstung", description = "Schhh! Sprecht leise und lenkt keine Aufmerksamkeit auf mich.\n\nWenn die Murlocs meiner Anwesenheit gewahr werden, ist es mit dem Experiment vorbei! Ich war schon sehr nahe daran, meine Arbeit zu gefährden.\n\nAls ich gestern am Herumkramen war, muss einer von ihnen zu nahe gekommen sein und mein Lager entdeckt haben. Ich kam noch rechtzeitig, um zwei von ihnen eine meiner Ausrüstungskisten fortschleppen zu sehen! Sie muss in einer ihrer Siedlungen hier zu finden sein, aber ich kann es nicht riskieren, meine Deckung aufzugeben. Wollt Ihr mir vielleicht helfen?", sourceObjective = "Bringt Kloppers Ausrüstung zurück zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.", progress = "Konntet Ihr meine Ausrüstung finden?", completion = "Das ist fantastisch! Der Diebstahl meiner Ausrüstung hat mir zu noch mehr Einsicht in das Verhalten der Murlocs verholfen, als ich womöglich mittels wochenlanger Beobachtungen hätte gewinnen können!\n\nIch weiß schon, was ich in meinen Bericht schreiben werde.\n\n'Beim Aufeinandertreffen mit Erzeugnissen einer technologisch höher gestellten Kultur, zeigten die Murlocs der Schwarzschlammküste nicht die sonst typische Neugier wie humanoide Entwicklungskulturen.'\n\nDas ist großartig! Die Herren in Eisenschmiede werden es lieben! Ich kann Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9549] = { id = 9549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzschlammartefakte", description = "Meine Beobachtungen und Aufzeichnungen über die Murlocs der Schwarzschlammküste sind recht aufschlussreich, {name}, aber ich habe gerade erst damit angefangen. Ich habe vor, mit Gegenständen, die auf primitivste Weise von den Murlocs der Schwarzschlammküste hergestellt wurden, nach Eisenschmiede zurückzukehren.\n\nDas Problem ist allerdings, dass die Murlocs diese Gegenstände stets bei sich tragen. Ich könnte es nicht ertragen, wenn meine Hände mit ihrem Blut befleckt wären. Wollt Ihr mir vielleicht dabei helfen, Götzen von den Sehern der Schwarzschlammküste und kunstlosen Messer von den Kriegern und Küstenschlägern der Schwarzschlammküste einzusammeln? Ich werde Euch auch nicht fragen, wie Ihr sie Euch beschafft habt.", sourceObjective = "Bringt 3 kunstlose Murlocgötzen und 6 kunstlose Murlocmesser zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.", progress = "Habt Ihr die Gegenstände, die ich nach Eisenschmiede bringen möchte?", completion = "Verblüffend, einfach verblüffend! Diese Stücke sind perfekt, {name}. Ich kann sie mir bereits unter Glas im Museum von Eisenschmiede vorstellen. Der Text für die Vitrine schreibt sich in meinem Kopf gewissermaßen von selbst!\n\nEure Hilfe war für den Fortgang meiner Studien von unschätzbarem Wert. Wie schreibt sich Euer Name doch gleich? Ich werde dafür sorgen, dass Ihr in meinem Bericht als Mitautor auftaucht.\n\nEiner der Burschen auf dem Schiff gab mir diese 'Schatzkarte', um seine Spielschulden bei mir zu begleichen, allerdings ist Mythologie keines meiner Fachgebiete. Abergläubiges Pack, diese Seefahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9550] = { id = 9550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wohin führt die Karte?", description = "Die nicht gerade sorgfältig gezeichnete Karte verrät zwar nichts über ihren Verfasser, scheint aber mit zittrigen Händen angefertigt worden zu sein. Krakelige Linien und Symbole beschreiben einen kleinen Pavillon mit eingestürzten Säulen. Er befindet sich im Westen eines Turms, der teilweise unter Wasser steht.\n\nGlaubt man der Karte, so liegen diese Ruinen an der östlichen Küste der Insel. Es ist Euch ein Rätsel, was Ihr dort vorfinden werdet, es scheint für die Erstellung dieser Karte jedoch wichtig genug gewesen zu sein.", sourceObjective = "Macht den auf der Karte beschriebenen Pavillon ausfindig und sucht, auf was der Verfasser der Karte hinweisen wollte.", progress = "Vielleicht bezieht sich die Karte ja auf dieses alte Tagebuch.", completion = "Nachdem Ihr Euch das Buch sorgfältig angesehen habt, kommt Ihr zu dem Schluss, dass es sich um ein Tagebuch handelt. Die Eintragungen auf den Seiten weisen eine elegante Handschrift auf, die sich von der auf der Karte unterscheidet. Zahlreiche Texte sind durch hinzugefügte Beschriftungen und Zeichnungen im Stil der Karte unleserlich geworden.\n\nDurch das Geschreibsel des Kartenverfassers, in dem er von Trinkgelagen während des Landgangs faselt, sind die eigentlichen Eintragungen fast nicht mehr auszumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9551] = { id = 9551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "{name}, Weissager Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.", sourceObjective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", completion = "Schließlich kommen wir zu dem letzten der vier großen Elemente, der Luft. Glaubt Ihr weise genug zu sein, um fortzufahren, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9552] = { id = 9552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Der mächtige Geist der Luft verlangt nach Euch, {name}, es ist an der Zeit, diesem Ruf zu folgen.\n\nIch möchte, dass Ihr den Wildwindpfad im Norden hinaufwandert, dem Berg zugewandt, an dem die Exodar zerschellt ist. Auf seinem Gipfel werdet Ihr eine Höhle finden und darin eine meiner am besten ausgebildeten Schülerinnen, Velaada.\n\nBitte, hört auf ihre Weisheit und befolgt ihren Rat. Wenn Ihr zurückkehrt, werdet Ihr ein größeres Verständnis für das Element der Luft haben.", sourceObjective = "Sprecht mit Velaada beim Wildwindgipfel auf der Azurmythosinsel.", completion = "Der Wind hat mir Euer Kommen zugeflüstert, {class}.\n\nWeissager Nobundo achtet Euch sehr - ich auch, nachdem ich von Euren Taten gehört habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9553] = { id = 9553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Die Luft scheint flüchtig zu sein, sie ist jedoch eine alles bedeckende und durchdringende Kraft, die uns umgibt.\n\nAuch wenn Ihr sie nicht sehen könnt, so bestehen die Felsen dieser Höhle doch hauptsächlich aus Luft, das Wasser der Ozeane ist mit ihr gesättigt und ohne sie könnte kein Feuer bestehen. Lasst dies die Elemente niemals hören!\n\nDerjenige, den ihr wegen dieses Wissens wirklich zu sprechen wünscht, ist ganz in der Nähe. Am nördlichen Ende der Felsklippe erwartet Euch Susurrus. Mit seiner Hilfe werdet Ihr verstehen lernen.", sourceObjective = "Sprecht mit Susurrus beim Wildwindgipfel auf der Azurmythosinsel.", completion = "Ich habe Eure Ankunft erwartet, {class}. Ihr sucht nach Weisheit und etwas anderem, das spüre ich.\n\nAlso gut, lasst uns beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9554] = { id = 9554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Während meine Brüder und Schwestern der anderen Elemente die Erfüllung verschiedenster Aufgaben von Euch verlangten, werde ich keine weiteren Anforderungen an Euch stellen. Ich glaube, dass Ihr genug geleistet habt, um für eine 'Wiedergutmachung' für den Unfall, den der Absturz Eures Schiffs verursacht hat, zu sorgen. Ich kann sehen, dass Ihr bereits über die Erfahrenheit verfügt, die Ihr für einen weisen Umgang mit dem Element der Luft benötigt.\n\nNehmt diesen Teil meiner Selbst zurück zu Weissager Nobundo, damit er Euch bei der Erstellung Eures Totems helfen kann. Sobald Ihr bereit seid, werde ich Euch zurück zur Exodar fliegen.", sourceObjective = "Kehrt mit dem Luftwirbel zu Weissager Nobundo bei der Exodar auf der Azurmythosinsel zurück.", progress = "Schon zurück? Euer Haar sieht zerzaust aus.\n\n<Nobundo grinst wissend.>", completion = "Ich bin stolz auf Euch, {name}. Ihr habt dort durchgehalten, wo andere aufgegeben haben. Während all dem habt Ihr ein größeres Verständnis für die Elemente und Euch selbst gewonnen. Denkt immer an das, was Ihr gelernt habt, und Ihr werdet im Leben von diesen Weisheiten profitieren.\n\nGebt mir jetzt bitte den Luftwirbel von Susurrus, damit ich ihn in Euer Lufttotem einbinden kann. Wie die anderen Totems auch, wird es Euch als Fokus und Erinnerung an Eure Bindung mit den Elementen dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9555] = { id = 9555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es freut mich, dass Ihr den schwierigen Pfad des Schamanen gewählt habt. Nur wenige entscheiden sich für diesen Weg, aber ich spüre, dass es für unsere Zukunft von großer Bedeutung sein wird, die Macht des Schamanismus von den Zerschlagenen zu erlernen.\n\nMan nennt sie so, aber einst waren auch sie Draenei. Teuflische Magie hat sie verwandelt und deshalb können sie sich nicht auf die Macht des Lichts berufen. Einige missbilligen sie und den Schamanismus, den sie lehren, aber sie sind nicht bösartig.\n\nIch möchte, dass Ihr mit Weissager Nobundo sprecht. Er ist der weiseste Schamane, den ich kenne, er wird Euch viel beibringen können.", sourceObjective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar.", completion = "Seid gegrüßt. Es ist stets ermutigend, einen {race} zu treffen, der sich dem Weg des Schamanismus eröffnet. Es gibt leider nur wenige.\n\nIhr habt nun gelernt, das Feuer nicht nach seinem Äußeren zu beurteilen, genauso, wie Ihr mein Äußeres nicht beurteilen solltet.\n\nIhr seid hier, weil Ihr bereit seid, Euer Feuertotem zu erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9556] = { id = 9556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Sieger...", description = "Ihr habt zweifellos lange und hart um die Verteidigung der Türme gekämpft, {race}. Wir würden Euch gerne etwas im Gegenzug für Euren tapferen Einsatz geben, allerdings müsst Ihr uns zuerst beweisen, dass Ihr die Gewichtigkeit dieser hier stattgefundenen Tragödien auch versteht.\n\nLauft durch Stratholme und sucht nach einer Phiole mit dem heiligen Wasser. Sobald Ihr sie gefunden habt, reist zum Magierviertel in Sturmwind oder nach Unterstadt... Dort werdet Ihr, insofern Ihr in diesen Landen siegreich wart, auf meinen Kollegen treffen.", sourceObjective = "Sucht nach einer Phiole mit heiligem Wasser in Stratholme und bringt sie zu dem Magier von Lordaeron im Magierviertel von Sturmwind oder in Unterstadt, falls Eure Seite in den östlichen Pestländern erfolgreich war.", sourceObjectiveStatus = "unverified-source-field" }
quests[9557] = { id = 9557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entziffern des Buchs", description = "Da Ihr über keinerlei Mittel verfügt, die es Euch ermöglichen würden, den Inhalt des Buchs zu entschlüsseln, versucht Ihr Euch jemanden ins Gedächtnis zu rufen, der Euch dabei helfen könnte, die ursprünglichen Eintragungen zwischen dem Gekritzel des Kartenverfassers herauszulesen.\n\nIhr erinnert Euch an Anachoret Paetheus' Sammlung verschiedenster Artefakte, die die Draenei während ihrer Reisen entdeckten. Vielleicht können Euch ja seine erfahrenen Augen bei der Entzifferung des Buchs weiterhelfen.", sourceObjective = "Bringt das alte Tagebuch zu Anachoret Paetheus bei der Blutwacht.", progress = "Möge das Licht bei all Euren Bemühungen mit Euch sein, {class}. Was habt Ihr da?", completion = "Hmm... das ist äußerst faszinierend. Ja, ich sollte in der Lage sein, die eigentlichen Einträge des Schreibers in diesem Buch entziffern zu können.\n\nIch verfüge über die benötigten Mittel hier. Es sollte nur einen Augenblick dauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9558] = { id = 9558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Langbarts", description = "Vor nicht allzu langer Zeit hatten wir einige Probleme mit Arakkoabanditen. Sie haben viele unserer Versorgungskarawanen überfallen, weswegen ich ein paar Zwerge angeheuert habe, die sich um sie kümmern sollten.\n\nEs waren Brüder, wobei Gremni Langbart der Älteste von ihnen war. Sie sind losgezogen und nie zurückgekehrt.\n\nIch mache mir ein wenig Sorgen um sie, versteht Ihr? Diese verrückten Zwerge haben mehr Bier als Essen oder Munition eingepackt! Könntet Ihr vielleicht einmal nach ihnen sehen?\n\nDas Versteck der Arakkoa, der Haal'eshbau, befindet sich von hier aus weit im Westen, hinter der großen Kluft. Sie haben nordwestlich von dort ein Lager aufgeschlagen, im Süden der Staubstachelschlucht.", sourceObjective = "Sucht nach Gremni Langbart nordwestlich des Haal'eshbaus, weit im Westen der Ehrenfeste auf der Höllenfeuerhalbinsel.", completion = "Wie habt Ihr uns gefunden, {class}? Egal, Ihr seid sicher hier, um uns zu helfen. Dann mal an die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9559] = { id = 9559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tannenruhfeste", description = "Auserwählter, Ihr müsst nach Norden zur Heimstätte meiner Leute reisen - zur Tannenruhfeste. Dort werdet Ihr auf Eure schrecklichste Herausforderung treffen.\n\nGeht jetzt, der Oberhäuptling der Tannenruhfeste erwartet Euch.", sourceObjective = "Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.", completion = "Jahrhunderte lang lebten wir in verhältnismäßigem Frieden mit den Kreaturen des Landes. Vor einigen Monaten begann Kurz, dunkle Vorzeichen zu sehen. Der Frieden, den wir so lange genossen hatten, schien in Gefahr. Keiner konnte die Ausmaße dieser Katastrophe erahnen!\n\nUnd so kam es, dass die Götter unser Land straften und sowohl Feinde als auch Freunde gegen uns richteten. Aber es gab da noch etwas... inmitten des Chaos sollte sich ein Held erheben: ein Held, in dessen Adern nicht das Blut der Tannenruh fließt. Der Auserwählte würde uns vor der Zerstörung erretten.\n\nDer prophezeite Held wart Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[9560] = { id = 9560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biester aus der Apokalypse!", description = "Mein Bruder und ich waren im östlich gelegenen Wald beim Jagen, als wir von seltsamen, insektenartigen Biestern angegriffen wurden. Solch fremdartige Geschöpfe hatten wir zuvor noch nie auf der Azurmythosinsel gesehen! Könnten es die Vorboten der angekündigten Apokalypse sein? Der Weltuntergang, den IHR verhindern sollt?\n\nSolltet Ihr wirklich der auserwählte Held sein, so werdet Ihr die Biester der Apokalypse bezwingen... und mir ihre Bälge bringen. Ich kann Euch aus diesem Material eine mächtige Rüstung anfertigen!\n\nSucht Richtung Osten nach ihnen, abseits der Straße.", sourceObjective = "Moordo bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr ihm 8 Felshetzerbälge bringt.", progress = "Es sind hässliche kleine Kreaturen. Sogar der blinde Behüter könnte sie sehen... und er ist blind.", completion = "Nicht nur, dass die Prophezeiung wahr ist, nein, diese Rüstung ist ebenso erstaunlich! Eine Rüstung für einen Helden! Ich werde sie Euch für einen besonders günstigen Preis verkaufen, Fellloser.\n\nDas war ein Scherz... das erste Teil gibt's umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[9561] = { id = 9561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nolkais Worte", description = "Ich bin mit der Entschlüsselung jetzt fertig, {name}.\n\n<Anachoret Paetheus zeigt auf einen Textabschnitt am Ende seiner Abschrift.>\n\n'Der Feind ist ganz nah. Wir haben alle Überlebenden zusammengerufen und uns mit ihnen zu dem östlich gelegenen Tempel geflüchtet. Es ist der letzte Ort auf dieser Insel, den wir noch halten können. Unter den Überlebenden hat sich der Glaube verbreitet, dass dies unsere endgültige Zuflucht sein wird. Ich habe Vorkehrungen getroffen und meine verbliebene Habe im Boden des Tempels vergraben. Ich hoffe, dass sie jemand finden und somit erfahren wird, was hier geschehen ist.'", sourceObjective = "Findet den in Nolkais Tagebuch beschriebenen Ort und sucht nach seinen seit langem vergrabenen Besitztümern.", completion = "Gras und Gestrüpp bedecken eine unnatürliche Wölbung am Boden.\n\nNach nur kurzem Graben entdeckt Ihr einen alten Kasten. Es muss sich dabei um den, der in Nolkais Tagebuch beschriebenen ist, handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[9562] = { id = 9562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocs... Warum hier? Warum jetzt?", description = "Es herrschen dunkle Zeiten, <Auserwählter/Auserwählte>. Sogar die Murlocs trampeln uns auf den Füßen herum - im wahrsten Sinne des Wortes. Unglücklicherweise wurde nicht nur mein Stolz verletzt.\n\nUnser Verhältnis zu den Schlickflossenmurlocs war zwar schon immer recht bescheiden, jedoch hätten wir uns niemals vorstellen können, dass sie uns angreifen und von unseren Essensvorräten stehlen würden! Reist Richtung Westen zur Schlickerküste und bringt uns unsere gestohlenen Vorräte wieder!\n\nUnd solltet Ihr einen dunkelhäutigen Murloc mit einem Stück weißen Fell zwischen den Schwimmhäuten sehen...", sourceObjective = "Gurf bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr 5 Säcke mit Tannenruhgetreide wiedererlangt.", progress = "Ein Murloc hat mir in den Hintern getreten und mich angespuckt... und das am helllichten Tag!", completion = "Mmmmm... köstliches Getreide... Parkat wird sich freuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9563] = { id = 9563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirrens Vertrauen erlangen", description = "Ihr wollt also unser Vertrauen erlangen? In diesen Zeiten vertraue ich nicht vielen Leuten.\n\nVor kurzer Zeit haben wir einen der unseren an die Arakkoa verloren. Das hat mich etwas nervös gemacht.\n\nIch sag' Euch was, wenn Ihr Eure Loyalität gegenüber der Ehrenfeste beweisen könnt und... mir einen Krug Nethergarde Bitter bringt... ja, das klingt so weit ganz gut... dann biete ich Euch einen Handel an.\n\nBernie in der Burg Nethergarde hat das Bitter auf Lager.", sourceObjective = "Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 1 Nethergarde Bitter bringt. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Ehrenfeste.", progress = "Probleme, das Bitter zu finden? Der gute alte Bernie in der Burg Nethergarde sollte Fässer davon auf Lager haben.\n\nEs sei denn, seine Vorräte sind ausgegangen... das wäre fatal!", completion = "Oh ja! Ihr scheint ganz in Ordnung zu sein, {race}. Ich denke, ich kann Euch vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9564] = { id = 9564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurfs Würde", description = "Nehmt dem Murloc das Stück Fell, das Gurf bei seiner Auseinandersetzung mit den Biestern \"verloren\" hat, ab und bringt es anschließend zu Gurf zurück. Lasst ihn sogleich wissen, dass der entsetzliche Murgurgula vernichtet wurde.", sourceObjective = "Bringt Gurfs Würde zu Gurf bei der Tannenruhfeste auf der Azurmythosinsel.", progress = "Ist das etwa das, was ich vermute?", completion = "<Gurf spuckt auf den Fellfetzen und versucht ihn auf die kahle Stelle auf seinem Hintern anzubringen.>\n\nDas muss vorerst halten! Ich hoffe, dass einer der Schamanen den Schaden wieder beheben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9565] = { id = 9565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht in der Tannenruhfeste", description = "Als Oberhäuptling gilt meine erste Sorge der Ursache, die hinter der Verderbnis innerhalb der Tannenruhfeste steckt.\n\nWarum haben uns die Wildekin - einst unsere Verbündeten - angegriffen? Warum haben sie die Tannenruhfeste besetzt?\n\nVielleicht finden wir im Innern der Feste ja eine Antwort. Sucht in der Tannenruhfeste nach dem Quell der Verderbnis.", sourceObjective = "Sucht in der Tannenruhfeste nach Hinweisen.", completion = "Der Blutkristall verstrahlt eine kränkliche Aura, die in das Wasser im Keller sickert.", sourceObjectiveStatus = "unverified-source-field" }
quests[9566] = { id = 9566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutkristalle", description = "Außerhalb des Wassers sieht der Kristall wie ein Teil der Exodar aus. Allerdings scheint mit diesem Kristall etwas nicht zu stimmen, denn er ist blutrot und löst sich sehr schnell im Wasser des Kellers auf.\n\nDas könnte das ungewöhnlich aggressive Verhalten der Kreaturen auf der Azurmythosinsel erklären. Kehrt mit diesen Informationen zum Oberhäuptling der Tannenruhfeste zurück.", sourceObjective = "Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.", completion = "Von den Blutkristallen, wie Ihr sie gesehen habt, wurden von meinen Spähern noch viele weitere im Norden gesichtet.\n\nIch danke Euch für die Hilfe, muss Euch nun aber bitten zu gehen, weil ich mich noch mit den Ältesten beraten muss. Ich werde nach Euch rufen lassen, sobald ich mit den anderen Ältesten des Dorfes gesprochen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9567] = { id = 9567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kenne deinen Feind", description = "Es tut gut, neue Gesichter hier bei der Blutwacht zu sehen, {class}. Die Blutelfen stellen zwar die derzeit größte Bedrohung für uns dar, jedoch gibt es noch andere finstere Kreaturen, die die Blutmythosinsel zu ihrem Zuhause gemacht haben.\n\nDie Satyrn der Nazzivus beunruhigen uns besonders. Es sind üble, dämonische Kreaturen, die dunkle Magien beherrschen und sich an der Verderbnis nähren, die der Absturz der Exodar verursacht hat.\n\nWir müssen sie in Schach halten, aber bevor wir handeln, gilt es noch etwas mehr über sie in Erfahrung zu bringen. Geht nach Nazzivian im Westen und versucht so viel wie möglich von ihrem grotesken Monument zu lernen.", sourceObjective = "Findet das Monument der Nazzivus in Nazzivian und beschafft Euch eine Glyphe vom Monument der Nazzivus. Kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück, sobald Ihr die Glyphe habt.", progress = "Habt Ihr schon etwas Wissenswertes von den Satyrn der Nazzivus erlangt?", completion = "Gut gemacht, {name}. Mal sehen, was ich von dieser Glyphe in Erfahrung bringen kann. Dann können wir unseren nächsten Schritt planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9568] = { id = 9568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Offensive", description = "Es ist schlimmer, als ich dachte, {name}. Wir Draenei wissen nur zu gut, was passiert, wenn man seine Seele an die Brennende Legion im Austausch für das Versprechen von Macht und Unsterblichkeit verkauft.\n\nDie Satyrn auf dieser Insel, die Nazzivus, sind Abkömmlinge der ersten abartigen Kreatur, die sich mit der Legion verbündet hatte. Ich fürchte, dass sie einen Weg finden werden, um die Kraft der Kristalle von der Exodar gegen uns zu verwenden.\n\nIhr habt gesehen, was sie diesem Land angetan haben. Stellt Euch nur vor, was sie in den Händen der Satyrn anrichten könnten. Geht Richtung Südwesten nach Nazzivian und startet unsere Offensive!", sourceObjective = "Verteidigerin Aalesia bei der Blutwacht möchte, dass Ihr 10 Satyrn der Nazzivus, 5 Schurken der Nazzivus und 5 Teufelsanbeter der Nazzivus tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9569] = { id = 9569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung bekämpfen", description = "Jetzt, da wir bei den Satyrn Eindruck hinterlassen haben, müssen wir ihnen zu verstehen geben, dass wir Übeltäter der Brennenden Legion hier nicht dulden.\n\nDie Draenei sind schon viel zu lange im Schatten der Legion und ihrer Diener geflohen, {name}. Wo immer sie uns auch fanden, sie zeigten niemals Gnade.\n\nWir dürfen es nicht zulassen, dass die Satyrn den Absturz der Exodar ausnutzen und die verderbten Kristalle als Waffe einsetzen. Geht nach Axxarien im Norden, dem Sitz ihres Anführers. Tötet ihn und nehmt die verderbten Kristalle, die er angesammelt hat, an Euch!", sourceObjective = "Tötet 5 Schattenpirscher von Axxarien, 5 Höllenrufer von Axxarien und Zevrax. Sammelt außerdem 5 verderbte Kristalle ein und kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück.", progress = "<Verteidigerin Aalesia scheint eher durch Euch hindurch, als Euch anzusehen, sie ist voll und ganz mit den Satyrn beschäftigt.>\n\nSeid Ihr schon gegen den Anführer der Satyrn vorgegangen?", completion = "Ohne ihren Anführer und die entwendeten Kristalle können wir die Satyrn bedenkenlos in Schach halten. Nur das Licht weiß, wie viele dieser erbärmlichen Kreaturen da draußen noch lauern.\n\nHerold Mikolaas und ich sind Euch für Eure Hilfe sehr dankbar. Ihr habt uns geholfen, eine noch größere Bedrohung durch die Satyrn abzuwenden. Euer Einsatz wird alle daran erinnern, dass Wachsamkeit der Schlüssel zum Erfolg ist, wenn es darum geht, gegen die Legion und ihre Diener vorzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9570] = { id = 9570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurken lauert", description = "Nachdem der Kristallsturm nachgelassen hatte, erschien eine mythische Bestie in unserem Dorf. Das Untier, Kurken, das von den einfallenden Wildekin hierher gebracht wurde, legte alles in Trümmer. Zahlreiche Furbolgs der Tannenruhfeste wurden bei der Verteidigung unseres Landes von der Bestie getötet. Beim Versuch, das Untier zu bezwingen, ließen viele weitere ihr Leben.\n\nIn meinen Visionen sah ich jemanden, der Kurken besiegte. Diese Person müsst Ihr sein, {name}. Es kann nur einen geben. Betretet die Tannenruhfeste und tötet Kurken. Bringt mir seinen Balg als Beweis für Eure Tat.", sourceObjective = "Kurz der Weise bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Kurken tötet und dass Ihr ihm Kurkens Balg bringt.", progress = "<Kurz schnaubt Euch an.>", completion = "Der Held ist erfolgreich zurückgekehrt!\n\nDie Prophezeiung hat sich fast vollständig bewahrheitet. Jetzt zu dem Balg...", sourceObjectiveStatus = "unverified-source-field" }
quests[9571] = { id = 9571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurkens Balg", description = "Bringt Kurkens Balg zu Moordo, auf der anderen Seite des Dorfes. Er wird daraus ein Rüstungsteil Eurer Wahl anfertigen.", sourceObjective = "Bringt Kurkens Balg zu Moordo bei der Tannenruhfeste.", progress = "Hallo, Held!", completion = "Das ist die stärkste Rüstung, die ich jemals angefertigt habe! Nutzt sie weise, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9572] = { id = 9572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bollwerke schwächen", description = "Schnell, wir haben nicht viel Zeit. Thrallmars Existenz steht auf Messers Schneide!\n\nWir sitzen zwischen der Höllenfeuerzitadelle im Westen und der Brennenden Legion im Osten fest. Da die Legion ihre Aufmerksamkeit auf das Dunkle Portal gerichtet hat, müssen wir die Chance nutzen, um die Höllenorcs in der Zitadelle anzugreifen. Der Schlüssel dazu ist, zunächst die Bollwerke zu durchbrechen!\n\nGeht dorthin, tötet ihre Anführer und bringt einen Beweis für Eure Tat zu Caza'rez gegenüber von mir!", sourceObjective = "Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Caza'rez in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "{name}, richtig? Stok'ton hat mir gesagt, dass ich auf Euren Bericht warten soll.\n\nBringt Ihr gute Nachrichten?", completion = "Das ist ein guter Anfang. Ohne diese drei sollten die Truppen verwirrt sein. Und solange ihre Artillerie außer Gefecht ist, haben wir bessere Chancen, näher vorzurücken, um die Zitadelle einzunehmen.\n\nAber es gehört mehr dazu, als man glaubt, ich fühle es. Deswegen habe ich einen weiteren Auftrag für Euch.\n\nFürs Erste jedoch habt Ihr Eure Arbeit gut gemacht. Sucht euch etwas aus Thrallmars Waffenkammer aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9573] = { id = 9573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptling Oomooroo", description = "Ich bin der Jüngling Tannenruh, Erbe des Vermächtnisses von Tannenruh. Wie Ihr sehen könnt, haben meine Verteidiger eine Todesfalle für die irren Wildekin aufgestellt, die von der Tannenruhfeste aus angreifen. Wir können sie zwar hier draußen abwehren, allerdings hat es noch keiner meiner Verteidiger geschafft, in die Feste vorzudringen. Wenn es Euch gelingen sollte, dort hinein zu gelangen und ihren Anführer zu töten, würde uns das vielleicht eine Gelegenheit zum Angriff verschaffen!\n\nFindet Häuptling Oomooroo und vernichtet ihn. Tötet auch alle wahnsinnigen Wildekin, die Euch im Innern der Feste in die Quere kommen.", sourceObjective = "Der Jüngling Tannenruh bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Häuptling Oomooroo und 9 wahnsinnige Wildekin tötet.", completion = "Das könnte die Gelegenheit sein, auf die wir so lange gewartet haben! Ich werde sofort angreifen lassen! Der Stamm der Tannenruhfeste dankt Euch für Euren Einsatz, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9574] = { id = 9574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfer der Verderbnis", description = "Unsere Ankunft hat die Blutmythosinsel für alle Zeit verändert. Der Absturz der Exodar hat Trümmer über die gesamte Insel verstreut und ich glaube, dass sich dies langsam negativ auf die Natur hier auswirkt.\n\nIch muss mir alles erst genauer ansehen, bevor ich meine Schlussfolgerung bestätigen kann. Die Kristalle scheinen die Bäume als erstes beeinträchtigt zu haben, also müssten die Treants am ehesten die Symptome aufweisen. Wenn Ihr mir Proben von der Rinde verderbter Treants bringen würdet, könnte ich mich weiter in meine Studien vertiefen.", sourceObjective = "Bringt 6 Stücke kristallisierte Rinde zu Morae bei der Blutwacht.", progress = "Konntet Ihr die Proben bekommen, die ich benötige?", completion = "Ich habe jetzt mehr als genug für meine Untersuchungen. Ich danke Euch, {name}. Solltet Ihr noch etwas anderes auftreiben können, das beweist, dass die Kristalle die einheimischen Kreaturen der Blutmythosinsel beeinträchtigen, so lasst es mich sofort wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9575] = { id = 9575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bollwerke schwächen", description = "Schnell, wir haben nicht viel Zeit. Die Existenz der Ehrenfeste steht auf Messers Schneide!\n\nWir sitzen zwischen der Höllenfeuerzitadelle im Westen und der Brennenden Legion im Osten fest. Da die Legion ihre Aufmerksamkeit auf das Dunkle Portal gerichtet hat, müssen wir die Chance nutzen, um die Höllenorcs in der Zitadelle anzugreifen. Der Schlüssel dazu ist, zunächst die Bollwerke zu durchbrechen!\n\nGeht dorthin, tötet ihre Anführer und bringt einen Beweis für Eure Tat zu Gunny gegenüber von mir!", sourceObjective = "Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.", progress = "{name}, richtig? Chadwick hat mir gesagt, dass ich auf Euren Bericht warten soll.\n\nWAS macht Ihr hier?! Habt Ihr Eure Aufgabe erledigt? Seid Ihr denn ein kompletter Vollidiot? Ich könnte mich übergeben!\n\nJetzt schwingt Euren nutzlosen Hintern zu diesem Bollwerk und tut, was Euch aufgetragen wurde! Habt Ihr mich gehört?!", completion = "Wisst Ihr, was ich noch mehr hasse, als mich zu irren? Gold bei einer Wette zu verlieren, dass Ihr es nicht schafft, Schätzchen.\n\nAusgezeichnet! Ohne diese drei sollten die Truppen verwirrt sein. Und solange ihre Artillerie außer Gefecht ist, haben wir bessere Chancen, näher vorzurücken, um die Zitadelle einzunehmen.\n\nIch habe jedoch das Gefühl, dass da noch mehr dahinter steckt. Deswegen habe ich einen weiteren Auftrag für Euch. Hier, sucht Euch etwas aus der Waffenkammer aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[9576] = { id = 9576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schandflosses Anhänger", description = "Ihr untersucht den sehr simpel angefertigten Anhänger und stellt fest, dass der Kristall ganz sachte pulsiert. Er leuchtet ein wenig, aber Ihr spürt auch, dass irgendetwas Unnatürliches davon ausgeht.\n\nIhr seid Euch zwar nicht sicher, was Schandflosse zur Anfertigung dieses Anhängers getrieben hat, aber der Fund scheint zu wichtig, als dass er ignoriert werden könnte. Ihr solltet ihn jemandem bei der Blutwacht zeigen.", sourceObjective = "Bringt den roten Kristallanhänger zu Morae bei der Blutwacht.", progress = "Was habt Ihr da bei Euch?", completion = "Das ist äußerst verwunderlich, {class}. Ich glaube nicht, dass wir jemals einen Murloc gesehen haben, der Schmuck trägt.\n\nBetrachtet man den verderblichen Einfluss, den die Kristallsplitter ganz offensichtlich haben, so muss der Murloc, der diesen Anhänger getragen hat, davon überzeugt gewesen sein, dass er ihm eine Art Macht über seine Artgenossen verleihen würde. Es würde mich nicht verwundern, wenn er in kürzester Zeit stärker als seine Murlocgefährten geworden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9578] = { id = 9578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Galaen", description = "Denkt Ihr oft an Eure Familie, {name}? An Bord der Exodar befanden sich einige Familien, aber ich habe nur von sehr wenigen gehört, die sich nach dem Absturz wiedergefunden haben.\n\nIch suche zum Beispiel nach Spuren von meinem Mann, Galaen. Er war Techniker im Kryokern. Die Trümmer davon wurden im Westen gefunden, allerdings wimmelt es dort nur so von Blutelfen!\n\nIch muss wissen, was Galaen zugestoßen ist! Selbst die Nachricht von seinem Tod wäre noch besser als diese Ungewissheit. Mein Mann trägt den gleichen Anhänger wie ich; sie waren ein Geschenk meiner Schwester.", sourceObjective = "Sucht nach Moraes Mann Galaen.", completion = "Der Leichnam trägt die für einen Techniker der Exodar übliche Kleidung, aber der von Morae beschriebene Anhänger fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9579] = { id = 9579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaens Schicksal", description = "Die Informationen von Morae ermöglichen es Euch nicht, den Leichnam eindeutig als den von Galaen zu identifizieren, allerdings scheint man die Kleidung bei der Suche nach Kostbarkeiten zerrissen zu haben.\n\nDie Blutelfen der Umgebung hätten bei den Wrackteilen jeglichen Gegenstand von Wert an sich genommen, einschließlich das mit Juwelen besetzte Amulett von Galaen.\n\nAuch wenn Moraes Mann den Absturz nicht überlebt hat, so wird sie mit Sicherheit dankbar sein, wenn Ihr das Amulett von den Blutelfen wiedererlangt.", sourceObjective = "Bringt Galaens Amulett zu Morae bei der Blutwacht.", progress = "<Morae sieht Euch voller Hoffnung an.>\n\nSeid Ihr bei Eurer Suche auf Spuren von Galaen gestoßen?", completion = "<Ihr berichtet Morae von Eurem Fund in den Trümmern des Kryokerns.>\n\nAlso... er ist...\n\nIch denke, dass ich es bereits wusste, wollte es aber einfach nicht glauben. Es sind zwar nicht die Neuigkeiten, die ich mir erhofft hatte, aber ich bin Euch für das Auffinden von Galaen zutiefst dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9580] = { id = 9580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärdarfsgüter", description = "Seit Ihr auf der Blutmythosinsel seid, habt Ihr sicherlich nur wenig gesehen, dass sich nicht auf Grund unserer Ankunft verändert hat. Meine Ausbildung und Erfahrung haben mich gelehrt, dass sogar die Erzeugnisse einer derartigen Umgebung noch von Nutzen sein können.\n\nMit so wenigen Ressourcen müssen wir uns auf unseren Einfallsreichtum verlassen, um versorgt zu sein. Ich habe unsere Läden mit Fleisch ausgestattet, das von Bären stammt, die auf dieser Insel umherstreifen. Wenn man es richtig zubereitet, kann es bedenkenlos verzehrt werden. Solltet Ihr da draußen unterwegs sein, so helft uns doch bitte unsere Vorräte aufzufüllen.", sourceObjective = "Bringt 8 Flanken eines alten Braunbären zu Fährtenleser Lyceon bei der Blutwacht.", progress = "Wie verläuft Eure Jagd, {name}?", completion = "Mit diesen Vorräten werden wir fürs Erste versorgt sein und die Zubereitung für den späteren Verzehr wird mich sicherlich ein Weilchen beschäftigen. Ich danke Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9581] = { id = 9581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Kristallen lernen", description = "Willkommen bei der Blutwacht, {class}. Meine hauptsächliche Sorge gilt der Verteidigung des Außenpostens, aber unsere Anführer bei der Exodar haben mir auch zahlreiche andere Pflichten überantwortet.\n\nDas Problem ist nur, dass es eigentlich zu unsicher ist, eine große Anzahl von Forschern auszusenden, wenn die Insel so gefährlich ist. Ich brauche jemanden, der für mich eine Reihe von Kristallproben von verschiedenen Stellen der Insel einsammelt.\n\nDie erste Probe muss von den von Felshetzern besetzten Schiffstrümmern kommen, die südlich des Dorfs und auf der anderen Seite der Brücke liegen.", sourceObjective = "Benutzt die Kristallspitzhacke, um eine Kristallprobe der Absturzstelle von einem Kristall der Absturzstelle zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", progress = "Konntet Ihr die erste Kristallprobe bekommen?", completion = "Dieser Kristallsplitter wird unseren Forschern als Vergleichsgrundlage für Proben von anderen Teilen der Insel dienen, da er aus einem weniger verseuchten Gebiet der Blutmythosinsel stammt.\n\nIch werde die Probe erst losschicken können, wenn ich ein vollständiges Probenset habe, aber der Anfang ist getan. Wenn Ihr mir helfen möchtet, die anderen Proben einzusammeln, werde ich Euch für Eure Mühe natürlich belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9582] = { id = 9582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke des Einen", description = "Als das Schiff abstürzte, wurde unsere Menagerie an den nordöstlichen Stränden dieser Insel zerstreut. Mir wurde ein Schlüssel für den Käfig eines besonders gefährlichen Exemplars anvertraut, dem Todesfelshetzer. Die Kreatur ist zwar nur leicht gepanzert, widersteht aber fast jeglicher Magie. Man muss sie mit der einfachen Kraft des Schwerts erlegen.\n\nNehmt diesen Schlüssel und befreit den Felshetzer aus seinem Gefängnis und von seiner Qual. Wir können es nicht zulassen, dass er aus dem Käfig ausbricht und der Umwelt hier noch weiteren Schaden zufügt.", sourceObjective = "Öffnet den Felshetzerkäfig und tötet den darin befindlichen Todesfelshetzer. Kehrt dann zu Ruada in der Azurwacht auf der Azurmythosinsel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9584] = { id = 9584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Probe", description = "Da wir nun einen Kristall als Vergleichsgrundlage haben, benötigen wir jetzt Proben von gefährlicheren Gegenden der Insel, um das Set zu vervollständigen, das ich zur Exodar senden möchte.\n\nDie nächste Probe muss von den Kristallen kommen, die von den Blutelfen in der Umgebung des Messerwinkels, nordwestlich der Blutwacht, kontrolliert werden. Berichten zufolge verändern und ernten sie die Kristalle, um sie in einer Art magischer Apparatur zu verwenden. Versucht einen Kristall zu finden, der noch nicht in eines dieser Geräte eingebaut wurde, und entnehmt eine Probe davon.", sourceObjective = "Benutzt die Kristallspitzhacke, um eine Veränderte Kristallprobe von einem veränderten Blutmythoskristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", progress = "Habt Ihr die zweite Kristallprobe?", completion = "<Herold Mikolaas untersucht den Kristallsplitter.>\n\nDieser Splitter unterscheidet sich stark von der ersten Probe.\n\n<Herold Mikolaas hält den Kristall ins Licht.>\n\nSeht Ihr, wie das Licht darin pulsiert? Das ist bedenklich. Ich werde in meinem Bericht vermerken, dass die Blutelfen diesen Kristall verändert zu haben scheinen. Ich danke Euch für Eure erneute Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9585] = { id = 9585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Probe", description = "Ich benötige nur noch eine letzte Probe, bevor ich das Set mit den Kristallen zur Exodar schicken kann, {name}. Die letzte Probe muss von der Feste der Satyrn im Nordwesten, Axxarien, kommen.\n\nIch weiß nicht genau, was mir diese Probe aufzeigen wird, aber ich bin mir sicher, dass sie Spuren der Verderbnis enthalten wird. Achtet darauf, dass Ihr eine Probe von den Kristallen entnehmt, die wie die aussehen, von denen Ihr zuvor Proben entnommen habt, ansonsten können unsere Forscher keine korrekten Vergleiche mehr anstellen.", sourceObjective = "Benutzt die Kristallspitzhacke, um eine Axxarienkristallprobe von einem Axxarienkristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", progress = "Habt Ihr die letzte Probe für mein Set?", completion = "<Herold Mikolaas nimmt den letzten Kristall von Euch entgegen.>\n\nDamit ist das Set vollständig. Ich muss nur noch alles verpacken und zur Exodar senden.\n\n<Der Herold scheint erleichtert, dass die Sache erledigt ist.>\n\nVersteht mich nicht falsch, {name}, ich bin mir sicher, dass die Forschungsarbeit wertvoll ist, aber wir haben es hier draußen noch mit zahlreichen anderen Problemen zu tun, die dringend sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9586] = { id = 9586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Tavara", description = "Tavara, eine unserer Kräuterkundigen, ist bei ihrer Suche nach Kräutern viel zu weit gegangen. Ich befürchte sie wurde verletzt und braucht Hilfe, aber unglücklicherweise kann ich mich nicht selbst auf die Suche nach ihr begeben.\n\nBitte findet und heilt sie, wenn nötig, {class}. Sie verließ die Azurwacht in Richtung Osten und machte sich auf den Weg zu einigen heißen Quellen.", sourceObjective = "Guvan bei der Azurwacht möchte, dass Ihr Tavara findet und ihre Wunden heilt.", completion = "Danke, dass Ihr Tavara geholfen habt. Die meisten anderen sind mit dem Land hier nicht vertraut und geraten dort in Schwierigkeiten, wo sie es am wenigsten erwarten.\n\nEs wäre eine Ehre für mich, wenn Ihr diese Roben tragen würdet. Sie zeichnen Euch als Beschützer der Azurwacht und als gläubigen Anhänger des Lichts aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9587] = { id = 9587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düstere Neuigkeiten", description = "Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles \"I\" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.\n\nSicherlich würde Truppenkommandant Danath Trollbann in der Ehrenfeste gerne einen Blick auf den Brief werfen.", sourceObjective = "Bringt den unheilvollen Brief zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.", progress = "Was habt Ihr denn da, mein Sohn?", completion = "Unterzeichnet von Illidan, sagt Ihr?! Gebt mir das mal.\n\n<Der Kommandant liest den Brief, liest ihn erneut und denkt einen Moment nach, bevor er fortfährt.>\n\nDie von Euch überbrachten Neuigkeiten sind ohne Zweifel unheilvoll. Wir müssen unsere Vorhaben gegen die Höllenfeuerzitadelle und diesen Blutkessel unbedingt beschleunigen. Da Ihr bewiesen habt, dass Ihr mit dieser Aufgabe fertigwerden könnt, möchte ich, dass Ihr diese Pläne umsetzt.\n\nGunny wird Euch Euren nächsten Auftrag erteilen, allerdings wird dieser wohl wesentlich tödlicher als Euer erster sein.\n\nMöge das Licht mit Euch sein, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9588] = { id = 9588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düstere Neuigkeiten", description = "Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles \"I\" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.\n\nSicherlich würde Nazgrel in Thrallmar gerne einen Blick auf den Brief werfen!", sourceObjective = "Bringt den unheilvollen Brief zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Was ist das für ein Brief, den Ihr da bei Euch tragt, {class}?", completion = "Unterzeichnet von Illidan, sagt Ihr?! Gebt mir das mal.\n\n<Nazgrel liest den Brief, liest ihn erneut und denkt einen Moment nach, bevor er fortfährt.>\n\nDie von Euch überbrachten Neuigkeiten sind ohne Zweifel unheilvoll. Wir müssen unsere Vorhaben gegen die Höllenfeuerzitadelle und diesen Blutkessel unbedingt beschleunigen. Da Ihr bewiesen habt, dass Ihr mit dieser Aufgabe fertigwerden könnt, möchte ich, dass Ihr diese Pläne umsetzt.\n\nZenturio Caza'rez wird Euch Euren nächsten Auftrag erteilen, allerdings wird dieser wohl wesentlich tödlicher als Euer erster sein.\n\nLok'tar Ogar, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9589] = { id = 9589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut bedeutet Leben", description = "Ich bin mir sicher, dass dieser Brief hier für einigen Aufruhr sorgen wird. Wir glauben, etwas gegen die Erschaffung immer neuer Höllenorcs unternehmen zu können, wenn wir nur mehr über ihren Entstehungsprozess in Erfahrung bringen. Es ist schon schlimm genug, dass wir im Osten gegen die Brennende Legion kämpfen müssen.\n\nHeute ist also Euer Glückstag, <mein Bester/meine Beste>! Ihr bekommt die Chance auf einen Spaziergang im Blutkessel, wie manche den Innenhof der Höllenfeuerzitadelle nennen. Klingt verdammt heiß!\n\nZieht los, tötet ein paar Höllenorcs und bringt Proben ihres Blutes mit zurück.\n\nFühlt Ihr Euch der Aufgabe gewachsen?", sourceObjective = "Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr das Blut Herzchen? Wird wohl ziemlich wichtig sein, wenn wir Euch darum gebeten haben, versteht Ihr?", completion = "Ist ja schon beinahe beängstigend! Von diesem Moment an, Gefreiter {name}, seid Ihr mein absoluter Liebling auf diesen erbärmlichen Überresten dieses erbärmlichen Planeten!\n\nIch bin mir fast sicher, dass die verdammten Eierköpfe sich vor Freude fast in die Hose machen werden, wenn ich ihnen das Blut für ihre Forschungen überlasse. Wer weiß, vielleicht finden wir ja eine neue Waffe im Kampf gegen diese verdammten Höllenorcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[9590] = { id = 9590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut bedeutet Leben", description = "Dieser Brief beunruhigt mich zutiefst, und das nicht nur, weil er vom Verräter persönlich verfasst wurde. Wenn wir sie besiegen wollen, ist es von größter Wichtigkeit, herauszufinden, wie sie diese neuen Höllenorcs erschaffen! Schlimm genug, dass wir die Brennende Legion bei unserer östlichen Flanke bekämpfen müssen, jetzt auch noch eine Höllenorcarmee im Westen!\n\nEs liegt jetzt an Euch, den so genannten Blutkessel im Inneren der Höllenfeuerzitadelle zu infiltrieren. Bringt einige Blutproben von den dortigen Höllenorcs mit.", sourceObjective = "Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Zenturio Caza'rez in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Seid Ihr sicher, dass Ihr ausreichend Blut gesammelt habt?", completion = "Eure Fähigkeiten haben mich sehr beeindruckt, {name}. Nicht einmal, sondern gleich zweimal habt Ihr die Höllenfeuerzitadelle für uns infiltriert und alles getan, was wir Euch aufgetragen hatten.\n\nIch werde mich persönlich darum kümmern, dass dieses Blut in die Hände fähiger Forscher gelangt. Wer weiß, vielleicht können wir den Prozess ja sogar umkehren?", sourceObjectiveStatus = "unverified-source-field" }
quests[9591] = { id = 9591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Das Erste und Einzigste, was <ein/eine:c> {class} am Anfang lernt, ist das Töten. Ihr scheint nun für den nächsten Schritt bereit zu sein.\n\nDie Furbolgs der Tannenruhfeste haben uns beigebracht, wie man Wildtiere zähmt, ohne monatelang zu studieren. Sie können ein Totem in der Gestalt eines Tiers formen, was sie für kurze Zeit mit einer Kreatur dieser Art verbindet.\n\nLektion Nummer Eins: Ihr nehmt dieses Totem und wendet es auf einen Stachelkriecher an. Ihr findet dergleichen an der westlichen Küste der Insel.", sourceObjective = "Benutzt das Zähmertotem, um einen Stachelkriecher zu bändigen. Kehrt nach gelungenem Unterfangen zu Jägerin Kella Nachtbogen zurück.", progress = "Konntet Ihr Euch die Magie des Totems zu Nutze machen und einen Stachelkriecher zähmen? Angriffslustige, kleine Biester!", completion = "Ihr habt mit Sicherheit gemerkt, wie unangenehm der Kriecher während des Zähmungsversuchs war. Bis zu dem Augenblick, in dem sie verstanden haben, dass Ihr sie nicht in einen Kochtopf werfen wollt, sehen sie in Euch einfach nur einen Feind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9592] = { id = 9592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Der Kriecher war zweifellos widerborstig, aber der Grünschreiter wird Eure Beharrlichkeit mit Sicherheit auf eine noch härtere Probe stellen. Stärkere Verbündete benötigen mehr Entschlossenheit.\n\nNehmt dieses Zähmertotem und bändigt damit einen großen Grünschreiter. Ihr findet diese Kreaturen im Norden der Azurmythosinsel.", sourceObjective = "Benutzt das Zähmertotem, um einen großen Grünschreiter zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.", progress = "Der Grünschreiter ist ein mächtiger Vogel. Er wird oft von Jägern unterschätzt, was schreckliche Folgen haben kann.", completion = "Na, hat der Grünschreiter Euch also nicht die Augen ausgepickt.\n\n<Kella sieht für einen Moment weg.>\n\nNatürlich habe ich das auch nicht vermutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9593] = { id = 9593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Während der Zähmung des Grünschreiters sind Euch sicherlich die großen Katzen, die man Nachtpirscher nennt, aufgefallen. Es sind rasche und tödliche Jäger... und Verbündete.\n\nNehmt dieses Zähmertotem und bändigt damit einen Nachtpirscher. Geht mit dem Nachtpirscher auf die Jagd und schützt ihn vor Angreifern. Kehrt anschließend zu mir zurück.", sourceObjective = "Benutzt das Zähmertotem, um einen Nachtpirscher zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.", progress = "Der Nachtpirscher ist im Grunde genommen eine große Katze mit messerscharfen Klauen und einem großen Appetit auf Fleisch...", completion = "Ich muss sagen, {name}, Ihr habt weitaus schneller gelernt, als ich zuerst habe glauben wollen. Es sieht so aus, als würden wir das letzte Zähmertotem nicht benötigen. Ehrlich gesagt, ich weiß nicht einmal genau, was es ist. Eine Art Echse mit Flügeln und einem langen Schwanz. Ach, naja, vielleicht ein andermal.\n\nEs ist an der Zeit, dass Ihr eine wilde Kreatur auch ohne die Hilfe eines Totems zähmen könnt. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[9594] = { id = 9594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Legion", description = "Das Rüstungsstück wurde aus einem tiefschwarzen Metall geschmiedet, das Licht zu absorbieren scheint. Es wirkt zwar nicht verzaubert, allerdings kommt es Euch alles andere als normal vor.\n\nSolch eine Rüstung wird nur von einer bestimmten Macht verwendet - der Brennenden Legion. Die Gegenwart der Legion kann nur bedeuten, dass sie vorhaben, die Satyrn der Insel gegen die Draenei aufzuhetzen.\n\nGeht gegen die einheimischen Satyrn vor und zeigt dieses Rüstungsstück Verteidigerin Aalesia bei der Blutwacht.", sourceObjective = "Tötet 8 Satyrn der Nazzivus und 8 Teufelsanbeter der Nazzivus. Bringt anschließend Tzeraks Panzerplatte zu Verteidigerin Aalesia bei der Blutwacht.", progress = "Ja, {class}? Was habt Ihr da?", completion = "Es war richtig, dass Ihr damit zu mir gekommen seid, {name}. Es handelt sich hierbei zweifellos um ein Rüstungsstück einer Teufelswache.\n\nDann ist es also, wie ich es befürchtet hatte. Die Satyrn der Nazzivus nehmen erneut Verbindung zur Brennenden Legion auf. Wenn wir sie nicht aufhalten, werden uns die Satyrn und ihre dämonischen Verbündeten überrennen. Ich werde Herold Mikolaas sofort davon in Kenntnis setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9595] = { id = 9595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle", description = "Ihr habt Euch entschieden, als {class} durchs Leben zu gehen, also müsst Ihr jetzt Kontrolle erlernen. Ungezügelte Magie ist fähig, Seelen zu verderben und Welten zu zerstören.\n\nUm all das noch besser verstehen zu können, müsst Ihr einem Wesen gegenüber treten, das der eigens ausgeübten Magie erlegen ist. Reist zu den Stränden an der nordwestlichen Küste der Azurmythosinsel und setzt Eure Magie ein, um ein paar üble Murlocs zu vernichten. Euer Magiegebrauch wird wahrscheinlich die böse Macht hervorlocken, die sich dort herumtreibt - ein Magiergeist der Quel'dorei. Vernichtet ihn.\n\nWenn Ihr fertig seid. macht Euch auf die Suche nach Bati in der Halle des Lichts der Exodar.", sourceObjective = "Vernichtet die Murlocs der Schlickerküste, um einen Magiergeist der Quel'dorei zu rufen, und vernichtet ihn. Sprecht dann mit Bati in der Halle des Lichts in der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9598] = { id = 9598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung", description = "Ich bin dafür verantwortlich, die Paladine auf den Pfad der größten Tugend zu bringen, sobald sie sich dem Weg des Lichts verschreiben und unser Volk vor den Bedrohungen verteidigen.\n\nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch das Buch der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.", sourceObjective = "Lest das Buch der Offenbarung und sprecht mit Jol.", progress = "Willkommen zurück, {name}.", completion = "Willkommen zurück, {name}. Ich hoffe, Ihr habt die Zeit genutzt und das Buch gelesen.\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9600] = { id = 9600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung", description = "Es wird Eure Aufgabe sein, {name}, unseren neuen Verbündeten, den Furbolgs der Tannenruhfeste, zu helfen.\n\nEinige der jüngeren Schamanen der Tannenruhfeste sind in ein Lager der Sichelklauen gestolpert und wurden allesamt getötet. Nehmt dieses Symbol des Lebens und erweckt einen der Schamanen wieder zum Leben.\n\nDie Enklave der Sichelklauen liegt östlich der Straße, direkt nachdem man die Brücke überquert, die die Azurmythosinsel und die Blutmythosinsel verbindet. Sprecht mit mir, wenn Ihr diese Aufgabe erfüllt habt.", sourceObjective = "Jol möchte, dass Ihr einen jungen Schamanen der Furbolgs mit dem Symbol des Lebens wieder zum Leben erweckt und dass Ihr anschließend wieder zu ihr zurückkehrt.", completion = "Sorgt Euch nicht um die Verwirrung derer, denen Ihr geholfen habt. Es ist nicht ungewöhnlich, dass diejenigen, die erst kürzlich wieder in die Welt der Lebenden gebracht wurden, etwas desorientiert sind. Stellt Euch nur einmal den Schock vor, den sie bei der Begegnung mit seltsamen Wesen erlitten haben.\n\nDer junge Schamane ist gesegnet, da er diese harte Lektion dank Euch überlebt hat. Es ist mehr als angebracht, dass Ihr Euch dieser Macht von nun an jederzeit bedienen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9601] = { id = 9601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Bollwerk", description = "Der Blutritter Mehlar Dämmerklinge hat ein Treffen mit Euch gefordert, {name}. Ihr findet Mehlar beim Bollwerk, das den Übergang zwischen Tirisfal und den westlichen Pestländern schützt.\n\nEr ist nicht gerade für seine Geduld bekannt. Ihr solltet ihn also nicht warten lassen.", sourceObjective = "Sprecht mit Mehlar Dämmerklinge beim Bollwerk.", completion = "Ahh... wie es scheint ist die zeit gekommen.\n\n<Mehlar nickt wissend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9602] = { id = 9602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheilvolle Mitteilung", description = "Ihr müsst Euren Leuten diese Informationen überbringen, {name}. Auch wenn Euer mutiger Einsatz die Pläne von Kael'thas und seinem dunklen Meister sicherlich ins Stocken gebracht hat, werden mit Sicherheit auch weiterhin Angriffe verübt werden.\n\nNehmt die Mitteilung des Verräters zu Euren Anführern. Sie müssen es mit ihren eigenen Augen sehen. Vielleicht verstehen sie einiges von dem Geschriebenen besser.", sourceObjective = "Bringt die Mitteilung des Verräters zu Exarch Menelaous bei der Azurwacht.", progress = "Ihr seid zurück!", completion = "<Exarch Menelaous nimmt die Mitteilung von Euch entgegen und beginnt sie zu lesen.>\n\nVerdammt... verdammt sie alle in den Nether. Sie hatten einen Spion, der sie über all unsere Aktivitäten informiert hat! Und seit wann?\n\nIch werde sofort Velen informieren!\n\nIhr habt uns einen großen Dienst erwiesen, {name}. Haltet die Augen offen, ich werde mich an Euch wenden, sobald der Prophet mir mitgeteilt hat, was es zu tun gilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9603] = { id = 9603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betten, Verbände und noch viel mehr", description = "Willkommen bei der Blutwacht, {class}. Bitte entschuldigt die Unordnung, die hier überall herrscht. Man betrachtet die einfachsten Dinge oft als selbstverständlich, wie zum Beispiel ein komplett eingerichtetes und ausgestattetes Gasthaus... bis man selbst ein neues aus dem Nichts errichten muss.\n\nWir konnten dieses Wrackteil bergen und für das Gebäude verwenden, allerdings ist dieses Gasthaus lediglich ein besseres Zelt, ohne die entsprechende Einrichtung und die Notvorräte. Nurguni bei der Exodar hat uns angeboten, ein paar Vorräte mit den im Moment am dringendsten benötigten Dingen zusammenzustellen. Ich brauche jedoch jemanden, der ihm diese Liste hier bringt.", sourceObjective = "Bringt Tophers Liste zu Laando, dem Hippogryphenmeister bei der Blutwacht.", progress = "Guten Tag, {name}. Interessiert Ihr Euch für einen Hippogryphenflug?", completion = "Ihr müsst also zu der Exodar?\n\nDas ist ein ganz schön weiter Weg, aber keine Sorge, ich weiß schon, wie Ihr auf dem schnellsten Weg an Euer Ziel kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9604] = { id = 9604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Rücken eines Hippogryphen", description = "Ihr könnt einen meiner Hippogryphen gegen ein kleines Entgelt mieten, um zur Exodar zu fliegen.\n\nEinen Hippogryphen zu nehmen, ist eine schnellere und, was noch wichtiger ist, sichere Reisemöglichkeit für jemanden, der eine wichtige Nachricht zu überbringen hat. Wenn Ihr Euch für einen Hippogryphenritt entschieden habt, sprecht einfach nochmal mit mir und ich kümmere mich um den Rest.", sourceObjective = "Erwerbt bei Laando einen Hippogryphenritt zur Exodar. Bringt Tophers Liste nach der Landung zu Nurguni im Sitz der Naaru der Exodar.", progress = "Seid gegrüßt, Freund. Ihr seht aus, als hättet Ihr einen langen Weg hinter Euch. Wie kann ich Euch helfen?", completion = "Ah, Ihr habt also Tophers Liste gebracht. Ausgezeichnet! Ich hatte gehofft, dass ich sie heute erhalten würde. Lasst mal sehen, was er braucht.\n\n<Nurguni überfliegt die Liste und beginnt verschiedene Gegenstände in eine Kiste zu packen.>\n\nDas sind fast alle Dinge, die er aufgelistet hat. Die Teile für die Betten sind einfach zu groß, um auf einem Hippogryphen transportiert werden zu können. Ich werde dafür sorgen, dass sie mit einem Wagen nachgeliefert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9605] = { id = 9605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryphenmeister Stephanos", description = "Hier ist die Kiste, {name}. Es sollte genug sein, damit Topher das Gasthaus fertigstellen und eröffnen kann. Richtet ihm bitte aus, dass er bei steigendem Bedarf jederzeit weitere Vorräte anfordern kann. Die Blutwacht braucht unbedingt einen Ort, an dem Verwundete versorgt und Reisende empfangen werden können.\n\nSucht Stephanos auf, wenn Ihr zur Blutwacht zurück möchtet, er hält sich beim Eingang der Exodar auf.", sourceObjective = "Geht zu Stephanos in der Exodar und erwerbt einen Hippogryphenritt zurück zur Blutwacht.", progress = "Wohin wollt Ihr, {class}?", completion = "Ihr wollt also mit dieser Kiste zurück zur Blutwacht? Kein Problem, {class}. Sagt einfach Bescheid, wenn's losgehen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[9606] = { id = 9606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Topher Loaal", description = "Wenn ich mich recht erinnere, dann ist Laando der Hippogryphenmeister bei der Blutwacht. Falls Ihr schon einmal mit ihm gesprochen habt, könnt Ihr einen meiner Hippogryphen zurück zu ihm nehmen.\n\nIhr solltet Euch etwas Wichtiges merken: Hippogryphen werden stets so ausgebildet, dass sie zu ihrer Hauptstadt zurückfliegen, sie bringen Euch aber nur zu einem entlegenen Hippogryphenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nDa Ihr mit einem von Laandos Hippogryphen hier angekommen seid, könnt Ihr diese Route mit Euren Vorräten auch wieder zurück zur Blutwacht nehmen.", sourceObjective = "Sprecht mit Stephanos und erwerbt einen Hippogryphenritt zurück zur Blutwacht. Bringt Nurgunis Vorräte nach Eurer Ankunft zu Versorger Topher Loaal.", progress = "Willkommen zurück, {name}. Konnte Nurguni Euch alle Vorräte mitgeben, die auf der Liste standen?", completion = "<Ihr überreicht Topher die Kiste und erklärt ihm, dass Nurguni dafür sorgt, dass die größeren Gegenstände mit einem Wagen nachgeliefert werden.>\n\nGroßartig! Ich werde jetzt endlich ein paar Lagerstätten und eine Versorgungsstation einrichten können. Hier wird man sich in Zukunft um Verwundete und mögliche weitere Überlebende kümmern können.\n\nIch weiß gar nicht, wie ich Euch für Eure Hilfe danken kann, {name}. Die Anerkennung von mir und den Verteidigern der Blutwacht ist Euch sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[9607] = { id = 9607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Herzen des Hasses", description = "{class}, sucht Euch sofort eine Gruppe und kundschaftet den Blutkessel im Inneren der Höllenfeuerzitadelle aus! Und ich meine heute noch Prinzesschen!\n\nUnsere magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden unsere weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt. Das sagt schon alles!\n\nRechnet mit starkem Widerstand; keine andere Truppe, die wir hineingeschickt haben, ist je zurückgekehrt.\n\nGeht hinein, untersucht das gesamte Areal und meldet Euch dann beim Truppenkommandant!", sourceObjective = "Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.", completion = "SIE HABEN EINEN GRUBENLORD?!\n\n<Der Truppenkommandant bemerkt die starrenden Gesichter der anderen und senkt seine Stimme.>\n\nDas ist es. Sie müssen das Blut dieses Grubenlords verwenden, um neue Höllenorcs, die aus irgendeinem Grund nicht zur Brennenden Legion gehören, zu erschaffen. Und wenn sie das mit den braunen Mag'har können, schaffen sie das auch mit grünen! Bei all den Orcs, die durch das Dunkle Portal kommen, sind das alles andere als gute Nachrichten!\n\nWir müssen sie ins Herz ihrer Militärmacht treffen, und zwar bald!", sourceObjectiveStatus = "unverified-source-field" }
quests[9608] = { id = 9608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Herzen des Hasses", description = "{class}, sucht Euch sofort eine Gruppe und kundschaftet den Blutkessel im Inneren der Höllenfeuerzitadelle aus!\n\nUnsere magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden unsere weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt, also muss es sehr wichtig sein.\n\nRechnet mit starkem Widerstand; keine andere Truppe, die wir hineingeschickt haben, ist je zurückgekehrt.\n\nGeht hinein, untersucht das gesamte Areal und meldet Euch dann bei Nazgrel, Thralls Berater.", sourceObjective = "Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", completion = "SIE HABEN EINEN GRUBENLORD?!\n\n<Nazgrel bemerkt die starrenden Gesichter der anderen und senkt seine Stimme.>\n\nDas ist es. Sie müssen das Blut dieses Grubenlords verwenden, um neue Höllenorcs, die aus irgendeinem Grund nicht zur Brennenden Legion gehören, zu erschaffen. Und wenn sie das mit den braunen Mag'har können, schaffen sie das auch mit uns!\n\nWir müssen sie ins Herz ihrer Militärmacht treffen, und zwar bald!", sourceObjectiveStatus = "unverified-source-field" }
quests[9609] = { id = 9609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Behüter Biggs", description = "Magtoor hat mir gesagt, dass in der Nähe ein Behüter gestrandet ist. Offensichtlich wurde die Karawane, die er von Dunkelhain ab begleitet hat, von Verirrten angegriffen. Wie es aussieht ist er der einzige Überlebende.\n\nEr ist irgendwo im Süden. Bitte, {class}, helft ihm.", sourceObjective = "Sucht Behüter Biggs in den Sümpfen des Elends.", completion = "Was? Ein Draenei vom sicheren Hafen hat Euch geschickt? Wie merkwürdig.\n\nNun, ich bin niemand, der Hilfe ablehnt. Vielen Dank, dass Ihr gekommen seid, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9610] = { id = 9610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tränenteich", description = "Ich interessiere mich für die Geschichte von Azeroth und frage mich, ob Ihr mir helfen möchtet.\n\nIn der Nähe im Sumpf gibt es einen Platz von historischer Bedeutung, zu dem ich Euch gerne schicken möchte. Der Tränenteich liegt im Südosten. Man sagt, dass sich an seinem Ufer und in seinen Tiefen vergrabene Artefakte der Zivilisation der Atal'aitrolle befänden.\n\nAber seid vorsichtig, der Teich wird von Somnus, einem uralten grünen Drachen, und seinen Drachlingen, sowie fleischfressenden Fischen bewacht!", sourceObjective = "Besorgt 10 Artefakte der Atal'ai und bringt sie zu Holaaru im sicheren Hafen in den Sümpfen des Elends.", progress = "Ich freue mich schon darauf, die Artefakte, die Ihr sammeln werdet, zu untersuchen. Ich möchte herausfinden, was mit der einst so großartigen Zivilisation geschehen ist.", completion = "Ich danke Euch, {class}. Ich werde eine ganze Weile mit der Untersuchung dieser Artefakte beschäftigt sein. Wie sonst können wir Zerschlagenen und Draenei uns einfügen, wenn wir nichts von der Geschichte unserer Welt kennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9612] = { id = 9612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzlichen Dank!", description = "Ihr habt mein Leben gerettet, {name}! Ich danke Euch von ganzem Herzen! Wärt Ihr nicht gewesen, hätte mich diese Bestie in Fetzen gerissen.\n\nWenn Ihr den Exarch bei der Azurwacht seht, erzählt ihm von Eurer Tat. Ich bin mir sicher, dass er diese Neuigkeit mit Freuden aufnehmen wird!", sourceObjective = "Sprecht mit Exarch Menelaous bei der Azurwacht.", completion = "Gut gemacht, {name}. Wirklich sehr, sehr gut! Ihr erweist Euch langsam als besonderer {race} - Ihr seid den anderen Euren Alters einen Schritt voraus. Nehmt dies als Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[9613] = { id = 9613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keannas Wille", description = "<Als Ihr das Schwert berührt, Hört Ihr eine weibliche Stimme, die Euch anspricht.>\n\nAu! Lasst das! Könnt Ihr nicht sehen, dass ich zerbrochen bin? Das tut weh!\n\nWie ich sehe, seid Ihr Karazhan nicht in die Falle gegangen. Dann müsst Ihr von Khadgar und dem Violetten Auge wissen.\n\nIhr müsst jemanden finden, der mich wieder zusammenfügen kann. Koren... er war einst unser Agent... er ist in der Nähe. Ich hoffe, dass Ihr zu den Guten gehört. Wenn ja, dann kann er uns helfen!", sourceObjective = "Die zertrümmerte Klinge, die ihr in Karazhan gefunden habt, möchte, dass Ihr Koren bittet, sie zu reparieren. Ihr müsst außerdem einen wohlwollenden Ruf beim Violetten Auge innehaben, um die Quest abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9614] = { id = 9614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge zusammenfügen", description = "Diese Waffe wurde in so viele Stücke zerbrochen... sie wieder zusammenzufügen wird nicht einfach.\n\nIch brauche Khorium. Viel davon. Und einen Kristall der Leere sowie etwas Urfeuer.", sourceObjective = "Bringt 40 Khoriumbarren, 1 Kristall der Leere und 8 Urfeuer zu Koren in Karazhan.", sourceObjectiveStatus = "unverified-source-field" }
quests[9615] = { id = 9615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge zusammenfügen", description = "Diese Waffe wurde in so viele Stücke zerbrochen... sie wieder zusammenzufügen wird nicht einfach.\n\nIch brauche Khorium. Viel davon. Und einen Kristall der Leere sowie etwas Urfeuer.", sourceObjective = "Bringt 40 Khoriumbarren, 1 Kristall der Leere und 8 Urfeuer zu Koren in Karazhan.", sourceObjectiveStatus = "unverified-source-field" }
quests[9616] = { id = 9616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banditen!", description = "Es scheint sich um ein Kopfgeldverzeichnis zu handeln. Ihr könnt die Sprache der Blutelfen zwar nicht verstehen, aber Ihr bemerkt ein Bild, das einen toten Draenei darstellt, einen grinsenden  Blutelfen, der sich über dessen Körper beugt, und ein Symbol, das Eurer Meinung nach für eine Art Währung der Blutelfen steht.\n\nSie haben es auf die Draenei abgesehen! Ihr müsst den Exarch darüber informieren.", sourceObjective = "Nehmt das Blutelfendokument zu Exarch Menelaous bei der Azurwacht.", progress = "Ja? Ich bin wirklich sehr beschäftigt, {name}.", completion = "Beim bartlosen, quadratischen Schädel von O'ros! Gut, dass Ihr das zu mir gebracht habt, {name}. Diese Blutelfen haben es... nun ja, auf Blut abgesehen. Velen wird davon sofort in Kenntnis gesetzt werden! Nehmt dies als Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9617] = { id = 9617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht die Weltenwanderer auf", description = "Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer hat nach einer Audienz mit allen fähigen Jägern verlangt. Es würde Euch zugutekommen, wenn Ihr sie aufsuchen würdet, {name}. Sie ist ein Stern der Erleuchtung für unsereins.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.", sourceObjective = "Sprecht mit Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.", completion = "{name}, es ist gut, dass Ihr gekommen seid. Unsere Liste mit Verbündeten schrumpft immer mehr. Selbst denjenigen, die die gleichen Ziele verfolgen, kann man nicht wirklich trauen. Daher wenden wir Waldläufer uns der Natur für Hilfe zu.\n\nDie Verbündeten des Waldes kennen keinen Verrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9618] = { id = 9618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringen der Berichte", description = "Eure Geschicklichkeit war äußerst beeindruckend. Es besteht kein Zweifel, ich kann Euch die Überbringung dieser Berichte an Zelanis anvertrauen.", sourceObjective = "Bringt Keltus Dunkellaubs Berichte zu Zelanis in Silbermond.", progress = "Konntet Ihr Keltus ausfindig machen?", completion = "All diese Berichte sind von Keltus? Er hatte jede Menge zu tun, so viel steht fest.\n\nKariel ist ein Schurke unter den Schurken - er hält sich nur selten genau an Anweisungen und reißt gewisse Dinge oft an sich! Denkt jetzt nichts Falsches, er ist einer meiner verlässlichsten Spione und ohne ihn, wären wir arm dran.\n\nIhr habt heute eine beispielhafte Leistung vollbracht. Bitte nehmt diese Klinge und führt sie in den Rücken unserer Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9619] = { id = 9619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörungsrune", description = "Der Leerstein offenbart Euch eine Vision von einem mehrstöckigen Gebäude, das von geisterhaften Figuren behaust wird. Die Szene wird schärfer und verschwimmt dann wieder, andere Gebäude kommen ins Bild, es scheint sich um den Ort Goldnebel zu handeln.\n\nHausdächer und Baumwipfel schwirren plötzlich vorbei, sie verraten Euch den Weg nach Goldnebel, der den Elrendar entlang nach Westen führt.\n\nVerwendet den Leerstein, sobald Ihr dort angekommen seid, nahe der Beschwörungsrune auf dem Hauptgebäude und bezwingt den heraufbeschworenen Leerwandler. Erst dann könnt Ihr zu Eurem Lehrer zurückkehren.", sourceObjective = "Verwendet den Leerstein, um einen Leerwandler in Goldnebel zu beschwören. Bezwingt ihn und kehrt zu Talionia in Silbermond zurück.", progress = "Seid Ihr dem vom Leerstein aufgezeigten Weg gefolgt?", completion = "Ich bin beeindruckt, dass Ihr hier seid, {name}. Viele Lehrlinge sind am Leerwandler gescheitert, oder sogar schon am Leerstein selbst.\n\nDer Leerwandler steht nun unter Eurem Befehl. Setzt Euren neuen Begleiter weise ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9620] = { id = 9620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das vermisste Vermessungsteam", description = "Als wir uns hier bei der Blutwacht langsam eingerichtet hatten, schickte ich Vermessungsteams aus, die zuverlässigere Karten der Insel erstellen sollten. Meistens kamen sie wieder unversehrt mit den von uns benötigten Angaben zurück, aber das Team, das ich nach Osten zu den Ruinen entsendet hatte, wird noch immer vermisst.\n\nIch mache mir Sorgen um sie, aber leider kann ich niemanden entbehren, um ein weiteres Team nach ihnen suchen zu lassen. Findet sie, {name}, und helft ihnen soweit es geht, damit sie mit ihren gesammelten Informationen wieder zurückkehren können.", sourceObjective = "Herold Mikolaas möchte, dass Ihr das Vermessungsteam findet, das er zu den Ruinen von Loreth'Aran entsendet hatte, und dass Ihr dem Team so gut es geht zur Seite steht.", completion = "Auf dem Boden liegen überall die Körper der {race}, die dem Vermessungsteam angehörten - von Waffen der Naga durchbohrt. Ihr seht die verstreuten Überreste ihrer Vorräte und Vermessungsausrüstung, aber ihre Datenkristalle befinden sich nicht darunter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9621] = { id = 9621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesandter zur Horde", description = "Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertig werden?\n\nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.\n\nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, {name}. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.", sourceObjective = "Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.", progress = "Ah, ein Besucher aus Quel'Thalas! Welche Neuigkeiten bringt Ihr?", completion = "Dann ist es also geschehen. Der gemeine Verräter hat bekommen, was er verdient hat.\n\nIhr habt das selbst getan? Eine beeindruckende Tat, die beweist, dass Euer Volk immer noch würdig ist, {name}.\n\nWie ich sehe hat Lor'themar weitere Nachrichten, die seine Beziehungen zu Thrall deutlich verbessern werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9622] = { id = 9622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt vor der Gefahr", description = "Die Feste ist jetzt wieder sicher und schon bald werden sich meine Leute auf den Weg zurück zu ihrem Ahnenstammsitz machen. Die Prophezeiung wurde Wirklichkeit und für die Furbolgs der Tannenruhfeste beginnt eine neue Ära des Wohlstands.\n\nIch befürchte allerdings, dass die Dunkelheit für Eure eigenen Leute eine Bedrohung darstellt. Es gibt noch immer unbeantwortete Fragen - ungesehene Visionen aus der Prophezeiung.\n\nKehrt zu Euren Anführern zurück und erzählt ihnen von all dem, was Ihr hier erlebt habt.\n\nSolltet Ihr jemals die Hilfe der Tannenruhfeste benötigen, lasst es uns einfach wissen.", sourceObjective = "Sprecht mit Exarch Menelaous bei der Azurwacht.", completion = "Visionen sagt Ihr? Interessant... und diese Prophezeiung hat sich also bewahrheitet?\n\nIhr sagt jedoch, dass man den Kraftkern der Exodar gesehen hat? O'ros erschien auch in der Vision? Was kann das nur bedeuten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9623] = { id = 9623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiferwerden", description = "Ihr habt in der Wildnis unserer neuen Heimat überlebt und Euch als etwas Besonderes unter den anderen hervorgetan. Ich glaube, dass Ihr nun reif genug seid, um die zu unterstützen, die an der Front der Blutmythosinsel kämpfen. Die Hand von Argus könnte <einen/eine> wie Euch gebrauchen.\n\nMeldet Euch bei Torallius dem Herdentreiber. Ihr findet ihn außerhalb der Exodar bei dem Elekk. Gebt ihm diese Befehle, damit er Euch neue Aufträge auf der Blutmythosinsel erteilen kann.", sourceObjective = "Exarch Menelaous bei der Azurwacht hat Euch gebeten, die Befehle des Exarchen zu Torallius dem Herdentreiber, der außerhalb der Exodar steht, zu bringen.", progress = "<Torallius rückt seine Augenklappe zurecht und sieht Euch an.>\n\nHaben wir der Hand von Argus nichts Besseres anzubieten?", completion = "<Torallius seufzt.>\n\nNun gut, lasst mich einen Blick auf diese Befehle werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9624] = { id = 9624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsleckerli", description = "Ich habe eine wundervolle Entdeckung gemacht, {class}. In den noch unberührten Gebieten dieser Insel wächst eine außergewöhnliche Frucht, die Sandbirne genannt wird. Man findet sie am Boden nahe der Bäume.\n\nIch habe sie zum Kuchenbacken verwendet, aber wenn ich nicht Acht gebe, kommen die Elekk angelaufen und stehlen mir das Obst. Ich hatte genug eingesammelt, um mit den Tieren teilen zu können, aber mein Vorrat ist aufgebraucht und nun herrscht wieder großes Verlangen nach Kuchen. Würdet Ihr mir mit dem Sammeln der Früchte helfen, damit ich eine weitere Charge Kuchen backen kann? Ich werde teilen, ich verspreche es!", sourceObjective = "Aonar bei Kessels Wegelager möchte, dass Ihr ihm 10 Sandbirnen bringt.", progress = "Man findet die Sandbirnen immer seltener, was natürlich weniger Kuchen und somit weniger Leckerli für die Elekk hier bedeutet. Konntet Ihr die benötigten Früchte auftreiben?", completion = "War das Auffinden der Früchte schwierig? Ich brauche mit jedem Mal länger.\n\nIch werde allmählich ganz damit aufhören müssen, da ich keine Zeit mehr dafür habe. Danke für das Sammeln der Birnen, {name}. Jetzt kann ich zumindest noch ein oder zwei Kuchen backen, bevor die Saison vorüber ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9625] = { id = 9625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk sind starker Tobak", description = "Ist er verrückt geworden? Wie kann er von mir erwarten, dass ich einen meiner wertvollen Lieblinge einem namenlosen <Jüngling/jungen Ding> wie Euch überlasse!\n\nLasst Euch etwas gesagt sein, Kindchen: Ihr werdet es nie zu einem von der Hand von Argus machen! Ihr habt nicht das Zeug dazu!\n\nIch glaube, dieses Mal muss ich ihm seinen Willen lassen. Sprecht mit Vorkhan bei Kessels Wegelager auf der Blutmythosinsel. Folgt einfach der Straße von hier aus nach Norden und geht einfach nach Norden weiter, wenn sie abzweigt.", sourceObjective = "Sprecht mit Vorkhan dem Elekktreiber auf der Blutmythosinsel.", completion = "Naja, zumindest habt Ihr's bis hierher geschafft! Jetzt schicken wir Euch lieber an die Arbeit, bevor Ihr noch zertrampelt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9626] = { id = 9626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit dem Kriegshäuptling", description = "Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Krallen und Zähnen gekämpft, damit Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.\n\nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zu Thrall in Orgrimmar. Als Anführer der Horde hat er das letzte Wort bei der Entscheidung über die Bitte Eures Volkes.\n\nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.", sourceObjective = "Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zu Thrall nach Orgrimmar, Hauptstadt von Durotar, bringt.", progress = "Ihr seid zurück, um mich zu sehen, {race}? Sprecht und beeilt Euch. Ich habe keine Zeit für die Förmlichkeiten Eures Volks.", completion = "<Thrall beginnt, den Brief zu lesen.>\n\nSylvanas ist sehr hartnäckig. Sie hat also einen von Silbermonds Helden geschickt... und was ändert das?", sourceObjectiveStatus = "unverified-source-field" }
quests[9627] = { id = 9627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue gegenüber der Horde", description = "Euer Volk litt unter dem großen Verrat der Allianz. Ihr habt darnassische Angriffe zurückgeschlagen und Spione aus Eisenschmiede ausgeschaltet. Nun gelang es Euch, vor den Toren Eurer Heimat, einen der mächtigsten Anführer der Geißel zu vernichten. Euer Wert steht außer Frage.\n\nEs ist offensichtlich, dass wir einander brauchen. Kehrt zu Lor'themar zurück. Berichtet ihm, dass ich seine Botschaft laut und deutlich vernommen habe.\n\n<Der Kriegshäuptling zerknüllt den Brief in seiner Hand.>\n\nWillkommen in der Horde, Elf.", sourceObjective = "Kehrt nach Silbermond zurück und erstattet Lor'themar Theron Bericht.", completion = "Eure Taten waren den Zielen unseres Volkes sehr dienlich. Nicht nur, dass Thrall nun davon überzeugt ist, dass wir uns dem Feind gegenüber behaupten können, nein, er glaubt außerdem, über uns und unsere Verbundenheit mit der Scherbenwelt, Kontakt zu den Überlebenden seines Volkes aufnehmen zu können.\n\nNicht gerade die Wahrheit, aber auch keine Lüge.\n\nBereitet Euch auf große Veränderungen vor, {name}. Wir sind nun offiziell ein Teil der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9628] = { id = 9628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergung der Daten", description = "Es ist zu spät, um den Kartografen beim Abschluss ihrer Mission zu helfen, aber es scheint, als hätten sie die Angaben gesammelt, nach denen Herold Mikolaas gefragt hat. Der Kristall, der ihre Vermessungsdaten beinhaltet, befand sich nicht unter ihren durchwühlten Habseligkeiten, also muss er den Naga der Hasspranken in die Hände gefallen sein.\n\nIhr wisst, dass Herold Mikolaas sehr betrübt über den Verlust des Teams sein wird, aber auch, dass er die Vermessungsdaten gerne retten würde.", sourceObjective = "Erlangt den Vermessungsdatenkristall von den Hasspranken nahe der toten Kartografen wieder und bringt ihn zu Herold Mikolaas bei der Blutwacht.", progress = "Konntet Ihr herausfinden, was das Vermessungsteam von seiner Rückkehr abgehalten hat?", completion = "<Ihr erzählt Herold Mikolaas vom Schicksal des Vermessungsteams. Er nimmt den Kristall von Euch entgegen, aber schweigt für einen langen Augenblick.>\n\nEs waren gute Männer, {name}, sie wussten, dass ihre Mission gefährlich sein würde. Ich bin Euch dankbar für das Auffinden des Teams und die Wiederbeschaffung des Kristalls.\n\n\n\nWie haben bereits zu viele unserer Männer verloren, dabei hat unsere Mission gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9629] = { id = 9629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurz geschnappt", description = "Die Murlocs der Schwarzschlammküste an der südwestlichen Küste sind merkwürdige Kreaturen. Oft verhalten sie sich nach keinem richtigen Verhaltensmuster und manchmal legen sie ein erstaunliches Organisationsgeschick an den Tag.\n\nIch verfolge ein paar Theorien, die belegen könnten, wie sie das zustande bringen. Bis vor kurzem konnte ich das Ganze jedoch noch nicht untersuchen. Ich habe eine Methode entwickelt, die es mir ermöglichen wird, die für mich interessanten Murlocs im Auge zu behalten, ohne ihnen dadurch längerfristig zu schaden oder ihr natürliches Verhalten zu stören. Wenn Ihr mir bei der Anbringung der Sender behilflich sein wollt, werde ich Euch gerne für Eure Unterstützung bezahlen.", sourceObjective = "Morae bei der Blutwacht möchte, dass Ihr 6 Späher der Schwarzschlammküste mit einem Murlocsender 'markiert'.", progress = "Hat der Apparat funktioniert? Habt Ihr die Murlocs für meine Untersuchungen markiert?", completion = "Gut gemacht, {name}. Ich hatte befürchtet, dass der Sender beim Markieren beschädigt werden könnte, aber scheinbar ist ja alles wie geplant verlaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9630] = { id = 9630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medivhs Tagebuch", description = "Euer Name spricht sich herum, {name}. Ihr habt es nach Karazhan und wieder heraus geschafft - das ist mehr, als die meisten Sterblichen von sich behaupten können.\n\nIhr müsst mir einen ganz besonderen Gefallen tun. Im Rahmen unserer Forschungen hat das Violette Auge versucht, an Medivhs Tagebuch zu kommen.\n\nUnglücklicherweise kam keiner der Agenten, die wir hineingeschickt haben, wieder heraus. Wravien war der letzte, den wir geschickt haben. Sucht ihn und erkundigt Euch, ob es neue Anhaltspunkte zu diesem Tagebuch gibt.", sourceObjective = "Erzmagier Alturus am Gebirgspass der Totenwinde möchte, dass Ihr nach Karazhan geht und mit Wravien sprecht.", completion = "Welch unermesslicher Wert an Informationen... Ich könnte Jahre hier verbringen! Ich bin sicher, Dalaran wird das verstehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9631] = { id = 9631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe unter Kollegen", description = "Es gibt da ein kleines Detail, das ich vergessen habe. Die Überreste von Medivhs Essenz in diesem kleinen Knochenfragment ist völlig ohne Leben, genauso wie Arcanagos'.\n\nEs gibt jedoch einen Weg, sie wieder zum Leben zu erwecken. Und ich weiß auch genau, wer uns dabei helfen kann.\n\nReist nach Area 52 in Nethersturm und zeigt Kalynna Lathred das Knochenfragment. Sie wird wissen, was damit zu tun ist.", sourceObjective = "Bringt das verkohlte Knochenfragment zu Kalynna Lathred in Area 52 im Nethersturm.", progress = "Alturus hat Euch geschickt. Die Sterne haben von Eurer Ankunft gesprochen.", completion = "Alturus möchte einen ganzen Drachen von den Toten zurückholen? Keine leichte Aufgabe.\n\nLasst uns darüber reden, wie wir uns gegenseitig unterstützen können, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9632] = { id = 9632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Verbündete", description = "Herold Mikolaas hat bei der Sicherung der Blutwacht eine äußerst löbliche Arbeit geleistet, {class}, allerdings sind unsere Feinde zahlreich und unsere Ressourcen gering.\n\nUnsere Gegner kennen unsere Schwäche nur zu gut, aber sie haben dabei nicht an Eure Verbindung zu den Streitkräften der Allianz gedacht. Ich habe ein Vorstellungsschreiben für Auberdine vorbereitet, der nächstgelegenen Siedlung der Allianz, in dem ich ihnen eine Zusammenarbeit beim Kampf gegen unsere Feinde vorschlage. Nehmt das Schreiben an Euch und sucht Jägerin Kella Nachtbogen auf, sie befindet sich in der Nähe der Docks westlich der Exodar.", sourceObjective = "Bringt das Vorstellungsschreiben zu Jägerin Kella Nachtbogen.", progress = "Seid gegrüßt, {class}. Was habt Ihr da?", completion = "Ich kann Euch helfen, nach Auberdine zu kommen. Glücklicherweise ist es nur eine kurze Fahrt mit dem Schiff von hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[9633] = { id = 9633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg nach Auberdine", description = "Wenn Ihr am Dock wartet, werdet Ihr das Schiff sehen, das aus Auberdine von der Dunkelküste hier ankommt. Sobald alle Passagiere von Bord gegangen sind, könnt Ihr einsteigen.\n\nDas Schiff wird nach einer kurzen Fahrt in Auberdine anlegen und Ihr werdet Euer Schreiben überbringen können.\n\nAm besten bringt Ihr es zu Thundris Windwirker, er ist ein alter Freund von mir und genießt überall hohes Ansehen.", sourceObjective = "Nehmt das Schiff in der Nähe von Jägerin Kella Nachtbogen nach Auberdine. Bringt das Vorstellungsschreiben zu Thundris Windwirker, sobald Ihr in Auberdine angekommen seid.", progress = "Willkommen in Auberdine. Was bringt Euch zur Dunkelküste?", completion = "<Thundris nimmt das Schreiben von Euch entgegen, liest es und nickt.>\n\nDie Inseln der {race}, die Azurmythosinsel und die Blutmythosinsel, wurden vor langer Zeit von meinen Leuten bewohnt. Einige der Bedrohungen, denen sich Anachoret Paetheus und seine Brüder und Schwestern jetzt stellen müssen, sind alte Feinde der Nachtelfen.\n\nIch bin mir sicher, dass man unseren neuen Verbündeten hier in Auberdine alles zur Verfügung stellen möchte, das benötigt wird. Sobald ich mit den Bewohnern der Stadt und den Schildwachen gesprochen habe, werde ich Paetheus benachrichtigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9634] = { id = 9634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubtiere aus einer anderen Welt", description = "Eine Sache, die wir auf unseren Reisen gelernt haben, ist, dass man bei der Einführung von Wildtieren aus einer anderen Welt besonders vorsichtig sein muss. Als die Exodar abstürzte, hatte sie Exemplare verschiedenster Tierarten aus der Scherbenwelt an Bord, einschließlich eines insektenartigen Raubtiers, dem Felshetzer.\n\nBei dem Absturz starben einige der Tiere, aber viele andere überlebten und suchten in der Wildnis das Weite. Wenn wir sie nicht in Schach halten, werden sie hier auf den Inseln das natürliche Gleichgewicht von Jägern und Gejagten stören.\n\nIhr findet die Hetzer westlich von Kessels Wegelager, in der Nähe der Küste.", sourceObjective = "Tötet 10 junge Blutfelshetzer und kehrt danach zu Vorkhan dem Elekktreiber bei Kessels Wegelager auf der Blutmythosinsel zurück.", completion = "Gut gemacht, {name}. Der Felshetzerbestand wird zwar nur für einige Zeit begrenzt bleiben, aber es ist ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[9635] = { id = 9635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schockdrosselnde Partikelextraktor!", description = "Das Sumpfgas ist wirklich erstaunlich und kann sehr nützlich sein, Mann! Aber zuerst müsst Ihr in der Lage sein, es aufzusaugen, und dazu, mein Freund, braucht Ihr einen schockdrosselnden Partikelextraktor.\n\nNun, ich könnte Euch einfach die Baupläne geben, aber erst will ich etwas dafür haben. Wie wär's mit ein paar Ersatzteilen? Als ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der kaputten Dampfpumpe im Todesmoor herum, ganz im Nordosten.\n\nIch habe gehört, dass die siechenden Riesen die Teile überall in dem ausgetrockneten See verteilt haben.", sourceObjective = "Bringt 15 Dampfpumpenteile zu Mack Dyver in Zabra'jin in den Zangarmarschen.", progress = "Habt Ihr die Teile schon? Ich bin hier mit Tauchen beschäftigt.", completion = "Schön! Wenn wir jetzt noch einen Kaugummi, eine Wäscheklammer, Schrumpfschlauch und etwas klebriges Geschenkband hätten, könnten wir wirklich etwas daraus machen!\n\nOk, ok, ich glaube, Ihr habt Euch das verdient, {name}. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9636] = { id = 9636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schockdrosselnde Partikelextraktor!", description = "Habt Ihr das Sumpfgas gesehen? Ist es nicht einfach klasse?\n\nMan braucht jedoch einen schockdrosselnden Partikelextraktor, um es aufzusaugen. Ich könnte Euch die Pläne dafür geben, aber zuerst brauche ich ganz dringend ein paar Ersatzteile, um ein paar Sachen hier zu reparieren.\n\nAls ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der Dampfpumpe im Todesmoor im Nordosten herum. Ich glaube, die siechenden Riesen haben die Pumpe kaputtgemacht.\n\nWollen wir uns gegenseitig helfen?", sourceObjective = "Bringt 15 Dampfpumpenteile zu K. Lee Kleinfrey in Telredor in den Zangarmarschen.", progress = "Habt Ihr die Teile schon? Ich muss die Kompressionsspule reparieren, bevor Anachoret Ahuurn mir im Nacken sitzt!", completion = "Klasse! Und mal ehrlich, welcher Ingenieur hat je genug Ersatzteile zur Hand? Hey, vielleicht könnte ich ja ein paar von den übrigen Teilen verkaufen und mir etwas von Tigule und Forors Erdbeereiscreme holen?! Ich liebe Erdbeeren! Denkt Ihr, man bekommt die hier irgendwo?\n\nOk, ok, Ich glaube, Ihr habt Euch das verdient, {name}. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9637] = { id = 9637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalynnas Bitte", description = "Ich habe die Kirin Tor verlassen, weil ich nach Wissen strebte, das von meinem Orden verboten wurde. Es ist mehr als ironisch, dass ich nun gebeten werde, sie mit genau diesem Wissen zu unterstützen.\n\nWenn ich Euch diesen Gefallen tun soll, dann müsst Ihr erst etwas für mich tun. Beschafft mir die beiden Folianten, nach denen ich schon so lange suche.\n\nDer erste heißt Dämmerfoliant und gehört dem orcischen Hexenmeister Nethekurse. Der zweite ist als Buch der vergessenen Namen bekannt und gehört einem Arakkoa namens Dunkelwirker Syth.", sourceObjective = "Kalynna Lathred möchte, dass Ihr den Dämmerfolianten vom Großhexenmeister Nethekurse in den Zerschmetterten Hallen der Höllenfeuerzitadelle und das Buch der vergessenen Namen von Dunkelwirker Syth in den Sethekkhallen in Auchindoun besorgt.\n\nIhr müsst diese Quest auf dem Schwierigkeitsgrad 'Heroisch' abschließen.", progress = "Habt Ihr die Folianten, die ich suche, {name}?", completion = "Ausgezeichnet, {name}. Ich versuche schon seit sehr langer Zeit, an diese Bücher heranzukommen. Welch Glück, dass wir uns gegenseitig helfen konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9638] = { id = 9638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In guten Händen", description = "Hätte ich nach diesem Tagebuch suchen sollen? Das kann nicht sein... Ich erinnere mich nicht daran...\n\nAber natürlich! Ihr meint Gradav. Er war auf der Suche nach dem Buch, als ich hierher kam. Er hat es bestimmt schon gefunden, warum fragt Ihr ihn nicht einmal?\n\nIch würde Euch ja helfen... aber diese Bücher sind einfach so... interessant!", sourceObjective = "Sprecht mit Gradav in der Bibliothek des Wächters in Karazhan.", completion = "Seht Ihr nicht, dass ich hier beschäftig bin? Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[9639] = { id = 9639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamsis", description = "Tagebuch? Welches Tagebuch? Ihr meint sicher Kamsis!\n\nGeht und fragt sie danach. Ich kann mein Projekt jetzt nicht allein lassen, sonst geht meine ganze Arbeit verloren!", sourceObjective = "Sprecht mit Kamsis in der Bibliothek des Wächters in Karazhan.", completion = "Dieses Tagebuch von dem Ihr sprecht... Ich wurde hierher geschickt, um danach zu suchen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[9640] = { id = 9640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arans Schemen", description = "Lasst mich kurz nachdenken. Das Violette Auge... Medivhs Tagebuch...  Oh ja, jetzt erinnere ich mich.\n\nIch glaube, ich hatte das Tagebuch, nach dem Ihr sucht, bevor ich anfing, diese Schriftrollen zu lesen...\n\nAran... genau, Aran hat mich darum gebeten.  Und das auch noch so nett.  Ich musste es ihm einfach geben.  Schließlich ist er Medivhs Vater, wusstet Ihr das?", sourceObjective = "Beschafft Medivhs Tagebuch und kehrt zu Kamsis in der Bibliothek des Wächters in Karazhan zurück.", progress = "Wart Ihr nicht auf der Suche nach einem Tagebuch oder so?", completion = "Habt Ihr gefunden, was Ihr gesucht habt?  Ihr habt doch etwas gesucht, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[9641] = { id = 9641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestrahlte Kristallsplitter", description = "Der Absturz der Exodar hat auf der Blutmythosinsel überall Stücke schädlicher Kristalle verstreut, die das Wasser und den Rest des Landes verderben.\n\nWir haben sogar schon Stücke der Kristalle im Fleisch von Tieren gefunden, die uns normalerweise als Nahrungsquelle dienen. Ich habe einen Weg gefunden, wie man die Splitter reinigen und somit in zweckmäßige Kristalle verwandeln kann. Wenn Ihr mir genug Splitter besorgt, werde ich Euch einen vollständigen Kristall im Tausch dafür geben. Bislang konnte ich die Splitter in den Körpern von Bären, Felshetzern, Faltern und Treants finden, die den verderbten Teil der Insel bewohnen.", sourceObjective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr ihm 10 bestrahlte Kristallsplitter bringt.", progress = "Konntet Ihr Kristallsplitter von den Kreaturen der Blutmythosinsel einsammeln?", completion = "Gut gemacht. Diese Splitter werden als Rohmaterial für weitere Stärkungskristalle dienen.\n\nIhr könnt Euch einen der drei Typen aussuchen, die ich herstellen kann. Ich finde sie alle recht nützlich, je nachdem auf welche Beute man es abgesehen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9642] = { id = 9642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr bestrahlte Kristallsplitter", progress = "Solltet Ihr noch über mehr bestrahlte Kristallsplitter verfügen, tausche ich sie gerne gegen einen weiteren meiner Kristalle ein.", completion = "Sehr schön, hier sind meine Kristalle, {name}. Verwendet sie weise." }
quests[9643] = { id = 9643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Würgeranken", description = "Ein guter Förster findet für jede der vorhandenen Ressourcen eine Verwendung, {class}. Auch die skurrilsten Kreaturen besitzen Eigenschaften, die wir zu unserem Vorteil nutzen können.\n\nDa die Blutwacht ständig von den Sonnenfalken angegriffen wird, suchen wir nach einer Vielzahl natürlicher Verteidigungsmechanismen, die auch als Fallen dienen können. Die dornigen Ranken der Peitscher eignen sich perfekt für den Bau von Fallen, die meiner Vorstellung entsprechen. Die Kombination von scharfen Dornen und tödlichem Gift wird unachtsame Angreifer ausschalten. Bringt mir Ranken von mutierten Würgern, damit ich mit der Arbeit beginnen kann.", sourceObjective = "Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr ihm 6 dornige Würgeranken bringt.", progress = "Habt Ihr die Würgeranken bekommen?", completion = "Das scheint mir stabil genug für meine Konstruktion. Danke für die Hilfe, {name}. Euer Unterstützung bei der Verteidigung der Blutwacht wird nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9644] = { id = 9644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken der Nacht", description = "Unsere Vorbereitungen sind fertig. Ich habe die Materialien, die Ihr gesammelt habt, in diese Urne getan. Bringt sie zur Terrasse des Meisters, wo der Kampf stattgefunden hat, und zündet sie an.\n\nDie freigesetzte Energie wird die verkohlten Überreste von Arcanagos wieder zum Leben erwecken. Besiegt die Kreatur und entzieht ihr sofort ihre Essenz! Ihr werdet sie zu Alturus bringen müssen.\n\nWenn Ihr scheitert, sagen die Sterne voraus, werdet Ihr ein großes Unheil auf die Himmel loslassen.\n\nEin Unheil namens Schrecken der Nacht!", sourceObjective = "Geht zur Terrasse des Meisters in Karazhan und benutzt Kalynnas Urne, um den Schrecken der Nacht zu rufen. Entzieht dem Körper des Schreckens die schwache arkane Essenz und bringt sie zu Erzmagier Alturus.", progress = "Welche Neuigkeiten bringt Ihr, {name}?", completion = "Das ist erstaunlich! Ihr habt nicht nur Medivhs Tagebuch zurückgebracht, sondern auch noch einen Teil seiner Essenz!\n\nSo schwach sie auch sein mag, sie wird uns wertvolle Informationen über Medivh liefern können. Wir werden Euch das nicht vergessen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9645] = { id = 9645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse des Meisters", description = "Tagebuch? Welches Tagebuch?\n\nOh, richtig. Dieses Tagebuch! Das Violette Auge hat mich deswegen hierher geschickt. Ich erinnere mich.\n\n<Kamsis zeigt auf eine Seite im Tagebuch>\n\nDies ist die Seite, an der Alturus interessiert ist. Wusstet Ihr, dass andere Leute Tagebücher benutzen, um ihre Erinnerungen aufzuzeichnen, während Medivhs Tagebuch genau seine Erinnerungen sind?\n\nProbiert es aus. Geht zur Terrasse des Meisters und lest die Seite. Ihr werdet sehen, was ich meine. Wenn Ihr schon da seid, könnt Ihr auch gleich Alturus Bericht erstatten. Ich fürchte, ich bin hier noch eine Weile beschäftigt.", sourceObjective = "Geht zur Terrasse des Meisters in Karazhan und lest Medivhs Tagebuch. Kehrt danach mit Medivhs Tagebuch zu Erzmagier Alturus zurück.", progress = "Ihr seid zurück! Was für Nachrichten bringt Ihr?", completion = "Es ist eine Schande, dass die Agenten, die wir geschickt haben, Karazhans Magie unterlegen sind. Zumindest konntet Ihr beschaffen, wonach sie suchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9646] = { id = 9646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Todespranke", description = "Auf Anweisung von Herold Mikolaas: Man wird demjenigen ein Kopfgeld von 18 Silber auszahlen, der den Beweis für den Tod des räuberischen Bären Todespranke erbringen kann.\n\nTodespranke wird als besonders gefährlich eingestuft und ist für den Tod eines Vermessungsteams an der Küste im Nordwesten der Blutwacht verantwortlich. Reisende werden angehalten, diese Gegend zu meiden.", sourceObjective = "Bringt Todesprankes Tatze zu Herold Mikolaas bei der Blutwacht.", progress = "Wie kann ich Euch helfen, {class}?", completion = "Gut gemacht. Von dem, was ich gehört habe, war es wohl kein leichter Kampf. Ihr habt Euch Eure Belohnung mehr als verdient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9647] = { id = 9647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausmerzen der Falter", description = "Als wird den Faltern das erste Mal auf der Insel begegneten, zeigten sie nur wenige Anzeichen von Mutation. Als sich die Verderbnis immer weiter ausbreitete, wurden die Motten und andere Arten jedoch immer mehr verseucht.\n\nEs ist jetzt sogar soweit gekommen, dass sie fast alles, mit dem sie in Berührung kommen, beschädigen. Der Schaden wird von den Kristallsplittern, die beim Absturz der Exodar zerbrochen wurden, noch verstärkt. Uns bleibt keine andere Wahl, aber wir müssen die Motten, die das Land nördlich der Blutwacht behausen, ausmerzen.", sourceObjective = "Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr 10 königliche blaue Falter tötet.", completion = "Es gilt jetzt, eine längerfristige Lösung zu finden, um die Arten wieder in ihren Urzustand zurückzuführen. Momentan ist das zeitweilige Ausmerzen ihres Bestandes jedoch die beste Methode. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9648] = { id = 9648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzsammlung von Maatparm", description = "Habt Ihr gewusst, dass das Sammeln von Pilzen gefährlicher als der Verzehr von Pilzen ist? Pilzsammler begeben sich ins Unbekannte - dazu kommen noch die Gefahren, die in der Wildnis lauern!\n\nWas wäre das Leben ohne ein paar Wagnisse? Ich benötige Pilze für meine Sammlung. In dieser unerforschten Natur werdet Ihr vier Arten finden: Wasserstinkmorchel, Blutpilz, ruinöser Birkensporling und Teufelszapfenfungus. Sie sind einzigartig in unterschiedlichen Gebieten der Blutmythosinsel. Bringt sie mir.", sourceObjective = "Maatparm bei der Blutwacht möchte 1 Wasserstinkmorchel, 1 Blutpilz, 1 ruinösen Birkensporling und 1 Teufelszapfenfungus.", progress = "Vergesst nicht, die von mir benötigten Pilze sind einzigartig in unterschiedlichen Gebieten der Blutmythosinsel.", completion = "Nun, ich hatte Euch gewarnt - oder etwa nicht? Ich hoffe diese kleine Bezahlung wird Euch für Eure Unannehmlichkeiten etwas entschädigen können. Kehrt zu mir zurück, sobald Ihr Euch ein wenig erholt habt, dann habe ich vielleicht noch eine Aufgabe für Euch - mit Pilzen natürlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[9649] = { id = 9649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yseras Tränen", description = "Gut, Euch wieder zu sehen, {name}! Ihr wart bei meiner letzten Aufgabe sehr tüchtig. Seid Ihr vielleicht an einer weiteren interessiert?\n\nIm Nordosten liegt die Insel Drachenfels, sie beheimatet eine sehr seltene Pilzart, die unter dem Namen Yseras Träne bekannt ist - benannt nach den grünen Drachlingen, die auf dieser Insel hausen. Ich brauche nicht viele von diesen Pilzen, möchte Euch aber dennoch warnen, denn die Bewohner dieser Insel mögen keine Besucher. Gebt auf Eure Schritte Acht.", sourceObjective = "Maatparm bei der Blutwacht möchte 2 Yseras Tränen.", progress = "Schon wieder zurück?", completion = "Ich hoffe diese Aufgabe hat nicht zu viel von Euch abverlangt, {name}. Ihr habt erneut bewiesen, dass Ihr ein fähiger und aufmerksamer {race} seid. Habt meinen Dank und natürlich eine kleine Abfindung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9650] = { id = 9650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Zunahme", description = "Lasst uns meine magischen Eigenschaften verstärken. Das macht Sinn. Schließlich war ich, als ich noch am Leben war, eine Zauberin.\n\nNur weil man in einer Waffe gefangen ist, heißt das noch lange nicht, dass man ein Rüpel sein muss.\n\nIch möchte, dass Ihr ein paar Materialien sammelt.", sourceObjective = "<TXT>", sourceObjectiveStatus = "unverified-source-field" }
quests[9651] = { id = 9651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Zunahme", description = "Lasst uns meine magischen Eigenschaften verstärken. Das macht Sinn. Schließlich war ich, als ich noch am Leben war, eine Zauberin.\n\nNur weil man in einer Waffe gefangen ist, heißt das noch lange nicht, dass man ein Rüpel sein muss.\n\nIch möchte, dass Ihr ein paar Materialien sammelt.", sourceObjective = "<TXT>", sourceObjectiveStatus = "unverified-source-field" }
quests[9652] = { id = 9652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körperliche Erweiterung", description = "Ich hätte nichts dagegen... Wir können genauso gut das Beste aus dieser Lage machen... in meinem Fall die Tatsache, dass ich eine Waffe bin. Ich könnte einfach die beste Waffe werden, die ich sein kann.\n\nJa, lasst uns das versuchen. Einen schärferen Schliff, einen stärkeren Griff... das klingt doch gut.\n\nIch möchte, dass Ihr ein paar Dinge für mich sammelt." }
quests[9653] = { id = 9653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körperliche Erweiterung", description = "Ich hätte nichts dagegen... Wir können genauso gut das Beste aus dieser Lage machen... in meinem Fall die Tatsache, dass ich eine Waffe bin. Ich könnte einfach die beste Waffe werden, die ich sein kann.\n\nJa, lasst uns das versuchen. Einen schärferen Schliff, einen stärkeren Schwertgriff... das klingt doch gut.\n\nIch möchte, dass Ihr ein paar Dinge für mich sammelt." }
quests[9654] = { id = 9654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gut abgerundete Verteidigung", description = "Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.\n\nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.", sourceObjective = "Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9655] = { id = 9655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilende Verstärkung", description = "Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.\n\nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.", sourceObjective = "Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.", sourceObjectiveStatus = "unverified-source-field" }
