quests[9657] = { id = 9657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffskanalisierung", description = "Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.\n\nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.", sourceObjective = "Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.", sourceObjectiveStatus = "unverified-source-field" }
