quests[9661] = { id = 9661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gut abgerundete Verteidigung", description = "Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.\n\nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.", sourceObjective = "Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9662] = { id = 9662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keannas Freiheit", description = "Meine Erinnerungen... ich kann mich wieder an alles erinnern! Mein Geist fühlt sich an, als würden Puzzleteile wieder zusammengefügt.\n\nIch war eine der Ersten, die nach Karazhan geschickt wurden, um hier Nachforschungen anzustellen, nachdem sich der Ort verändert hatte. Der Dämon Malchezaar hat mich entdeckt.\n\nIch habe schnell bemerkt, dass ich für ihn kein Gegner bin. Ich könnte fühlen, wie seine Magie meine Seele einfing.\n\nIm letzten Moment habe ich einen Teil meiner Selbst, meiner Erinnerungen versteckt... an dem einzigen Ort, der mir einfiel: meine Waffe. Malchezaar hat meine Seele. Ihr müsst mir helfen, sie zurück zu bekommen!", sourceObjective = "Besiegt Malchezaar in Karazhan während Ihr Keannas Wille angelegt habt. Keannas Erscheinung muss überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9663] = { id = 9663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Korsallauf", description = "Ihr kommt gerade richtig, {name}. Die Aktivitäten der Blutelfen haben sich in der letzten Woche fast verdoppelt. Unsere Agenten haben uns mitgeteilt, dass die Blutelfen, die sich selbst Sonnenfalken nennen, einen baldigen Angriff auf die Azurmythosinsel planen. Ihr müsst unseren Verbündeten und Landsmännern eine Warnung zukommen lassen.\n\nWarnt den Oberhäuptling bei der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus' Ankerplatz.\n\nDie Zeit drängt, deshalb werde ich Euch meinen Elekk zur Verfügung stellen. Beeilt Euch!", sourceObjective = "Kessel bei Kessels Wegelager möchte, dass Ihr den Oberhäuptling der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus' Ankerplatz vor der unmittelbar bevorstehenden Blutelfeninvasion warnt. Ihr habt 15 Minuten. Kehrt anschließend zu Kessel zurück. Denkt daran, dass Elekks wasserscheu sind!", completion = "Gut gemacht, {name}. Dies war ein Test Eurer Fähigkeiten, aber Ihr habt mit wehenden Fahnen bestanden. Um ein Soldat der Hand von Argus zu werden, gilt es viele dieser Tests zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9664] = { id = 9664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Befestigungen", description = "Willkommen in den Pestländern, {name}. Wie Ihr wisst, behaupten sich die Verlassenen und ihre Verbündeten entgegen all unserer Anstrengungen in den von hier aus westlich gelegenen Ländern. Die Kommandanten der Allianz haben beschlossen, dass hier im Osten neue Befestigungen errichtet werden sollen, um die Schlinge um unseren Feind noch etwas enger zu schnüren.\n\nLange seit den Tagen Lordaerons verlassene und herrenlose Türme müssen für diesen Zweck erobert und wieder aufgebaut werden. Diese Länder hier sind gefährlich, wir brauchen Eure Hilfe.", sourceObjective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Weißbart bei der Kapelle des hoffnungsvollen Lichts zurück.", completion = "Sehr gut, {name}. Es ist äußerst wichtig, dass wir diese Türme halten. Wir müssen sie vor zukünftigen Angriffen schützen und brauchen noch so lange Eure Hilfe, bis Verstärkung zur Sicherung dieses Gebiets eintrifft.", sourceObjectiveStatus = "unverified-source-field" }
quests[9665] = { id = 9665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Verteidigung", description = "Agenten der Verlassenen sind hinter das Vorhaben der Allianz gekommen. Sie wollen neue Stützpunkte bei verlassenen Türmen hier in den östlichen Pestländern einrichten.\n\nWir dürfen auf keinen Fall zulassen, dass sie sich an unserer östlichen Grenze dauerhaft festsetzen, wir müssen den Einfall der Allianz abwehren. Wir beabsichtigen sie aus jeglichen Türmen, die sie bereits besetzt haben, zu vertreiben. Dann gilt es diese Türme zu verteidigen und weitere Eroberungsversuche abzuwehren.", sourceObjective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Gormok bei der Kapelle des hoffnungsvollen Lichts zurück.", completion = "Das sind gute Neuigkeiten, {name}. Bis wir die Kräfte der Allianz gänzlich vertrieben haben, wird es hier in den Pestländern dauerhaft zu Kämpfen kommen.\n\nIch hoffe, dass Ihr uns bis zu diesem Tag auch noch weiterhin unterstützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9666] = { id = 9666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonstration der Macht", description = "Habt Ihr die Schlangenwesen gesehen? Die, die sich selbst Naga nennen?\n\n<Kessel spuckt.>\n\nSie haben es vor drei Nächten gewagt, im Schutze der Dunkelheit bis zu diesem Lager vorzudringen. Denkt nur an die Dreistigkeit dieser primitiven Biester!\n\nIhr müsst ihrem Anführer eine Botschaft überbringen, {name}. Im Nordosten liegt die Hassprankenzuflucht, der Sitz von Lord Xiz. Findet ihn, tötet ihn an Ort und Stelle und treibt diesen Banner durch seinen Körper.\n\nLasst sie vor Furcht erschaudern, wann immer sie diese Standarte sehen!", sourceObjective = "Kessel bei Kessels Wegelager auf der Blutmythosinsel möchte, dass Ihr Lord Xiz bei der Hassprankenzuflucht tötet und das Banner der Draenei durch seinen Körper stoßt.", completion = "Es tut mir leid, dass Ihr das tun musstet, {name}. Rohe Gewalt entspricht nicht der Natur der {race}, aber manchmal ist sie der einzige Weg.\n\nUnglücklicherweise gehört dies zum Leben und man versteht es oft erst dann, wenn es zu spät ist. Genau wie mit den Orcs, die unsere Brüder und Schwestern abschlachteten.\n\nEin Mitglied der Hand von Argus zu werden, ist ein Prozess der Wiedergeburt. Mit der Geburt kommt bekanntlich auch der Schmerz...", sourceObjectiveStatus = "unverified-source-field" }
quests[9667] = { id = 9667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Prinzessin der Tannenruhfeste", description = "Helft mir, {name}! Die Sichelklauen haben mich gefangen genommen und wollen mich ihren üblen Göttern opfern!\n\nDer Oberhäuptling der Sichelklauen ist in Besitz der Schlüssel für den Käfig. Damit er auftaucht, müsst Ihr die bösartigen Furbolgs der Sichelklauen töten, die in der Enklave hausen. Sie liegt zwei Lager weiter im Westen. Wenn Ihr genug von ihnen niedergestreckt habt, wird er kommen, um sich zu rächen! Tötet ihn, sobald er sich zeigt, und nehmt die Schlüssel an Euch!\n\nMein Vater wird Euch reichlich entlohnen, wenn Ihr es schafft mich zu rettet!", sourceObjective = "Befreit die Prinzessin der Tannenruhfeste aus ihrem Käfig und sprecht anschließend mit Botschafter Olorg der Tannenruhfeste bei der Blutwacht.\n\nIhr müsst den Oberhäuptling der Sichelklauen töten, um an den Schlüssel für den Käfig zu gelangen.", completion = "Ihr habt erneut bewiesen, dass Ihr all dem entsprecht, was in der Prophezeiung vorhergesagt wurde. Ihr habt den ewigen Dank des Oberhäuptlings, {name} - und Ihr habt die Wahl zwischen diesen Relikten der Tannenruhfeste...", sourceObjectiveStatus = "unverified-source-field" }
quests[9668] = { id = 9668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstattet Exarch Admetius Bericht", description = "Ein Soldat der Hand von Argus ist vielerlei: gehorsam, mutig, intelligent und vor allem ehrenhaft. Vielleicht verfügt Ihr schon jetzt über einige dieser Züge, {class}.\n\nErstattet Exarch Admetius bei der Blutwacht Bericht, wenn Ihr der Hand noch immer beitreten möchtet. Er und seine Untergebenen werden Euch weiter auf dem Weg zum Draeneisoldaten ausbilden.\n\nUnd vergesst dies nicht, {name}: Ehrenhafte Personen handeln nicht immer ehrenhaft. Manchmal ist es ihnen nicht möglich.\n\nIhr findet die Blutwacht ganz einfach diese Straße entlang, in Richtung Norden.", sourceObjective = "Sprecht mit Exarch Admetius bei der Blutwacht.", completion = "Ich hatte es bereits im Gefühl, dass Ihr es bis hierher schaffen würdet, {class}. Wenn Ihr noch weiter kommen möchtet, bin ich gerne bereit Euch zu unterrichten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9669] = { id = 9669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsreise in den Tod", description = "Vor etwa einer Woche war ich mit meinem Forschungsteam auf einem Erkundungstrip im Westen der Blutmythosinsel, als wir plötzlich von blutdurstigen Spinnen angegriffen wurden. Die Auswirkungen der Kristallverseuchung waren unverkennbar, da diese Spinnen extrem groß und aggressiv waren.\n\nIch schaffte es zu fliehen, aber mein Team hatte nicht so viel Glück. Wir dürfen nicht zulassen, dass andere das gleiche Schicksal ereilt. Geht nach Westen zum Goldweberpass und vernichtet die Spinnen und ihre Matriarchin Zarakh.", sourceObjective = "Tötet 8 Mythosspinner, 8 Mythosfänger und ihre Anführerin Zarakh. Kehrt anschließend zu Achelus bei der Blutwacht zurück.", completion = "Unglaublich! Konntet Ihr andere Überlebende finden?\n\n<Achelus senkt seine Stimme zu einem Flüstern.>\n\nIch möchte ehrlich mit Euch sein, {name}, niemand sonst wollte diesen Auftrag annehmen. Ihr seid sehr mutig, {class}...", sourceObjectiveStatus = "unverified-source-field" }
quests[9670] = { id = 9670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie leben! Vielleicht...", description = "Es war ein blutiges Gemetzel, {name}. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.\n\nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!\n\nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?\n\nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!", sourceObjective = "Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.", completion = "Ihr habt mehr als die Hälfte des Teams befreit! Der Exarch und die anderen bei der Blutwacht werden mit Sicherheit von Eurer heldenhaften Tat erfahren. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9671] = { id = 9671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Nachricht", sourceObjective = "Seid Ihr {name}? Es wurde auch Zeit! Ich war gerade dabei, die Suche nach Euch aufzugeben!\n\nBeim Briefkasten wartet eine dringende Nachricht auf Euch. Die Person, die sie mir übergeben hatte, war ein Admiral der Menschen von der Azurmythosinsel. Admiral Odesy-irgendwas... der Name ist mir entfallen. Er sagte, Ihr würde wissen, wer er sei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9672] = { id = 9672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Blutfluchs", description = "Getreuer Freund,\n\nmeine Hand zittert beim Schreiben dieses Briefs. Ich hoffe, dass er Euch rechtzeitig erreicht.\n\nLetzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.\n\nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich von Eurer Basis liegt, suchen?\n\nGruß,\n\nAdmiral Odesyus", sourceObjective = "Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.", completion = "Habt Ihr von dem Blutfluch gehört, Landratte? Nein, natürlich nicht. Der Blutfluch ist das, was all diese Schiffe hat sinken lassen. Der verderbte, entweihte Teil des Wassers hier wird Riff des Blutfluchs genannt - ein Teil der Welt, den Ihr niemals sehen möchtet. Ich bin hier selbst seit 20 Jahren.\n\nSkorbut, so ein Quatsch! Ich starb an diesen wilden Ufern als Drachenfutter... Ah, das ist wieder eine andere Geschichte, für ein anderes Mal. Jetzt müssen wir den armen Seelen helfen, die hier im Riff gefangen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9673] = { id = 9673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtierausbildung", description = "Nachdem Ihr nun alles über die Zähmung eines Tieres wisst, ist es an der Zeit, sich mit den Feinheiten der Pflege und Ausbildung Eures Begleiters vertraut zu machen. Sucht dazu Halthenis den Tierausbilder von Silbermond auf, er wird Euch alles Nötige beibringen.\n\nEr respektiert meine Schüler in höchstem Maße, solange Ihr Euch ihm gegenüber genauso respektvoll verhaltet. Enttäuscht mich also nicht.", sourceObjective = "Sprecht mit Halthenis in Silbermond.", completion = "Ihr habt also schon einiges gelernt, nicht wahr?\n\n<Halthenis begutachtet Euch eingehend.>\n\nMit Euren neu erlernten Fähigkeiten werdet Ihr der Stadt und unserer großen Sache gut dienen. Gebt mir einen Moment Zeit, um Euch zu zeigen, wie Ihr Euer Tier ausbildet und wie man ihm einige interessante Tricks, wie das Ausweiden Eurer Feinde, beibringen kann. Danach könnt Ihr Eures Weges gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9674] = { id = 9674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Naga des Blutfluchs", description = "Man sagt, dass dieses Land am lautesten geschrien hat, als die Welt geteilt wurde. Hier fielen tausende von Nachtelfen und an ihrer Stelle erhoben sich fürchterliche Kreaturen des Hasses - die Naga.\n\nIhrer wahnsinnigen Königin, Azshara, gehorsam ergeben, würden sie alles und jeden zerstören, der sich durch ihre Gewässer wagt. Es würde noch für tausende von Jahren so bleiben - bis zum heutigen Tag.\n\nZuerst gilt es die Naga des Blutfluchs aus dem Riff zu entfernen.", sourceObjective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 10 Naga des Blutfluchs tötet.", completion = "Ein guter Anfang, aber es gibt noch viel mehr zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[9675] = { id = 9675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtierausbildung", description = "Oh, da wäre noch etwas! Ihr solltet mit Ganaar bei der Exodar sprechen. Er wird Euch das letzte bisschen Wissen bezüglich der Pflege und Ausbildung Eures Begleiters lehren.\n\nIhr findet ihn in der südwestlichen Ecke der Händlertreppe.", sourceObjective = "Sprecht mit Ganaar bei der Händlertreppe der Exodar.", completion = "Zu wissen, wie man seinen Begleiter füttert und wiederbelebt, ist nicht nur ein zusätzlicher \"Leckerbissen\", wie Euer letzter Lehrer so gelinde sagte - es ist viel mehr. Mit der richtigen Ausbildung kann sich Euer Begleiter auf eine Weise verbessern, wie er es nie von alleine getan hätte.\n\nIch habe bereits viel von den Furbolgs gelernt, also gebt Acht und ich werde dieses Wissen an Euch weitergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9676] = { id = 9676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Paladin", description = "Mit dem Voranschreiten in Eurer Klasse, möchtet Ihr sicherlich von der Ausbildung profitieren, die Euch der Lehrer für Eure Klasse anbieten kann. Jesthenis Sonnensturm ist der Lehrer für junge Paladine hier auf der Insel der Sonnenwanderer. Sprecht mit Jesthenis und seht, welche Ausbildung er Euch anbieten kann. Es wird Euch etwas kosten, bringt also ein wenig Geld mit Euch.\n\nEuer Lehrer - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - befindet sich im unteren Teil des Sonnenturms.", sourceObjective = "Sprecht mit Jesthenis Sonnensturm - dem Paladinlehrer - im Sonnenturm auf der Insel der Sonnenwanderer.", completion = "Ich sehe Eure vor Stolz geschwollene Brust. Ihr glaubt Euch schon als einer der Blutritter.\n\nMit der Zeit werdet Ihr Euch einen Platz in unseren Reihen verdienen. Als Erstes müsst Ihr jedoch den Umgang und das Meistern des mächtigen Lichts erlernen. Verbessert Eure Waffenfertigkeit und erweist Euch als würdig.\n\nIhr müsst gut vorbereitet sein, um den Spott, die Angst und den Abscheu derer ertragen zu können, die Ihr zu beschützen geschworen habt. So ergeht es denjenigen, die nicht verstehen, welchen Preis es für die große Macht zu zahlen gilt, die sie beschützt. Geht mit erhobenem Haupt und gezückter Klinge voran, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9677] = { id = 9677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufforderung des Ritterfürsten Heldenblut", description = "{name}, Ihr habt Euch in Eurer frühen Ausbildung bereits selbst übertroffen und von den anderen, die Blutritter werden möchten, hervorgehoben. Ihr seid reif für die nächste Ausbildungsphase und dazu kommt, dass Ritterfürst Heldenblut höchstpersönlich nach Euch verlangt hat.\n\nIch zweifle nicht daran, dass Ritterfürst Heldenblut Eure Fähigkeiten und Eure Ausbildung einer Prüfung unterziehen möchte. Ihr findet ihn beim Hauptsitz der Blutritter in Silbermond beim Platz der Weltenwanderer. Alles Gute, {name}.", sourceObjective = "Sprecht mit Ritterfürst Heldenblut beim Platz der Weltenwanderer in Silbermond.", completion = "Willkommen, junger Initiand. Dass Ihr meiner Aufforderung so rasch nachgekommen seid, verheißt Gutes.\n\nLasst uns auf Belanglosigkeiten verzichten, sie passen besser zu Höflingen und ihresgleichen.\n\nEure schnellen Fortschritte haben meine Aufmerksamkeit auf sich gezogen, {name}. Wir werden sehen, ob Ihr Eure Lehrstunden wirklich zu Herzen genommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9678] = { id = 9678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Prüfung", description = "Ihr habt viel über das Kämpfen und Vergießen von Blut gelernt, Initiand, doch in unserem Orden geht es um viel mehr.\n\nDie Beherrschung des Lichts erfordert einen klaren Geist und enorme Willenskraft.\n\nOhne diese Eigenschaften seid Ihr nicht mehr wert als ein räudiger Streuner.\n\nAn den nordöstlichen Ausläufern der Geisterlande gibt es eine Insel, die Insel des Martyriums, auf der wir diese Eigenschaften formen. Versteckt in einer kleinen Höhle, steht eine Kohlepfanne. Kniet vor ihr, entzündet sie und konzentriert Euch auf das, was Ihr vor Euren Augen seht.", sourceObjective = "Reist zu der Insel, die Euch Ritterfürst Heldenblut beschrieben hat, sucht die Höhle und entzündet die Kohlepfanne. Kehrt, nachdem Ihr die erste Prüfung bestanden habt, zu Ritterfürst Heldenblut in Silbermond zurück.", completion = "Ich denke ich weiß, was Euch gerade durch den Kopf geht.\n\nJa, ich entsandte Stillstreich, um Euch zu töten.\n\nNehmt es mir nicht übel, {name}; es war eine notwendige Prüfung. Die Blutritter sind eine Ordensgemeinschaft, ja, doch müssen wir sicherstellen, dass unsere Brüder und Schwestern stets wachsam und vorbereitet sind. War Stillstreichs Tod tatsächlich notwendig, um Euch diese Lektion zu erteilen?\n\nJa, denn dies ist ein ebenso wichtiger Bestandteil Eurer Ausbildung wie das Schwerttraining.", sourceObjectiveStatus = "unverified-source-field" }
quests[9680] = { id = 9680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit aufwühlen", description = "Kamsis hatte Recht! Diese Information ist äußerst wichtig. \n\nWenn Medivh seine eigene Essenz in die Magie, die er benutzt hat, um den Drachen zu besiegen, hineingewebt hat, dann ist es ziemlich wahrscheinlich, dass wir einen schwachen Rest dieser Essenz aus den Überresten des Drachen gewinnen können. Welch großartige Erkenntnisse mögen wohl unter der Asche des Gebirgspass der Totenwinde liegen, die nur darauf warten, entdeckt zu werden.\n\nGeht zu den Bergen südlich von Karazhan und bringt mir ein Knochenfragment deutlich drachischen Ursprungs.", sourceObjective = "Erzmagier Alturus möchte, dass Ihr zu den Bergen südlich von Karazhan im Gebirgspass der Totenwinde geht und ein verkohltes Knochenfragment besorgt.", progress = "Habt Ihr das Knochenfragment, das ich brauche, {name}?", completion = "Ausgezeichnet! Auch wenn es klein ist, strotzt es nur so vor Energie, ich fühle es!", sourceObjectiveStatus = "unverified-source-field" }
quests[9681] = { id = 9681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Studie der Macht", description = "Haltet mich nicht für übermäßig grausam, {name}. Stillstreich hat sehr wohl gewusst, worauf er sich einlässt. Er verstand und akzeptierte seine Pflicht und wurde so ein leuchtendes Vorbild für alle aufstrebenden Blutritter.\n\nMeine Worte sind nicht als Grabesrede gedacht, {name}. Stillstreichs Dienste für uns gehören noch lange nicht der Vergangenheit an und Ihr werdet das Instrument seiner Wiederauferstehung sein.\n\nEure Ausbildung in der Kunst des Ordens hat gerade erst begonnen. Angesichts Kael'thas' Verrat und des Verlusts unserer Energiequelle, müsst Ihr neue Wege zur Beherrschung des Lichts erlernen. Sucht Magister Astalor Blutschwur auf.", sourceObjective = "Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9682] = { id = 9682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnungslosen...", description = "An einem Vorsprung des Riffs, noch tiefer im Wasser als die Naga des Blutfluchs, werdet Ihr die Hoffnungslosen finden: Reisende des Blutfluchs, Geister derer, die vom Blutfluch heimgesucht wurden.\n\nEs ist bedauerlich, was ich jetzt von Euch verlangen werde... aber sie müssen vernichtet und ihre Hüllen des Blutfluchs zu mir gebracht werden.\n\nIhre Seelen müssen erlöst werden. Kehrt zu mir zurück, wenn Ihr dergleichen getan habt und ich werde Euch eine letzte Aufgabe stellen.", sourceObjective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 4 Seelen des Blutfluchs zu ihm bringt.", progress = "Trauert ihrem Niedergang nicht nach, {name}.", completion = "Ihr habt den Hoffnungslosen einen großen Dienst erwiesen, {name}. Es gilt jedoch noch eine letzte Aufgabe zu erledigen: Tötet den Anführer des Blutfluchs.", sourceObjectiveStatus = "unverified-source-field" }
quests[9683] = { id = 9683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beendigung des Blutfluchs", description = "Im Süden findet Ihr die Insel des Blutfluchs. Oben auf der Insel befindet sich ein Schrein, der der von den Naga geliebten Königin, Azshara, gewidmet wurde. Zerstört die Statue - verbrennt das Abbild! Dies wird mit Sicherheit den Zorn von Anführer Atoph des Blutfluchs erwecken.\n\nTötet Atoph und kehrt zu mir zurück!", sourceObjective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr die Statue der Königin Azshara zerstört und Atoph des Blutfluchs tötet.", progress = "Ihr müsst Atoph hervorlocken!", completion = "Ihr habt es geschafft! Hunderte von Seelen sind Euch für alles, was Ihr getan habt, dankbar.\n\nGestattet mir, Euch etwas zu überreichen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9684] = { id = 9684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beherrschung des Lichts", description = "Nehmt dieses Gefäß, {name}. Durch die Erweckung seiner Verzauberung werdet Ihr in der Lage sein, die letzten Überreste des Lichts, das diese Magister umgibt, für Euch zu nutzen. Sie pflegten einst den gefangenen Naaru und tragen noch immer einen Teil von dessen Energie in sich.\n\nSorgt Euch nicht um die Magister, {name}. Ich kümmere mich um ihr Wohlergehen. Lord Solanar hat mir versichert, dass Lady Liadrin selbst jetzt auf der Suche nach einer neuen Energiequelle ist.", sourceObjective = "Wendet das schimmernde Gefäß auf die Magister der Blutelfen an, um es zu füllen und kehrt anschließend zu Ritterfürst Heldenblut in Silbermond zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9685] = { id = 9685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung der Toten", description = "Während Ihr das Gefäß vorbereitet habt, habe ich eine Gruppe von Initianden entsandt, um Sangrias Stillstreich zu bergen. Ihr findet ihn, zusammen mit einem Ordensdiener, auf der obersten Etage des Gasthauses von Silbermond. Begebt Euch ohne Verzögerung dorthin und entfesselt die magischen Kräfte des Gefäßes, um ihn ins Leben zurückzuholen.\n\nDie Zeit drängt, {name}. Sollte er zu lange tot sein, können ihn nicht einmal mehr die Mächte des Lichts retten. Kehrt nach Stillstreichs Wiederbelebung zu mir zurück.", sourceObjective = "Bringt das gefüllte schimmernde Gefäß zum Gasthaus von Silbermond und verwendet seine Magie, um Sangrias Stillstreich wiederzubeleben.", completion = "Willkommen zurück, Initiand. Jetzt, da Ihr die volle Wahrheit über die Quelle unserer Macht kennt und nachdem Ihr Euer Geschick bei dessen Anwendung unter Beweis gestellt habt, gewähre ich Euch die Fähigkeit, die Toten auf dem Schlachtfeld wiederzubeleben.\n\nWenn Ihr dem Orden gegenüber treu bleibt und Ihr die Ausbildung weiter so beflissen fortsetzt, werdet Ihr nur noch mächtiger werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9686] = { id = 9686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Prüfung", description = "Ihr steht kurz davor, innerhalb des Ordens den Status eines Adepten zu erhalten, {name}. Zunächst werdet Ihr jedoch beweisen müssen, dass Ihr für eine solche Ehre schon bereit seid, indem Ihr eine weitere Prüfung absolviert.\n\nDie zweite Prüfung unterscheidet sich vor allem dadurch von der Ersten, dass Euch keine unliebsamen Überraschungen mehr erwarten. Die vor Euch liegende Aufgabe ist einfach; Ihr müsst Euch gegen die vier besten Champions der Blutritter im Kampf beweisen.\n\nSobald Ihr die Herausforderung annehmt, erscheint in der Mitte des Pavillons ein Kristall. Berührt ihn, um mit Eurer Prüfung zu beginnen und entfernt Euch niemals zu weit von dem Gebäude.\n\nSeid Ihr bereit?", sourceObjective = "Besteht die zweite Prüfung und besiegt Champion Rachblut, Champion Lichtrend, Champion Schnellklinge und Champion Sonnensturm im Pavillon in der Nähe von Meister Kelerun Blutpein.", progress = "Ein Blutritter würde eher sterben, als sich seinem Feind zu unterwerfen. Vergesst das nie, {name}.", completion = "Hervorragend, {name}! Ihr habt Eure Fähigkeiten unter Beweis gestellt und seid würdig, in den Stand eines Adepten, eines vollwertigen Mitglieds der Blutritter, erhoben zu werden. Bevor die tatsächliche Zeremonie stattfinden kann, warten allerdings noch einige Aufgaben auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9687] = { id = 9687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung der Heiligkeit", description = "Es ist noch nicht lange her, da kamen die einst so friedlichen Eulkin der Umgebung an die Ufer dieser Insel. Sie kamen einer nach dem anderen, um die Knochen der gefallenen Drachen zu stehlen. Ich weiß nicht, was die Kreaturen in diese Verzweiflung getrieben hat oder warum sie die Knochen der Dahingeschiedenen wollen. Allerdings ruhen die Geister der Brut seit dieser Schändung nicht mehr.\n\nGen Westen, über die Purpurbrandung hinweg, liegt der Rachfederkamm. Reist zu den Siedlungen der Eulkin und nehmt die gestohlenen Drachenknochen wieder an Euch.", sourceObjective = "Prinz Toreth auf der Insel Drachenfels möchte, dass Ihr 8 Drachenknochen wiedererlangt.", progress = "Die Kriege der Drachen sind seit langem vorüber. Was noch bleibt, sind die Knochen und die aufgewühlten Überbleibsel von Yseras Brut.", completion = "Ein Ritual? Die Eulkin haben seit tausenden von Jahren mit dem Land in Einklang gelebt. Derartiges ist nicht normal!\n\nWie bedauerlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[9688] = { id = 9688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Traum", description = "Die Welpen, die Ihr auf dieser Insel seht, sind die ruhelosen Geister des grünen Drachenschwarms. Sie sind wie ich an das Land gebunden, außerstande ihre letzte Ruhestätte im Traum zu erreichen.\n\nDie Wiederbeschaffung der Knochen von den Gefallenen hat sie zwar etwas beruhigt, aber Ihr müsst noch mehr unternehmen.\n\nZerstört ihre astralen Erscheinungen. Ich kann diesen Ort erst verlassen, wenn es geschehen ist. Sie müssen erlöst werden!", sourceObjective = "Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr 5 Viridianwelpen und 5 Viridianbrutlinge tötet.", completion = "Wie verwerflich Eure Aufgabe auch war, es musste einfach getan werden. Jetzt müsst Ihr in das Angesicht des Bösen sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9689] = { id = 9689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messerrachen", description = "Während den Angriffen wurden viele des schwarzen Drachenschwarms getötet. Einer von ihnen, ein Offizier von Todesschwinge selbst, sucht noch immer diesen Ort heim. Blickt Ihr in den Himmel, so könnt Ihr sein spektrales Antlitz durch die Lüfte kreisen sehen. Sein Hass ist so groß, dass er sogar den Tod übersteht.\n\nNehmt die Knochen, die Ihr bereits für mich eingesammelt habt, zu der Spitze des Berges dieser Insel und platziert sie im ewig brennenden Scheiterhaufen. Dieses Signal sollte Messerrachen herabschweben lassen. Sobald er da ist, tötet sein untotes Abbild.", sourceObjective = "Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr Messerrachen tötet.", completion = "Wie lange war es noch? Tausend Jahre? Zehntausend Jahre vielleicht? Ihr habt mir und der Erinnerung meiner Leute einen großen Dienst erwiesen, {name}. Bitte, nehmt diesen mächtigen Gegenstand als Zeichen der Anerkennung von Loreth'Aran an - für Eure ehrvollen Taten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9690] = { id = 9690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Prüfung", description = "Initiand {name}, Ihr habt hart an Euch gearbeitet, um die Macht des Lichts zu beherrschen, über die wir Dank unserer Magister verfügen. Ihr wisst nun von der Quelle unserer Fähigkeiten und alles über die Pflichten eines Blutritters.\n\nDer Zeitpunkt ist nahe, da Ihr Euch der zweiten Prüfung unterziehen werdet und Ihr um den Rang eines Adepten der Blutritter kämpfen müsst. Die Prüfung findet unter der Aufsicht von Meister Kelerun Blutpein im nördlichen Teil von Silbermond statt. Reist durch die Ruinen von Silbermond nach Norden und nehmt den östlichen Pfad, der kurz vor der Brücke abzweigt, die zur Insel der Sonnenwanderer führt.", sourceObjective = "Meldet Euch bei Meister Kelerun Blutpein.", completion = "Sobald Ihr bereit seid, werde ich Euch mehr über die bevorstehende Prüfung erzählen. Trefft Eure Vorbereitungen und wenn Ihr beginnen möchtet, sprecht erneut mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[9691] = { id = 9691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Silbermond", description = "Kehrt umgehend nach Silbermond zurück und berichtet Ritterfürst Heldenblut. Eure Ankunft sollte ihm alles Notwendige über den Ausgang der Prüfung mitteilen.\n\nEr wird Euch Eure weiteren Aufgaben auf dem Weg zum Adepten erläutern. Ihr könnt stolz auf Euch sein, {name}. Viele versuchen sich an dieser Prüfung, doch nur die Wenigsten kehren zurück, um von ihrem Erfolg zu berichten.", sourceObjective = "Kehrt zu Ritterfürst Heldenblut nach Silbermond zurück.", completion = "Ich habe immer daran geglaubt, dass Ihr diese Prüfung bestehen würdet, {name}. Eure verbleibenden Pflichten sind größtenteils zeremonieller Natur und doch sind sie nicht weniger gefährlich, als der Versuch, mit bloßen Fäusten gegen einen unserer Champions zu bestehen. Hört genau hin, was Ihr als Nächstes tun müsst, um Euren neuen Rang zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9692] = { id = 9692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Adepten", description = "Bevor ein frischgebackener Adept in die Ränge der Blutritter aufgenommen wird, muss er die Materialien beschaffen, die zum Schmieden der besonderen Waffe des Ordens benötigt werden: dem blutgehärteten Ranseur.\n\nIhr müsst Euch außerdem das Recht verdienen, das Insigne unseres Ordens zu tragen. Bei der Gründung des Ordens wurde eine begrenzte Zahl dieser Insignien geschmiedet und verteilt, jeder Adept erbt sein Insigne von einem Veteran. Euer Insigne erhaltet Ihr von einem gefallenen Ritter, der einen Angriff auf die Todesfestung anführte.\n\nIch habe Notizen vorbereitet, die Euch helfen sollen.", sourceObjective = "Bringt Ritterfürst Heldenblut in Silbermond einen verderbten Koredelstein, eine Kiste mit blutgeschmiedeten Blöcken, etwas Blut des Hasserfüllten und ein Insigne der Blutritter.", progress = "Habt Ihr getan, was Euch aufgetragen wurde?", completion = "Sehr gut, {name}. Es ist alles da. Nun muss nur noch die Waffe geschmiedet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9693] = { id = 9693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Argus für mich bedeutet", description = "Was bedeutet Argus für Euch, {name}? Ihr, wie viele andere Draenei auch, kennt oder erinnert Euch wahrscheinlich nicht an unseren Heimatplaneten. Dort trennten wir uns von den Man'ari: unseren verdorbenen dämonischen Abbildern, die von Sargeras 'bedacht' wurden. Sie selbst nennen sich die Eredar.\n\nEredar... dieses Wort hatte einst eine Bedeutung.\n\n<Admetius scheint das Wort förmlich zu schmecken.>\n\nWiderlich.\n\nLasst uns nicht noch mehr Zeit verschwenden. Sucht nach Verteidiger Boros, damit Ihr mit Eurer Ausbildung beginnen könnt.", sourceObjective = "Exarch Admetius bei der Blutwacht wies Euch an, mit Verteidiger Boros zu sprechen.", completion = "Ah, {name}... ich habe bereits von Euch gehört. Ihr seid also derjenige, der den Korsallauf in unter 15 Minuten gemacht hat. Ts, wahrscheinlich nicht.\n\nSeid Ihr bereit, etwas Blut im Namen des Lichts zu vergießen? Für Velen? Für Argus?\n\n\n\nGut, gut, ich halte mich jetzt besser zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9694] = { id = 9694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutwacht", description = "Wie Ihr wisst, ist die Blutwacht einer von zwei Vorposten, die der Hand von Argus als Operationsbasen dienen. Ihr wart bereits bei der anderen Basis, der Azurwacht; die Dinge laufen auf der Blutmythosinsel etwas anders. Als wir hier zu Beginn ankamen, war das Land genauso wunderschön und unberührt wie auf der Azurmythosinsel. Wir nannten es sogar Silberbrise, doch nun breitet sich die Seuche über das Land aus. Was noch schlimmer ist, die Blutelfen, die wir auf der Exodar bekämpften, haben den Absturz überlebt. Somit kommen wir zu Eurem ersten Auftrag: Reist nach Nordwesten zum Messerwinkel und vernichtet alle Blutelfen, die Euch über den Weg laufen.", sourceObjective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr 10 Spione der Sonnenfalken tötet.", completion = "Ihr seid zurück - in einem Stück!\n\nIch habe gute Neuigkeiten, {name}. Wir haben neue Informationen zum wahrscheinlichen Aufenthaltsort weiterer Überlebender erhalten. Eine neue Absturzstelle wurde entdeckt! Sobald ich mich eingehender damit befasst habe, werde ich mich an Euch wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9695] = { id = 9695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anweisung des Sonnenkönigs", description = "Dieses Dokument sieht wichtig aus. Leider wurde es in Thalassisch verfasst; eine Sprache, derer Ihr nicht mächtig seid.\n\nVielleicht weiß Verteidiger Boros, wie man weiter vorgehen könnte.", sourceObjective = "Bringt die Anweisung des Sonnenkönigs zu Verteidiger Boros bei der Blutwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9696] = { id = 9696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzungen...", description = "Unsere hochrangigste Vernehmungsbeauftragte Elysia spricht fließend Thalassisch. Bringt ihr dieses Dokument, mal sehen, was sie dazu zu sagen hat.", sourceObjective = "Bringt das Schreiben der Sonnenfalken zur Vernehmungsbeauftragten Elysia bei der Blutwacht.", progress = "Ich habe hier etwas viel zu tun, Agent {name}. Ich hoffe Euer Anliegen ist wichtig.", completion = "<Elysia liest das Dokument.>\n\nWenn wirklich stimmt, was hier steht, dann haben die Blutelfen ein Portal zur Scherbenwelt geöffnet! Das würde auch ihre schier endlose Zahl erklären...", sourceObjectiveStatus = "unverified-source-field" }
quests[9697] = { id = 9697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüterin Leesa'oh", description = "Es müssen wichtige Forschungen bezüglich der Ökologie der hiesigen Lebewesen betrieben werden, besonders bei den Sporlingen und den Sumpflords der Marschen. Und vertraut mir, wenn Ihr Euch einmal mit diesem Thema befasst habt, werdet Ihr die Arbeit faszinierend finden.\n\nSucht Behüterin Leesa'oh im Wachposten des Cenarius im westlichen Teil der südlichen Marschen. Folgt dem Pfad nach Westen, dann werdet Ihr sie sicher finden. Sie ist manchmal etwas... übereifrig..., aber lasst Euch davon nicht abschrecken.\n\nOh, und hütet Euch vor ihrer Katze.", sourceObjective = "Sprecht mit Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen.", completion = "Oh, gut... endlich Unterstützung! Es gibt einfach so viel zu tun, und ich muss hierbleiben, um alles zu organisieren.\n\nIch hoffe Ihr seid bereit, Euch die Hände schmutzig zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9698] = { id = 9698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz beim Propheten", description = "Ihr müsst das übersetzte Dokument Velen persönlich überbringen, {name}. Ich vertraue diesem verstörten Boten nicht.\n\nErklärt dem Propheten, dass die Blutelfen Verstärkung aus der Scherbenwelt erhalten und dass sie einen Spion unter den Draenei bei der Exodar haben. Velen hält sich in der Halle des Lichts in der Exodar auf.\n\nBeeilt Euch!", sourceObjective = "Bringt das übersetzte Schreiben der Sonnenfalken zum Propheten Velen bei der Exodar.", progress = "<Velen lächelt.>\n\nSeid gegrüßt, {name}. Ich habe Euch erwartet.", completion = "<Velen beginnt das Dokument zu lesen.>\n\nInteressant... dies erklärt in der Tat einiges.", sourceObjectiveStatus = "unverified-source-field" }
quests[9699] = { id = 9699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist wahr?", description = "Ich danke Euch für die rasche Zustellung, {name}. Ihr erweist Euch schließlich als einer der besseren Agenten der Hand.\n\nWenn wir bloß wüssten, wem sie auf der Blutmythosinsel Bericht erstattet haben und noch wichtiger, wo dieses Sonnenportal ist... Sie scheinen es streng zu bewachen - wo immer es auch sein mag.\n\nWärt Ihr an einer Erkundungsmission interessiert?\n\nWenn ja, dann bringt diese Anordnungen zu Verteidiger Boros. Er wird Euch Euren nächsten Auftrag erteilen.", sourceObjective = "Bringt Velens Anordnungen zu Verteidiger Boros bei der Blutwacht.", progress = "Ja?", completion = "Es ist ein guter Plan, aber auch ein gefährlicher. Ich bin mir jedoch sicher, dass alles gut verlaufen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[9700] = { id = 9700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht ins Dunkel bringen", description = "Velen erklärt, dass falls die Blutelfen Verbindungen zwischen der Insel und der Scherbenwelt hergestellt haben, Überreste oder Anomalien rund um die geöffneten Portale zurückgelassen wurden. Ihr müsst die Insel nach Gebieten absuchen, in denen diese Anomalien vorkommen.\n\nSeid gewarnt, {name}, manche dieser Anomalien sind Kreaturen aus der Leere selbst. Solltet Ihr auf Anomalien der Leere treffen, tötet sie! Erstattet mir Bericht, sobald Ihr neue Informationen ausfindig gemacht habt. Beginnt mit Eurer Suche im Norden, nahe der Warpgondel.", sourceObjective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr die Lage des Sonnenportals ausfindig macht und 5 Anomalien der Leere tötet.", completion = "Wie viele sagtet Ihr doch gleich, habt Ihr bei der Warpgondel gesichtet? Wie oft haben sie nur dieses Sonnenportal geöffnet? Das sind sehr schlechte Neuigkeiten...\n\nTja, Ihr habt Euch nun alles von mir angeeignet, was ich Euch lehren kann, {name}. Kuros wird nach Euch rufen lassen, wenn es an der Zeit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9701] = { id = 9701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporlinge beobachten", description = "Wir müssen alles über die Sporlinge von Sporeggar und ihre Beziehung zu den anderen Lebewesen in der Umgebung in Erfahrung bringen. Eine Möglichkeit dazu ist die, die ich anwende: passives Beobachten und ihr Verhalten notieren.\n\nIch möchte, dass Ihr für mich nach Westen in das Pilzgeflecht geht. Untersucht die gesamte Gegend dort und berichtet mir dann davon.", sourceObjective = "Untersucht das Pilzgeflecht in den Zangarmarschen und berichtet danach Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen von Euren Beobachtungen.", progress = "Schon wieder zurück? Eure Beobachtungen der Sporlinge von Sporeggar sind unverzichtbar für meine Forschungen. Ich hoffe, Ihr seid nicht der Typ, der Dinge gerne überstürzt. Zeigt etwas Geduld und stellt sicher, dass Ihr die gesamte Gegend des Pilzgeflechts untersucht habt, bevor Ihr zu mir zurückkommt.", completion = "Was?! Die Sumpflords des Quaggkamms ESSEN die Sporenkapseln die Sporlinge? Das ist nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[9702] = { id = 9702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Fressgier", description = "Ich habe mich schon gefragt, warum die Sumpflords die Straße überqueren, um in das Pilzgeflecht zu gelangen - sie müssen aus irgendeinem Grund am verhungern sein. Das darf nicht sein!\n\nIch meine, normalerweise würde ich mich nicht einmischen, aber wenn sie weiterhin alle Kapseln essen, werden sie die Sporlinge ausrotten!\n\nHier ist mein Plan: Ich bleibe hier und Ihr geht zum Quaggkamm im Osten und seht Euch nach nahrungstechnischen Gründen um, warum sie die Sporlinge überfallen.", sourceObjective = "Sammelt 10 Stück liegengelassene Nahrung und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", progress = "Stellt sicher, dass Ihr alle Beweise sorgfältig zusammentragt, {class}! Wir fügen hier die Teile eines riesigen Puzzles zusammen. Ein Fehler von Euch könnte zu falschen Schlussfolgerungen führen.\n\nWo stünden wir dann mit unserem Verständnis für die Zangarmarschen?", completion = "Das habt Ihr gefunden? Das ist komisch. Diese vertrockneten Pilzüberreste sind ungewöhnlich und kommen mir irgendwie bekannt vor.\n\nIch muss kurz darüber nachdenken. Geht nicht weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[9703] = { id = 9703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kryokern", description = "Wir haben noch andere, die nach Spuren suchen, die zu den Sonnenportalen führen, {name}. Ihr müsst Euch jetzt auf Euren bevorstehenden Einsatz konzentrieren.\n\nBoros erhielt Berichte über eine neue Absturzstelle. Wir haben herausgefunden, dass es sich bei dieser Absturzstelle eigentlich um den Kryokern der Exodar handelt. Eine Transportkammer, in der genau solche Kapseln untergebracht sind wie die, aus denen wir Draenei im Am'mental gekrochen sind.\n\nIn diesem Bereich werden auch Heilvorräte aufbewahrt. Geht zum Kryokern genau westlich der Blutwacht. Sucht nach Vorräten und nach Überlebenden.", sourceObjective = "Verteidiger Kuros bei der Blutwacht möchte, dass Ihr 12 Kisten mit Heilvorräten sichert.", progress = "Waren die Informationen korrekt?", completion = "Nur Blutelfen? Keine Überlebenden? Das ist beunruhigend. Ich brauche etwas Zeit zum Nachdenken, {name}. Vielleicht haben Aesom oder Boros einen Auftrag für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9704] = { id = 9704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Getriebenen getötet", description = "Es ist ein hartes Stück Arbeit, ein Kundschafter zwischen der Insel der Sonnenwanderer und dem Falkenplatz zu sein. Knappe Zeitvorgaben, lange Arbeitszeiten und noch schlimmer... die Getriebenen!\n\nDie Straße im Süden führt durch die Ruinen von Silbermond... ein Ort, an dem es nur so von Getriebenen wimmelt, die darauf warten, Euch für ein paar Manakristalle töten zu können. Ich glaube dieses Schicksal hat unsere letzte Kundschafterin ereilt. Wir hatten sie mit einem von Eronas Päckchen entsandt.\n\nWie ich sehe, brennt Ihr bereits darauf, Euch beweisen zu können. Reist zum Dämmerweg und sucht nach Spuren unserer Kundschafterin.", sourceObjective = "Geht nach Süden zu den Ruinen von Silbermond und haltet nach der getöteten Kundschafterin beim Dämmerweg Ausschau.", completion = "Die Habseligkeiten der Kundschafterin wurden mit Ausnahme eines Pakets allesamt entwendet. Es scheint der Beschreibung zu entsprechen, die Euch Alarion von Eronas Päckchen gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9705] = { id = 9705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergung des Päckchens", description = "Ihr nehmt das Päckchen und stellt noch einmal sicher, dass es wirklich von Magistrix Erona stammt. Alarion würde es sicherlich gerne entgegennehmen.", sourceObjective = "Kehrt mit Eronas Päckchen zu Kundschafterin Alarion zurück.", progress = "Was habt Ihr gefunden, {name}?", completion = "Beim Sonnenbrunnen! Es ist der dritte Kundschafter, den wir diesen Monat verloren haben.\n\nIch weiß Euren Mut zu schätzen, den Ihr bei Eurer Reise zum Dämmerweg bewiesen habt. Die Wachen müssen diese verdammten Getriebenen besser im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9706] = { id = 9706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaens Tagebuch - Das Schicksal von Verteidiger Saruan", description = "Eure Hände zittern beim Aufheben des Buchs. Kuros muss von dieser Tragödie erfahren. Bringt ihm das Tagebuch.", sourceObjective = "Bringt Galaens Tagebuch zu Verteidiger Kuros bei der Blutwacht.", progress = "Was habt Ihr da, {name}? Ist das ein Tagebuch?", completion = "<Kuros erbleicht beim Lesen des Tagebuchs und Tränen strömen seine Wangen herab.>\n\nSaruan war mein Meister... mein Lehrer... mein Mentor... Ich nahm seinen Platz im Dreigestirn erst vor kurzem ein - nachdem wir die Suche nach ihm aufgegeben hatten.\n\n<Kuros' Gesichtsausdruck schlägt in Zorn über.>\n\nMatis...", sourceObjectiveStatus = "unverified-source-field" }
quests[9707] = { id = 9707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden der Waffe", description = "Wieder habt Ihr Euch als würdig erwiesen, ein Mitglied des Ordens zu sein. Mit großer Freude verleihe ich Euch den Rang des Adepten, {name}. Prinz Kael'thas selbst wäre stolz auf Euch.\n\nEs ist eine Ehre für uns alle, an Eurer Seite auf dem Schlachtfeld zu kämpfen. Verhaltet Euch weiterhin vorbildlich, zeigt keine Gnade oder Schwäche, verteidigt unermüdlich Euer Volk und Eure Brüder und verfeinert Eure Beherrschung des Lichts.\n\nNun holt Euch die Waffe, die Eurem neuen Rang angemessen ist.", sourceObjective = "Bringt die Kiste mit Rohmaterialien zu Bemarrin in Silbermond.", progress = "Ich gratuliere Euch, {name}. Den Rang des Adepten zu erreichen ist keine leichte Sache, glaubt mir. Ich habe viele Leute dieses Gebäude betreten sehen, und nur wenige halten lange genug durch, um mit diesen Rohmaterialien zu mir zu kommen.", completion = "Sieht aus, als hättet Ihr alles, was ich brauche. Ans Werk!", sourceObjectiveStatus = "unverified-source-field" }
quests[9708] = { id = 9708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekannter Pilz", description = "Ja, das ist es! Ich wusste doch, dass ich diesen Pilzstamm schon woanders in den Marschen gesehen habe!\n\nIm Norden gibt es einen Ort, der Prügelsumpf genannt wird. Komischer Name für einen Sumpf, wenn Ihr mich fragt, aber ich bin noch nie dort gewesen. Ich brauche Proben von diesen Pilzen um meine Theorie zu unterstützen.\n\nAber seid vorsichtig, {class}. Ich habe gehört, dass die Oger in dieser Gegend einmarschiert sind. Ihr müsst also die Proben von ihnen besorgen. Könnte das der Grund sein, warum die Sumpflords dort nicht mehr ihre Nahrung suchen?", sourceObjective = "Sammelt 15 Pilzproben und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", progress = "Habt Ihr die Proben schon?", completion = "Die Proben stimmen definitiv überein. Und die Anwesenheit der Oger und was sie dort tun erklärt alles. Jetzt verstehe ich, warum der Ort Prügelsumpf genannt wird.\n\nWir müssen etwas an dieser Situation ändern, aber was? Wir können nicht einfach alle Oger auslöschen, sie haben genauso viel Recht hier zu leben, wie alle anderen Lebewesen in den Marschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9709] = { id = 9709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pilze zurückstehlen", description = "{class}, ich habe eine Idee. Ich möchte, dass Ihr Euch wieder nach Norden aufmacht, aber dieses Mal in das Herz des Ogergebiets!\n\nNordwestlich des Prügelsumpfs gibt es einen Ort, der Festung der Ango'rosh genannt wird. Er befindet sich auf einer Insel jenseits einer großen Pilzbrücke. Dort lagern sie bestimmt die geernteten Pilze. Ihr könnt sie sicher überall finden, wahrscheinlich haben die Oger selbst sie sogar in den Taschen!\n\nBringt mir genügend davon, und ich werde versuchen, die Sumpflords mit einer neuen Nahrungsquelle zu versorgen.", sourceObjective = "Sammelt 10 Kisten Pilze und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", progress = "Habt Ihr schon alle Pilze, um einen neuen Garten für die Sumpflords anzulegen?", completion = "Sie sind perfekt! Oh danke, {class}!\n\nIhr wart so darauf bedacht, das natürliche Gefüge nicht aus dem Gleichgewicht zu bringen, und wir haben in so kurzer Zeit so viele Informationen sammeln können!\n\nJetzt wollen wir mal schauen, ob unser kleiner Plan, eine neue Nahrungsquelle für die Sumpflords zu schaffen, funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[9710] = { id = 9710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der blutgehärtete Ranseur", description = "Es ist alles vorbereitet, {name}. Bald werdet Ihr eine Waffe haben, die Eurem neuen Status angemessen ist.", sourceObjective = "Wartet, während Bemarrin Eure Waffe schmiedet.", completion = "Hier ist die Waffe, {name}. Nutzt sie im Dienst für Silbermond und Euren Orden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9711] = { id = 9711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matis der Grausame", description = "Matis wird Gerechtigkeit widerfahren, {name}. Ich möchte, dass Ihr derjenige seid, der ihn findet und ihn zum Dreigestirn zurückbringt.\n\nDurchkämmt die Insel nach diesem Bastard. Solltet Ihr ihn finden, verwendet diese Leuchtpistole. Sobald mein Suchtrupp das Signal sieht, wird man herbeieilen und Euch bei der Gefangennahme von Matis helfen. Kommt anschließend zu mir zurück.", sourceObjective = "Verteidiger Kuros bei der Blutwacht möchte, dass Ihr Matis den Grausamen gefangen nehmt.", completion = "Das Dreigestirn hat beschlossen, Matis sofort zu verurteilen. Ihr habt heute einen Erzverbrecher der Gerechtigkeit überführt, junger {race}.\n\nIhr habt für zwei von dreien außerordentliche Arbeit geleistet, lediglich Aesom fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9712] = { id = 9712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das thalassische Schlachtross", description = "Ihr habt Euch im Dienste des Ordens ausgezeichnet, {name}. Die Euch durch Magister Astalor und seiner Brüder gewährten Fähigkeiten, die Energien des Lichts zu beherrschen und Eurem Willen nach einzusetzen, und Euer offensichtliches Talent darin, machen Euch alle Ehre. Ihr wurdet für würdig befunden, Euer Wissen noch zu erweitern.\n\nMit dem Licht unter Eurer Kontrolle seid Ihr in der Lage, ein furchterregendes Schlachtross herbeizurufen; ein treues Reittier an Eurer Seite.\n\nDient auch weiterhin so voller Eifer und Ehre, {name}, und Ihr werdet belohnt werden.Ihr erlernt:", sourceObjective = "Sprecht mit Ritterfürst Heldenblut, um zu erfahren, wie Ihr Euer thalassisches Schlachtross beschwören könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9714] = { id = 9714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein weiteres Gebüsch!", progress = "Wir können immer noch mehr Bluthibiskus von den Schlurfern, Sumpfriesen und Tiefenfledermäusen im Echsenkessel gebrauchen. Bringt sie mir in Bündeln zu je fünf, und ich werde Euch sehr dankbar sein.", completion = "Das ist schon mal sehr gut, aber wir können immer noch mehr davon gebrauchen. Vielleicht geht Ihr ja bald mal wieder in den Tiefensumpf?" }
quests[9715] = { id = 9715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein Gebüsch!", description = "Wir müssen unsere Vorräte an Bluthibiskus aufstocken, die wir für viele Zwecke brauchen. Früher gab es hier dicke Büsche davon, aber seitdem der Wasserspiegel der Marschen gesunken ist, findet man ihn nur noch im Tiefensumpf und im Echsenkessel, unter dem Schlangensee.\n\nMan sagt, er sei eine Delikatesse für die Schlurfer, Sumpfriesen und die Tiefenfledermaus. Wenn Ihr uns also helfen wollt, müsst Ihr die Blumen von Ihnen besorgen.", sourceObjective = "Sammelt 5 Stück Bluthibiskus und bringt sie zu Gzhun'tt in Sporeggar in den Zangarmarschen.", progress = "Habt Ihr den Hibiskus, um den ich Euch gebeten habe?", completion = "Das ist schon mal sehr gut, aber wir können immer noch mehr davon gebrauchen. Vielleicht geht Ihr ja bald mal wieder in den Tiefensumpf?", sourceObjectiveStatus = "unverified-source-field" }
quests[9716] = { id = 9716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anomalie am Umbrafennsee", description = "Wir kamen in die Scherbenwelt mit der Erwartung, hier kleine Ansammlungen von Leben zu finden. Doch was wir hier in den Zangarmarschen entdeckt haben, ist eine üppige Landschaft mit einem gedeihenden Ökosystem.\n\nUnsere ursprüngliche Einschätzung der Gegend war dennoch trügerisch. Die Wasserstände der Seen und Marschen sind seit unseren ersten Messungen stetig gesunken.\n\nDies könnte verheerende Auswirkungen auf die Flora und Fauna der Gegend haben. Geht zum Umbrafennsee südwestlich von hier und seht Euch nach möglichen Gründen für das Sinken des Wasserspiegels um.", sourceObjective = "Untersucht den Grund für die sinkenden Wasserspiegel am Umbrafennsee. Kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", completion = "Die Naga stecken dahinter! Aber warum? Euren Schilderungen zufolge sind die Dampfpumpen für das Sinken der Wasserspiegel in den Marschen verantwortlich.\n\nEgal - dies erklärt Ihre offensichtliche Feindlichkeit uns gegenüber. Lasst uns keine Zeit verschwenden, Ihr müsst eine weitere Aufgabe für uns erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9717] = { id = 9717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Los geht's!", description = "Auch wenn wir ein friedliebendes Volk sind, befinden wir uns im Krieg mit den Fungusgiganten, ob uns das gefällt oder nicht. Und es gibt ein Sprichwort bei den Sporlingen, das besagt, dass im Krieg und im Pilz alles erlaubt ist!\n\nEiner der Anführer der Fungusgiganten, Hungarfenn, pflegt seit Jahrtausenden mit Hingabe eine sehr besondere Pflanze, bekannt als die Tiefenspore. Er würde daran zerbrechen, wenn dieser Pflanze etwas zustoßen würde.\n\nReist zum Tiefensumpf im Echsenkessel und stehlt einen Dorn von ihr. Vertraut mir, er wird es bemerken.", sourceObjective = "Besorgt einen Tiefensporenfarn und bringt ihn zu T'shu in Sporeggar in den Zangarmarschen.", progress = "Der Tiefensumpf ist ein sehr gefährlicher Ort. Wenn Ihr Euch scheut, dorthin zu gehen, würde ich Euch nicht als Feigling bezeichnen. Ich wäre allerdings auch alles andere als zufrieden, wenn Ihr mir nicht das brächtet, worum ich gebeten habe.", completion = "<Der Sporling macht ein Geräusch, das fern an ein prustendes Lachen erinnert.>\n\nPerfekt! Die Moral der Fungusgiganten wird sicher ein Rekordtief erreichen, wenn sie sehen, was Ihr getan habt.\n\nEntweder das oder sie werden so erzürnt sein, dass sie uns bald wieder angreifen.\n\n<T'shu zuckt mit den Schultern.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9718] = { id = 9718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flug der Krähe", description = "Wir müssen genau herausfinden, wie weit reichend die Aktivität der Naga wirklich ist und entsprechend reagieren.\n\nJedes Wasservorkommen in den Zangarmarschen zu untersuchen wäre ein sehr zeitaufwändiges Unterfangen. Wenn Ihr mir gestattet, werde ich meine Magie benutzen, um Euch in eine Gestalt zu verwandeln, die Euch das Erkunden der Marschen leichter machen wird.\n\nHaltet dieses Amulett über den Balkon in meiner Nähe, wenn Ihr bereit seid. Ich werde Euch zurück in die Sicherheit führen, wenn wir fertig sind.", sourceObjective = "Ysiel Windsänger möchte, dass Ihr das Sturmkrähenamulett benutzt, um die größeren Seen in den Zangarmarschen zu erkunden.", progress = "Seid gegrüßt, {name}.", completion = "Es ist so, wie ich dachte. Die Naga haben Pumpstationen an allen größeren Seen in den Zangarmarschen errichtet.\n\nWenn die Marschen weiter existieren sollen, müssen sie aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9719] = { id = 9719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Mutter", description = "Geschichtlich gesehen waren die Marschenläufer die größte Gefahr für mein Volk. Jetzt, da wir mit den Problemen mit den Fungusgiganten zu kämpfen haben, können wir uns keinen weiteren Angriff unserer alten Feinde erlauben.\n\nIhr habt Euch als fähig erwiesen, {class}. Meint Ihr, Ihr könntet zum Tiefensumpf im Echsenkessel reisen und die große Mutter der Marschenläufer, die als Schattenmutter bekannt ist, auslöschen?!\n\nBringt mir ihr Gehirn als Beweis.", sourceObjective = "Bringt das Gehirn der Schattenmutter zu Khn'nix in Sporeggar in den Zangarmarschen.", progress = "Ihr seid zurück. Heißt das die Schattenmutter ist nicht mehr?", completion = "Die Schattenmutter ist tot! Normalerweise schwelge ich ja nicht in solchen Gemetzeln, aber der Schmerz, den die große Mutter und ihre Brut über Jahrhunderte über mein Volk gebracht haben, ist unaussprechlich.\n\nEs ist schade, dass nun einer ihrer Nachkömmlinge sich verwandeln wird, um ihren Platz einzunehmen, aber das wird Zeit benötigen. So haben wir eine kleine Atempause, und müssen uns eine Zeitlang nicht vor den Marschenläufern fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9720] = { id = 9720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht muss erhalten bleiben", description = "Ich kann nicht verstehen, warum die Naga ihren eigenen Lebensraum entwässern wollen. Ich weiß aber sicher, dass wir sie aufhalten müssen.\n\nDiese Samen tragen die Wut der Erde in sich. Bringt sie zu den Dampfpumpen, die von den Naga betrieben werden, und benutzt sie bei den Steuerungen.\n\nDie Ranken, die aus den Samen wachsen, werden so dick wie Euer Arm und so stark wie Eisen sein, {name}. Stellt das Gleichgewicht wieder her, das die Naga zerstört haben.", sourceObjective = "Ysiel Windsänger möchte, dass Ihr die Eisenrankensamenkörner benutzt, um die Dampfpumpensteuerungen am Schlangensee, Umbrafennsee, Sumpflichtsee und der Lagune zu zerstören. Kehrt danach mit den übrigen Samen zu ihr in die Zuflucht des Cenarius in den Zangarmarschen zurück.", progress = "Schon fertig, {class}?", completion = "Es ist also vollbracht. Die Marschen sind vorerst gerettet.\n\nGlaubt aber nicht, dass wir zum letzten Mal von den Naga gehört haben. Wir müssen unseren Feind im Auge behalten, während wir unsere Mission in der Scherbenwelt fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9721] = { id = 9721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufforderung von Lord Solanar", description = "Eure Aufopferung für den Orden und Euer rascher Aufstieg innerhalb seiner Ränge sind nicht unbeachtet geblieben. Tatsächlich erbittet Lord Solanar Blutzorn, Lady Liadrins rechte Hand und verdienter Held, Eure Gegenwart.\n\nDas ist eine seltene Ehre, {name}. Normalerweise überlässt Lord Solanar mir die Verwaltung des Ordens und das damit verbundene Tagesgeschäft, doch scheint er ein besonderes Interesse an Euch zu haben. Wartet nicht zu lange, {name}.", sourceObjective = "Sprecht mit Lord Solanar Blutzorn in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9722] = { id = 9722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Meisters", description = "Innerhalb meines Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem thalassischen Schlachtross zu erkennen.\n\nJeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen.\n\nIch habe beschlossen, Euch als Fürsprecher zur Seite zu stehen, sollte es Euer Wunsch sein, in die Reihen der Meister der Blutritter aufgenommen zu werden.", sourceObjective = "Sprecht nochmals mit Lord Solanar Blutzorn, um seine angebotene Unterstützung für Eure Aufnahme zu akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9723] = { id = 9723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geste der Hingabe", description = "Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge, {name}. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen.\n\nDiese erste Aufgabe fordert weder Eure Kampfeskunst, noch ist sie besonders ruhmreich, doch ohne solche Tätigkeiten würde der Orden auseinander fallen. Ich werde Euch eine Liste mit Gegenständen geben, die Magister Astalor Blutschwurs Männer benötigen, um uns mit Lichtenergie für unsere Magie zu versorgen.", sourceObjective = "Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lord Solanar Blutzorn in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9724] = { id = 9724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zirkel des Cenarius warnen", description = "Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.\n\nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.", sourceObjective = "Sprecht mit Amythiel Nebelgänger beim Posten des Cenarius auf der Höllenfeuerhalbinsel.", completion = "Das sind schlimme Nachrichten, die Ihr mir über die Naga in den Zangarmarschen bringt. Es war sehr klug von Ysiel, uns darüber zu informieren. Sie hat nicht vergessen, dass die Expedition nicht ohne die Unterstützung des Zirkels existieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9725] = { id = 9725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Demonstration Eurer Loyalität", description = "Wir Blutritter haben geschworen, Quel'Thalas zu verteidigen, {name}. Dies ist ein zentraler Teil unserer Ausbildung. Unsere Feinde sind wild und unbeugsam. Einzig unsere Anstrengungen und die Unterstützung unserer Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von Silbermond.\n\nIch habe einige beunruhigende Berichte über die verstärkte Präsenz der Geißel, südöstlich unserer Grenze zu den östlichen Pestländern, erhalten. Eine Kompanie Belagerungsingenieure der Geißel, mitsamt Belagerungsgerät, scheinen sich dort für einen Angriff auf die Geisterlande zu sammeln. Auf keinen Fall dürfen sie Erfolg haben.", sourceObjective = "Lord Solanar Blutzorn in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9726] = { id = 9726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt, da wir Freunde sind...", description = "Die Naga in der Enklave der Blutschuppen im Nordosten haben angefangen, unsere Leute umzubringen. Das können wir nicht tolerieren, {class}!\n\nWir schlagen vor, dass Ihr ihnen als Beweis für unsere Freundschaft eine Lektion erteilt.", sourceObjective = "Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun'tt in Sporeggar in den Zangarmarschen zurück.", progress = "Habt Ihr den Naga schon einen Besuch abgestattet?", completion = "<Gzhun'tt nickt Euch zu.>\n\nWir sind sehr erfreut, dass Ihr unsere Freundschaft bestätigt habt, {name}. Vielleicht denken die heidnischen Naga in Zukunft zweimal darüber nach, bevor sie uns belästigen, wenn wir so einen starken Verbündeten haben.", sourceObjectiveStatus = "unverified-source-field" }
